INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f66ef86-de8c-43a5-becb-26a5333aad46', '登廣武原', '登廣武原', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["廣武原西北，華夷此浩然。","地盤山入海，河遶國連天。","遠樹千門邑，高檣萬里船。","鄉心日云暮，猶在楚城邊。"]', '["廣武原西北，华夷此浩然。","地盤山入海，河遶国連天。","远樹千门邑，高檣万里船。","乡心日云暮，猶在楚城邊。"]', '诗', 'shi', '', NULL, '登廣武原 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba8b869-2b97-462c-a8db-e7eccc05567b', '觀宋州田大夫打毬', '观宋州田大夫打毬', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["白馬頓紅纓，梢毬紫袖輕。","曉冰蹄下裂，寒瓦杖頭鳴。","叉手膠黏去，分鬃線道絣。","自言無戰伐，髀肉已曾生。"]', '["白马頓紅纓，梢毬紫袖轻。","晓冰蹄下裂，寒瓦杖头鳴。","叉手膠黏去，分鬃線道絣。","自言無戰伐，髀肉已曾生。"]', '诗', 'shi', '', NULL, '觀宋州田大夫打毬 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab45eb4-da2d-4368-b3ab-01f2fbb32516', '題丹陽永泰寺練湖亭', '題丹陽永泰寺練湖亭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["小檻俯澄鮮，龍宮浸浩然。","孤光懸夜月，一片割秋天。","淺派胤沙草，餘波漂岸船。","聊當因畎澮，披拂坐潺湲。"]', '["小檻俯澄鲜，龙宮浸浩然。","孤光懸夜月，一片割秋天。","淺派胤沙草，餘波漂岸船。","聊當因畎澮，披拂坐潺湲。"]', '诗', 'shi', '', NULL, '題丹陽永泰寺練湖亭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23553ffd-b8dd-446a-80c5-2b7e4e9e734c', '題程氏書齋', '題程氏书斋', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["僻巷難通馬，深園不藉籬。","青蘿纏栢葉，紅粉墜蓮枝。","雨燕銜泥近，風魚咂網遲。","緣君尋小阮，好是更題詩。"]', '["僻巷难通马，深园不藉籬。","青蘿纏栢葉，紅粉墜蓮枝。","雨燕銜泥近，风鱼咂網遲。","緣君尋小阮，好是更題诗。"]', '诗', 'shi', '', NULL, '題程氏書齋 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc1558e5-7994-47f7-8c42-66cef9229046', '毀浮圖年逢東林寺舊', '毀浮圖年逢东林寺旧', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["可惜東林寺，空門失所依。","翻經謝靈運，畫壁陸探微。","隙地泉聲在，荒途馬跡稀。","殷勤話僧輩，未敢保儒衣。"]', '["可惜东林寺，空门失所依。","翻經謝靈運，畫壁陸探微。","隙地泉声在，荒途马跡稀。","殷勤話僧輩，未敢保儒衣。"]', '诗', 'shi', '', NULL, '毀浮圖年逢東林寺舊 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('255c4435-29ed-49a7-ac0e-2d41e75c8786', '貴池道中作', '貴池道中作', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["羸驂驅野岸，山遠路盤盤。","清露月華曉，碧江星影寒。","離羣徒長泣，去國自加餐。","霄漢寧無舊，相哀自語端。"]', '["羸驂驱野岸，山远路盤盤。","清露月华晓，碧江星影寒。","離羣徒长泣，去国自加餐。","霄漢寧無旧，相哀自語端。"]', '诗', 'shi', '', NULL, '貴池道中作 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc6dbff-6141-4453-aca6-f7af8bae486f', '喜王子載話舊', '喜王子載話旧', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["相逢青眼日，相歎白頭時。","累話三朝事，重看一局棊。","歡娛非老大，成長是嬰兒。","且盡尊中物，無煩更後期。"]', '["相逢青眼日，相歎白头时。","累話三朝事，重看一局棊。","歡娛非老大，成长是嬰兒。","且尽尊中物，無煩更後期。"]', '诗', 'shi', '', NULL, '喜王子載話舊 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0682aa38-f390-49e9-8685-b8195c3a5420', '秋日病中', '秋日病中', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["析析簷前竹，秋聲拂簟涼。","病加陰已久，愁覺夜初長。","坐拾車前子，行看肘後方。","無端憂食忌，開鏡倍萎黃。"]', '["析析簷前竹，秋声拂簟涼。","病加陰已久，愁覺夜初长。","坐拾车前子，行看肘後方。","無端憂食忌，开镜倍萎黄。"]', '诗', 'shi', '', NULL, '秋日病中 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0958fb4-f2de-40dc-a56e-7af16de68faf', '訪許用晦', '訪許用晦', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["遠郭日曛曛，停橈一訪君。","小橋通野水，高樹入江雲。","酒興曾無敵，詩情舊逸羣。","怪來音信少，五十我無聞。"]', '["远郭日曛曛，停橈一訪君。","小橋通野水，高樹入江云。","酒兴曾無敵，诗情旧逸羣。","怪来音信少，五十我無闻。"]', '诗', 'shi', '', NULL, '訪許用晦 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5502e22e-e55f-4e74-9af1-31f64cef2223', '題海鹽南館', '題海鹽南館', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["故人營此地，臺館尚依依。","黑夜山魈語，黃昏海燕歸。","舊陰楊葉在，殘雨槿花稀。","無復南亭賞，高簷紅燭輝。"]', '["故人營此地，台館尚依依。","黑夜山魈語，黄昏海燕归。","旧陰楊葉在，殘雨槿花稀。","無复南亭賞，高簷紅燭輝。"]', '诗', 'shi', '', NULL, '題海鹽南館 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cca6f72-4783-4d6e-99d1-08f6cd768459', '晚秋江上作', '晚秋江上作', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬里窮秋客，蕭條對落暉。","煙霞山鳥散，風雨廟神歸。","地遠蛩聲切，天長鴈影稀。","那堪正砧杵，幽思想寒衣。"]', '["万里窮秋客，蕭條对落暉。","煙霞山鸟散，风雨廟神归。","地远蛩声切，天长鴈影稀。","那堪正砧杵，幽思想寒衣。"]', '诗', 'shi', '', NULL, '晚秋江上作 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffaf9870-e688-45d5-94ed-d66d4843783e', '吳宮曲', '吳宮曲', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日下苑西宮，花飄香徑紅。","玉釵斜白燕，羅帶弄青蟲。","皓齒初含雪，柔枝欲斷風。","可憐傾國豔，誰信女爲戎。"]', '["日下苑西宮，花飄香徑紅。","玉釵斜白燕，羅带弄青蟲。","皓齒初含雪，柔枝欲斷风。","可怜傾国豔，誰信女爲戎。"]', '诗', 'shi', '', NULL, '吳宮曲 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4869ef2f-3ebd-45f2-84d9-4235d3047681', '賦昭君塚', '賦昭君塚', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬里關山塚，明妃舊死心。","恨爲秋色晚，愁結暮雲陰。","夜切胡風起，天高漢月臨。","已知無玉貌，何事送黃金。"]', '["万里关山塚，明妃旧死心。","恨爲秋色晚，愁結暮云陰。","夜切胡风起，天高漢月臨。","已知無玉貌，何事送黄金。"]', '诗', 'shi', '', NULL, '賦昭君塚 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b2ef31a-a526-458d-997a-cf47b28081ce', '哭汴州陸大夫', '哭汴州陸大夫', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["利劒太堅操，何妨拔一毛。","冤深陸機霧，憤積伍員濤。","直道非無驗，明時不錄勞。","誰當青史上，卒爲顯詞褒。"]', '["利劒太堅操，何妨拔一毛。","冤深陸機霧，憤積伍員濤。","直道非無驗，明时不錄勞。","誰當青史上，卒爲显词褒。"]', '诗', 'shi', '', NULL, '哭汴州陸大夫 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44bd0cd6-7abf-4c99-89c9-207af5f06fb2', '晚夏歸別業', '晚夏归別業', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古岸扁舟晚，荒園一徑微。","鳥啼新果熟，花落故人稀。","宿潤侵苔甃，斜陽照竹扉。","相逢盡鄉老，無復話時機。"]', '["古岸扁舟晚，荒园一徑微。","鸟啼新果熟，花落故人稀。","宿潤侵苔甃，斜陽照竹扉。","相逢尽乡老，無复話时機。"]', '诗', 'shi', '', NULL, '晚夏歸別業 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22ec3a40-03e1-4ed4-b676-461cb5413f53', '公子行', '公子行', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["春色滿城池，杯盤著處移。","鐙金斜鴈子，鞍帕嫩鵝兒。","買笑歌桃李，尋歌折柳枝。","可憐明月夜，長是管弦隨。"]', '["春色满城池，杯盤著处移。","鐙金斜鴈子，鞍帕嫩鵝兒。","買笑歌桃李，尋歌折柳枝。","可怜明月夜，长是管弦隨。"]', '诗', 'shi', '', NULL, '公子行 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71770c5a-2ae6-438e-96f6-0e98dcdb8c3f', '題曾氏園林', '題曾氏园林', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["十畝長堤宅，蕭疎半老槐。","醉眠風卷簟，棋罷月移堦。","斫樹遺桑斧，澆花濕笋鞋。","還將齊物論，終歲自安排。"]', '["十畝长堤宅，蕭疎半老槐。","醉眠风卷簟，棋罷月移堦。","斫樹遺桑斧，澆花濕笋鞋。","還將齊物論，終歲自安排。"]', '诗', 'shi', '', NULL, '題曾氏園林 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dd04cce-7799-4b5c-b4ea-a675bc2517e0', '讀始興公傳', '读始兴公傳', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["歿世議方存，昇平道幾論。","詩情光日月，筆力動乾坤。","亂首光雄筭，朝綱在典墳。","明時封禪績，山下見丘門。"]', '["歿世議方存，昇平道幾論。","诗情光日月，笔力动乾坤。","亂首光雄筭，朝綱在典墳。","明时封禪績，山下见丘门。"]', '诗', 'shi', '', NULL, '讀始興公傳 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e7282c-6608-491e-b386-79c4c22528be', '中秋月', '中秋月', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["碧落桂含姿，清秋是素期。","一年逢好夜，萬里見明時。","絕域行應久，高城下更遲。"]', '["碧落桂含姿，清秋是素期。","一年逢好夜，万里见明时。","絕域行應久，高城下更遲。"]', '诗', 'shi', '', NULL, '中秋月 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0468380b-83f8-4ea8-bf36-e95d71bc7b6a', '江西道中作三首 一', '江西道中作三首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日落江村遠，煙霞度幾重。","問人孤驛路，驅馬亂山峰。","夜入霜林火，寒生水寺鐘。","淒涼哭途意，行處又饑凶。"]', '["日落江村远，煙霞度幾重。","问人孤驛路，驱马亂山峰。","夜入霜林火，寒生水寺鐘。","淒涼哭途意，行处又饑凶。"]', '诗', 'shi', '', NULL, '江西道中作三首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c56496ca-aa35-4ede-8617-223b709a085f', '江西道中作三首 二', '江西道中作三首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["西江江上月，遠遠照征衣。","夜色草中網，秋聲林外機。","渚田牛路熟，石岸客船稀。","無復是鄉井，鷓鴣聊自飛。"]', '["西江江上月，远远照征衣。","夜色草中網，秋声林外機。","渚田牛路熟，石岸客船稀。","無复是乡井，鷓鴣聊自飞。"]', '诗', 'shi', '', NULL, '江西道中作三首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d6cf905-0e0f-470c-99eb-aeac30da4387', '江西道中作三首 三', '江西道中作三首 三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["秋灘一望平，遠遠見山城。","落日啼烏桕，空林露寄生。","燒畬殘火色，盪槳夜溪聲。","況是曾遊處，桑田小變更。"]', '["秋灘一望平，远远见山城。","落日啼烏桕，空林露寄生。","燒畬殘火色，盪槳夜溪声。","況是曾游处，桑田小变更。"]', '诗', 'shi', '', NULL, '江西道中作三首 三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bac9f9a-7997-4257-b489-4f545b3a8326', '題常州水西館', '題常州水西館', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["隟地叢筠植，修廊列堵環。","樓臺疎占水，岡岸遠成山。","盡日草深映，無風舟自閑。","聊當俟芳夕，一泛芰荷間。"]', '["隟地叢筠植，修廊列堵环。","楼台疎占水，岡岸远成山。","尽日草深映，無风舟自闲。","聊當俟芳夕，一泛芰荷间。"]', '诗', 'shi', '', NULL, '題常州水西館 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f17426ee-fed4-4748-86f3-0797f4b4729e', '題李瀆山居玉潭', '題李瀆山居玉潭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古樹千年色，蒼崖百尺陰。","髮寒泉氣靜，神駭玉光沉。","上穴青冥小，中連碧海深。","何當煙月下，一聽夜龍吟。"]', '["古樹千年色，蒼崖百尺陰。","髮寒泉氣静，神駭玉光沉。","上穴青冥小，中連碧海深。","何當煙月下，一听夜龙吟。"]', '诗', 'shi', '', NULL, '題李瀆山居玉潭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca936e1-9ae3-4381-9cff-944ef52ae7f4', '題陸墉金沙洞居', '題陸墉金沙洞居', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["東溪泉一眼，歸臥愜高疎。","決水金沙靜，梯雲石壁虛。","細吟搔短髮，深話笑長裾。","莫道遺名品，嘗聞入洛初。"]', '["东溪泉一眼，归臥愜高疎。","決水金沙静，梯云石壁虛。","細吟搔短髮，深話笑长裾。","莫道遺名品，嘗闻入洛初。"]', '诗', 'shi', '', NULL, '題陸墉金沙洞居 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d091a80-4b04-4182-adc8-67134550ec8e', '題陸敦禮山居伏牛潭', '題陸敦禮山居伏牛潭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["伏牛真怪事，餘勝幾人諳。","日彩沉青壁，煙容靜碧潭。","泛心何慮冷，漱齒詎忘甘。","幸挈壺中物，期君正興酣。"]', '["伏牛真怪事，餘勝幾人諳。","日彩沉青壁，煙容静碧潭。","泛心何慮冷，漱齒詎忘甘。","幸挈壺中物，期君正兴酣。"]', '诗', 'shi', '', NULL, '題陸敦禮山居伏牛潭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63de0ccb-8500-4ba7-aa56-9ed242c13c55', '旅次石頭岸', '旅次石头岸', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["行行石頭岸，身事兩相違。","舊國日邊遠，故人江上稀。","水聲寒不盡，山色暮相依。","惆悵未成語，數行鵶又飛。"]', '["行行石头岸，身事兩相違。","旧国日邊远，故人江上稀。","水声寒不尽，山色暮相依。","惆悵未成語，數行鵶又飞。"]', '诗', 'shi', '', NULL, '旅次石頭岸 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2b0b0f1-ab53-4073-ae79-25809269c906', '觀宋州于使君家樂琵琶', '观宋州于使君家乐琵琶', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["歷歷四弦分，重來上界聞。","玉盤飛夜雹，金磬入秋雲。","隴霧笳凝水，砂風鴈咽羣。","不堪天塞恨，青塚是昭君。"]', '["歷歷四弦分，重来上界闻。","玉盤飞夜雹，金磬入秋云。","隴霧笳凝水，砂风鴈咽羣。","不堪天塞恨，青塚是昭君。"]', '诗', 'shi', '', NULL, '觀宋州于使君家樂琵琶 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('242d5465-f3be-4024-837b-98481381a915', '箏', '箏', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["綽綽下雲煙，微收皓腕鮮。","夜風生碧柱，春水咽紅弦。","翠佩輕猶觸，鶯枝澀未遷。","芳音何更妙，清月共嬋娟。"]', '["綽綽下云煙，微收皓腕鲜。","夜风生碧柱，春水咽紅弦。","翠佩轻猶觸，鶯枝澀未遷。","芳音何更妙，清月共嬋娟。"]', '诗', 'shi', '', NULL, '箏 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fabbd19f-4b61-4c3a-98a9-e00e97fafc96', '歌', '歌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一夜列三清，聞歌曲阜城。","雪飛紅燼影，珠貫碧雲聲。","皓齒嬌微發，青蛾怨自生。","不知新弟子，誰解囀喉輕。"]', '["一夜列三清，闻歌曲阜城。","雪飞紅燼影，珠貫碧云声。","皓齒嬌微發，青蛾怨自生。","不知新弟子，誰解囀喉轻。"]', '诗', 'shi', '', NULL, '歌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b25b532b-b89c-45aa-84c7-af0093a606da', '笙', '笙', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["董雙成一妙，歷歷韻風篁。","清露鶴聲遠，碧雲仙吹長。","氣侵銀項濕，膏胤漆瓢香。","曲罷不知處，巫山空夕陽。"]', '["董雙成一妙，歷歷韻风篁。","清露鹤声远，碧云仙吹长。","氣侵銀項濕，膏胤漆瓢香。","曲罷不知处，巫山空夕陽。"]', '诗', 'shi', '', NULL, '笙 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e78a10e-17cb-43ab-b509-55724b206df9', '五弦', '五弦', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["小小月輪中，斜抽半袖紅。","玉瓶秋滴水，珠箔夜懸風。","徵調侵弦乙，商聲過指攏。","只愁纔曲罷，雲雨去巴東。"]', '["小小月輪中，斜抽半袖紅。","玉瓶秋滴水，珠箔夜懸风。","徵調侵弦乙，商声過指攏。","只愁纔曲罷，云雨去巴东。"]', '诗', 'shi', '', NULL, '五弦 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3917e030-def4-4749-8c3f-e04262954563', '𥷑篥', '𥷑篥', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一管妙清商，纖紅玉指長。","雪藤新換束，霞錦旋抽囊。","併揭聲猶遠，深含曲未央。","坐中知密顧，微笑是周郎。"]', '["一管妙清商，纖紅玉指长。","雪藤新換束，霞錦旋抽囊。","併揭声猶远，深含曲未央。","坐中知密顧，微笑是周郎。"]', '诗', 'shi', '', NULL, '𥷑篥 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40dbe539-a4d5-4dbf-accb-519472d8e09f', '笛', '笛', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紫清人一管，吹在月堂中。","鴈起雪雲夕，龍吟煙水空。","虜塵深漢地，羌思切邊風。","試弄陽春曲，西園桃已紅。"]', '["紫清人一管，吹在月堂中。","鴈起雪云夕，龙吟煙水空。","虜塵深漢地，羌思切邊风。","試弄陽春曲，西园桃已紅。"]', '诗', 'shi', '', NULL, '笛 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46245022-d7dc-4bff-806e-5c1c8f516c8d', '舞', '舞', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["荆臺呈妙舞，雲雨半羅衣。","褭褭腰疑折，褰褰袖欲飛。","霧輕紅躑躅，風豔紫薔薇。","強許傳新態，人間弟子稀。"]', '["荆台呈妙舞，云雨半羅衣。","褭褭腰疑折，褰褰袖欲飞。","霧轻紅躑躅，风豔紫薔薇。","強許傳新態，人间弟子稀。"]', '诗', 'shi', '', NULL, '舞 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb3cd026-e2b5-4438-926d-4f72a4a972b3', '箜篌', '箜篌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["星漢夜牢牢，深簾調更高。","亂流公莫度，沉骨嫗空嘷。","向月輕輪甲，迎風重紉絛。","不堪聞別引，滄海恨波濤。"]', '["星漢夜牢牢，深簾調更高。","亂流公莫度，沉骨嫗空嘷。","向月轻輪甲，迎风重紉絛。","不堪闻別引，滄海恨波濤。"]', '诗', 'shi', '', NULL, '箜篌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78635faa-875b-4359-a027-9381da646165', '簫', '簫', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["清籟遠愔愔，秦樓夜思深。","碧空人已去，滄海鳳難尋。","杳妙和雲絕，依微向水沉。","還將九成意，高閣竚芳音。"]', '["清籟远愔愔，秦楼夜思深。","碧空人已去，滄海鳳难尋。","杳妙和云絕，依微向水沉。","還將九成意，高閣竚芳音。"]', '诗', 'shi', '', NULL, '簫 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e0fcac2-79cb-4774-8307-2f5831ef41a9', '夕次桐廬', '夕次桐廬', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["百里清溪口，扁舟此去過。","晚潮風勢急，寒葉雨聲多。","戍出山頭鼓，樵通竹裏歌。","不堪無酒夜，廻首夢煙波。"]', '["百里清溪口，扁舟此去過。","晚潮风勢急，寒葉雨声多。","戍出山头鼓，樵通竹裏歌。","不堪無酒夜，廻首梦煙波。"]', '诗', 'shi', '', NULL, '夕次桐廬 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2666512f-a08f-4a6a-9043-4d053b499361', '入潼關', '入潼关', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["都城三百里，雄險此廻環。","地勢遙尊嶽，河流側讓關。","秦皇曾虎視，漢祖昔龍顏。","何處梟兇輩，干戈自不閑。"]', '["都城三百里，雄險此廻环。","地勢遙尊嶽，河流側讓关。","秦皇曾虎視，漢祖昔龙顏。","何处梟兇輩，干戈自不闲。"]', '诗', 'shi', '', NULL, '入潼關 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab580f7a-8008-4b08-9abd-4b4f9b9b5b3c', '南宮歎亦述玄宗追恨太真妃事', '南宮歎亦述玄宗追恨太真妃事', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["北陸冰初結，南宮漏更長。","何勞却睡草，不驗返魂香。","月隱仙娥豔，風殘夢蝶揚。","徒悲舊行跡，一夜玉堦霜。"]', '["北陸冰初結，南宮漏更长。","何勞却睡草，不驗返魂香。","月隐仙娥豔，风殘梦蝶揚。","徒悲旧行跡，一夜玉堦霜。"]', '诗', 'shi', '', NULL, '南宮歎亦述玄宗追恨太真妃事 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83e71318-7dd4-4abc-91cb-e6b92c9c5afc', '題平望驛', '題平望驛', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一派吳興水，西來此驛分。","路遙經幾日，身去是孤雲。","雨氣朝忙蟻，雷聲夜聚蚊。","何堪秋草色，到處重離羣。"]', '["一派吳兴水，西来此驛分。","路遙經幾日，身去是孤云。","雨氣朝忙蟻，雷声夜聚蚊。","何堪秋草色，到处重離羣。"]', '诗', 'shi', '', NULL, '題平望驛 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a95f8c7b-64d8-40e2-8bd9-ecf99200dde3', '隋宮懷古', '隋宮懷古', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["廢宮深苑路，煬帝此東行。","往事餘山色，流年是水聲。","古牆丹雘盡，深棟黑煤生。","惆悵從今客，經過未了情。"]', '["廢宮深苑路，煬帝此东行。","往事餘山色，流年是水声。","古牆丹雘尽，深棟黑煤生。","惆悵從今客，經過未了情。"]', '诗', 'shi', '', NULL, '隋宮懷古 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb5e6b66-7858-4ec5-9eb5-a591cdb04434', '偶蘇求至話別', '偶蘇求至話別', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["幾年滄海別，萬里白頭吟。","夜月江流闊，春雲嶺路深。","珠繁楊氏果，翠耀孔家禽。","無復天南夢，相思空樹林。"]', '["幾年滄海別，万里白头吟。","夜月江流闊，春云嶺路深。","珠繁楊氏果，翠耀孔家禽。","無复天南梦，相思空樹林。"]', '诗', 'shi', '', NULL, '偶蘇求至話別 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4603701-24f5-41d8-84c6-ff0a8fb96d25', '秋霽', '秋霽', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["垂老歸休意，棲棲陋巷中。","暗燈棋子落，殘語酒瓶空。","滴羃侵簷露，虛疎入檻風。","何妨一蟬嘒，自抱木蘭叢。"]', '["垂老归休意，棲棲陋巷中。","暗灯棋子落，殘語酒瓶空。","滴羃侵簷露，虛疎入檻风。","何妨一蟬嘒，自抱木蘭叢。"]', '诗', 'shi', '', NULL, '秋霽 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f8fd6c9-2031-49c5-a39e-3c843727fa8c', '詠史二首 一', '詠史二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["漢代非良計，西戎世世塵。","無何求善馬，不筭苦生民。","外國讐虛結，中華憤莫伸。","却教爲後恥，昭帝遠和親。"]', '["漢代非良計，西戎世世塵。","無何求善马，不筭苦生民。","外国讐虛結，中华憤莫伸。","却教爲後恥，昭帝远和親。"]', '诗', 'shi', '', NULL, '詠史二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe3140f6-002e-4bfd-b105-77c568031625', '詠史二首 二', '詠史二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["留名魯連去，於世絕遺音。","盡愛聊城下，寧知滄海深。","偶然飛一箭，無事在千金。","迴望凌煙閣，何人是此心。"]', '["留名魯連去，於世絕遺音。","尽愛聊城下，寧知滄海深。","偶然飞一箭，無事在千金。","迴望凌煙閣，何人是此心。"]', '诗', 'shi', '', NULL, '詠史二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90a049e-fe22-46f0-bf37-11d1ebca0068', '洞房燕', '洞房燕', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["清曉洞房開，佳人喜燕來。","乍疑釵上動，輕似掌中迴。","暗語臨窗戶，深窺傍鏡臺。","新妝正含思，莫拂畫梁埃。"]', '["清晓洞房开，佳人喜燕来。","乍疑釵上动，轻似掌中迴。","暗語臨窗戶，深窺傍镜台。","新妝正含思，莫拂畫梁埃。"]', '诗', 'shi', '', NULL, '洞房燕 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1be19bff-39d7-4e19-b4c6-708e8bb4564b', '答僧贈柱杖', '答僧贈柱杖', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["千迴掌上橫，珍重遠方情。","客問何人與，閩僧寄一莖。","畫空疑未決，卓地計初成。","幸以文堪採，扶持力不輕。"]', '["千迴掌上橫，珍重远方情。","客问何人與，閩僧寄一莖。","畫空疑未決，卓地計初成。","幸以文堪採，扶持力不轻。"]', '诗', 'shi', '', NULL, '答僧贈柱杖 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e1cb3e8-eede-4bcc-8436-afad4811972e', '鷺鷥', '鷺鷥', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["深窺思不窮，揭趾淺沙中。","一點山光淨，孤飛潭影空。","暗棲松葉露，雙下蓼花風。","好是滄波侶，垂絲趣亦同。"]', '["深窺思不窮，揭趾淺沙中。","一点山光淨，孤飞潭影空。","暗棲松葉露，雙下蓼花风。","好是滄波侶，垂絲趣亦同。"]', '诗', 'shi', '', NULL, '鷺鷥 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31739c8a-53cb-453e-ac6f-882d7d4a0e35', '塞下', '塞下', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬里配長征，連年慣野營。","入羣來揀馬，拋伴去擒生。","箭插雕翎闊，弓盤鵲角輕。","問看行近遠，西去受降城。"]', '["万里配长征，連年慣野營。","入羣来揀马，拋伴去擒生。","箭插雕翎闊，弓盤鵲角轻。","问看行近远，西去受降城。"]', '诗', 'shi', '', NULL, '塞下 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f9d3623-c289-42c7-bb56-173019420a88', '憶雲陽宅', '憶云陽宅', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一別雲陽宅，深愁度歲華。","翠濃春檻柳，紅滿夜庭花。","鳥影垂纖竹，魚行踐淺沙。","聊當因寤寐，歸思浩無涯。"]', '["一別云陽宅，深愁度歲华。","翠濃春檻柳，紅满夜庭花。","鸟影垂纖竹，鱼行踐淺沙。","聊當因寤寐，归思浩無涯。"]', '诗', 'shi', '', NULL, '憶雲陽宅 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d91195b6-b050-4d82-8f0c-eea6f7621ee2', '題造微禪師院', '題造微禪師院', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["夜香聞偈後，岑寂掩雙扉。","照竹燈和雪，穿雲月到衣。","草堂疎磬斷，江寺故人稀。","唯憶江南雨，春風獨鳥歸。"]', '["夜香闻偈後，岑寂掩雙扉。","照竹灯和雪，穿云月到衣。","草堂疎磬斷，江寺故人稀。","唯憶江南雨，春风独鸟归。"]', '诗', 'shi', '', NULL, '題造微禪師院 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed6c65a3-54f8-44c0-8efc-4d2139835842', '酬武藴之乙丑之歲始見華髮余自悲遂成繼和', '酬武藴之乙丑之歲始见华髮余自悲遂成繼和', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["賈生年尚少，華髮近相侵。","不是流光促，因緣別恨深。","憐君成苦調，感我獨長吟。","豈料清秋日，星星共映簪。"]', '["賈生年尚少，华髮近相侵。","不是流光促，因緣別恨深。","怜君成苦調，感我独长吟。","豈料清秋日，星星共映簪。"]', '诗', 'shi', '', NULL, '酬武藴之乙丑之歲始見華髮余自悲遂成繼和 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0389ac55-6fe0-4775-a662-1e40f2bcca50', '題萬道人禪房', '題万道人禪房', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["何處鑿禪壁，西南江上峰。","殘陽過遠水，落葉滿疎鐘。","世事靜中去，道心塵外逢。","欲知情不動，牀下虎留蹤。"]', '["何处鑿禪壁，西南江上峰。","殘陽過远水，落葉满疎鐘。","世事静中去，道心塵外逢。","欲知情不动，牀下虎留蹤。"]', '诗', 'shi', '', NULL, '題萬道人禪房 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1239a628-d570-4564-8b09-26069f02d4d0', '病後訪山客', '病後訪山客', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["久病倦衾枕，獨行來訪君。","因逢歸馬客，共對出溪雲。","新月坐中見，暮蟬愁處聞。","相歡貴無事，莫想路歧分。"]', '["久病倦衾枕，独行来訪君。","因逢归马客，共对出溪云。","新月坐中见，暮蟬愁处闻。","相歡貴無事，莫想路歧分。"]', '诗', 'shi', '', NULL, '病後訪山客 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b2ecfea-a5dd-40ea-86f9-1b8d518fca48', '題松汀驛', '題松汀驛', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["山色遠含空，蒼茫澤國東。","海明先見日，江白逈聞風。","鳥道高原去，人煙小徑通。","那知舊遺逸，不在五湖中。"]', '["山色远含空，蒼茫澤国东。","海明先见日，江白逈闻风。","鸟道高原去，人煙小徑通。","那知旧遺逸，不在五湖中。"]', '诗', 'shi', '', NULL, '題松汀驛 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('022b9dfe-8b9e-4a06-94c4-fc80ad85d73c', '處士隱居', '处士隐居', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["斜日半飛閤，高簾輕翳空。","清香芙蓉水，碧冷琅玕風。","絕岸派沿洑，修廊趾崇隆。","唯當餌仙朮，坐作朱顏翁。"]', '["斜日半飞閤，高簾轻翳空。","清香芙蓉水，碧冷琅玕风。","絕岸派沿洑，修廊趾崇隆。","唯當餌仙朮，坐作朱顏翁。"]', '诗', 'shi', '', NULL, '處士隱居 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7b46a9e-9dd8-444c-baa2-645422ee243a', '早春錢塘湖晚眺', '早春錢塘湖晚眺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["落日下林坂，撫襟睇前蹤。","輕澌流迴浦，殘雪明高峰。","仰視天宇曠，俯登雲樹重。","聊當問真界，昨夜西巒鐘。"]', '["落日下林坂，撫襟睇前蹤。","轻澌流迴浦，殘雪明高峰。","仰視天宇曠，俯登云樹重。","聊當问真界，昨夜西巒鐘。"]', '诗', 'shi', '', NULL, '早春錢塘湖晚眺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a333076f-418d-4a0e-b2df-d6cb6cc2d3bf', '濠州水館', '濠州水館', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["高閣去煩燠，客心遂安舒。","清流中浴鳥，白石下遊魚。","秋樹色凋翠，夜橋聲褭虛。","南軒更何待，坐見玉蟾蜍。"]', '["高閣去煩燠，客心遂安舒。","清流中浴鸟，白石下游鱼。","秋樹色凋翠，夜橋声褭虛。","南軒更何待，坐见玉蟾蜍。"]', '诗', 'shi', '', NULL, '濠州水館 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3a2fec4-5ca6-49b4-b91f-d15b6183b1e0', '石頭城寺', '石头城寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["山勢抱煙光，重門突兀傍。","連簷金像閣，半壁石龕廊。","碧樹藂高頂，清池占下方。","徒悲宦遊意，盡日老僧房。"]', '["山勢抱煙光，重门突兀傍。","連簷金像閣，半壁石龕廊。","碧樹藂高頂，清池占下方。","徒悲宦游意，尽日老僧房。"]', '诗', 'shi', '', NULL, '石頭城寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d98867a-8ee3-455c-937e-e139e8872671', '傷遷客歿南中', '傷遷客歿南中', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["故人何處歿，謫宦極南天。","遠地身狼狽，窮途事果然。","白鬚纔過海，丹旐却歸船。","腸斷相逢路，新來客又遷。"]', '["故人何处歿，謫宦極南天。","远地身狼狽，窮途事果然。","白鬚纔過海，丹旐却归船。","腸斷相逢路，新来客又遷。"]', '诗', 'shi', '', NULL, '傷遷客歿南中 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('debd62ef-a8e3-4f3a-a5c1-50f9e43627fa', '烏夜啼', '烏夜啼', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["忽忽南飛返，危絲共怨悽。","暗霜移樹宿，殘夜遶枝啼。","咽絕聲重敘，愔淫思乍迷。","不妨還報喜，悞使玉顏低。"]', '["忽忽南飞返，危絲共怨悽。","暗霜移樹宿，殘夜遶枝啼。","咽絕声重敘，愔淫思乍迷。","不妨還報喜，悞使玉顏低。"]', '诗', 'shi', '', NULL, '烏夜啼 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e6ffa3-42a8-40da-b43b-b91972fc3d1e', '題潤州金山寺', '題潤州金山寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一宿金山寺，超然離世羣。","僧歸夜船月，龍出曉堂雲。","樹色中流見，鐘聲兩岸聞。","翻思在朝市，終日醉醺醺。"]', '["一宿金山寺，超然離世羣。","僧归夜船月，龙出晓堂云。","樹色中流见，鐘声兩岸闻。","翻思在朝市，終日醉醺醺。"]', '诗', 'shi', '', NULL, '題潤州金山寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d48d14df-81c4-4f6a-aeac-deaf91f0aa63', '題潤州甘露寺', '題潤州甘露寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["千重構橫險，高步出塵埃。","日月光先見，江山勢盡來。","冷雲歸水石，清露滴樓臺。","況是東溟上，平生意一開。"]', '["千重構橫險，高步出塵埃。","日月光先见，江山勢尽来。","冷云归水石，清露滴楼台。","況是东溟上，平生意一开。"]', '诗', 'shi', '', NULL, '題潤州甘露寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01d61dfa-6c6e-421d-a5b3-c7db62f9d7fe', '題杭州孤山寺', '題杭州孤山寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["樓臺聳碧岑，一徑入湖心。","不雨山長潤，無雲水自陰。","斷橋荒蘚澀，空院落花深。","猶憶西窗月，鐘聲在北林。"]', '["楼台聳碧岑，一徑入湖心。","不雨山长潤，無云水自陰。","斷橋荒蘚澀，空院落花深。","猶憶西窗月，鐘声在北林。"]', '诗', 'shi', '', NULL, '題杭州孤山寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00437c8e-467d-42ab-95f2-8f5861dcac31', '題餘杭縣龍泉觀', '題餘杭縣龙泉观', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["四迴山一面，臺殿已嵯峨。","中路見山遠，上方行石多。","天晴花氣漫，地煖鳥音和。","徒漱葛仙井，此生其奈何。"]', '["四迴山一面，台殿已嵯峨。","中路见山远，上方行石多。","天晴花氣漫，地煖鸟音和。","徒漱葛仙井，此生其奈何。"]', '诗', 'shi', '', NULL, '題餘杭縣龍泉觀 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84c7b669-bfce-421f-97f7-1c1c2c830deb', '題徑山大覺禪師影堂', '題徑山大覺禪師影堂', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["超然彼岸人，一徑謝微塵。","見相即非相，觀身豈是身。","空門性未滅，舊里化猶新。","謾指堂中影，誰言影似真。"]', '["超然彼岸人，一徑謝微塵。","见相即非相，观身豈是身。","空门性未滅，旧里化猶新。","謾指堂中影，誰言影似真。"]', '诗', 'shi', '', NULL, '題徑山大覺禪師影堂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edce7bfc-ef8e-4368-9b92-7a1a5ab22a9c', '題濠州鍾離寺', '題濠州鍾離寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["遙遙東郭寺，數里占原田。","遠岫碧光合，長淮清派連。","院藏歸鳥樹，鐘到落帆船。","唯羨空門叟，棲心盡百年。"]', '["遙遙东郭寺，數里占原田。","远岫碧光合，长淮清派連。","院藏归鸟樹，鐘到落帆船。","唯羨空门叟，棲心尽百年。"]', '诗', 'shi', '', NULL, '題濠州鍾離寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec6c2efd-5898-4304-a7a5-cc0b53fd77ee', '秋夜宿靈隱寺師上人', '秋夜宿靈隐寺師上人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["月色荒城外，江聲野寺中。","貧知交道薄，老信釋門空。","露葉凋堦蘚，風枝戞井桐。","不妨無酒夜，閑話值生公。"]', '["月色荒城外，江声野寺中。","貧知交道薄，老信釋门空。","露葉凋堦蘚，风枝戞井桐。","不妨無酒夜，闲話值生公。"]', '诗', 'shi', '', NULL, '秋夜宿靈隱寺師上人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf00650b-5f81-4662-a1c3-6057ad702e4b', '題蘇州靈巖寺', '題蘇州靈巖寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["碧海西陵岸，吳王此盛時。","山行今佛寺，水見舊宮池。","亡國人遺恨，空門事少悲。","聊當值僧語，盡日把松枝。"]', '["碧海西陵岸，吳王此盛时。","山行今佛寺，水见旧宮池。","亡国人遺恨，空门事少悲。","聊當值僧語，尽日把松枝。"]', '诗', 'shi', '', NULL, '題蘇州靈巖寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69bcb23b-61c1-4621-8b2c-566979560625', '題蘇州楞伽寺', '題蘇州楞伽寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["樓臺山半腹，又此一經行。","樹隔夫差苑，溪連句踐城。","上坡松徑澀，深坐石池清。","況是西峰頂，淒涼故國情。"]', '["楼台山半腹，又此一經行。","樹隔夫差苑，溪連句踐城。","上坡松徑澀，深坐石池清。","況是西峰頂，淒涼故国情。"]', '诗', 'shi', '', NULL, '題蘇州楞伽寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9a7953f-cdb6-4320-8e09-e5c10ec98a38', '題蘇州思益寺', '題蘇州思益寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["四面山形斷，樓臺此逈臨。","兩峰高崪屼，一水下淫滲。","鑿石西龕小，穿松北塢深。","會當來結社，長日爲僧吟。"]', '["四面山形斷，楼台此逈臨。","兩峰高崪屼，一水下淫滲。","鑿石西龕小，穿松北塢深。","會當来結社，长日爲僧吟。"]', '诗', 'shi', '', NULL, '題蘇州思益寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b31f5017-c4eb-40c7-b471-4324303e780e', '題重居寺', '題重居寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["浮圖經近郭，長日羨僧閑。","竹徑深開院，松門遠對山。","重廊標板榜，高殿鎖金環。","更問尋雷室，西行咫尺間。"]', '["浮圖經近郭，长日羨僧闲。","竹徑深开院，松门远对山。","重廊標板榜，高殿鎖金环。","更问尋雷室，西行咫尺间。"]', '诗', 'shi', '', NULL, '題重居寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5a42c23-c204-439b-b183-beaf340447a2', '題善權寺', '題善權寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["碧峰南一寺，最勝是仙源。","峻坂依巖壁，清泉泄洞門。","金函崇寶藏，玉樹閟靈根。","寄謝香花叟，高蹤不可援。"]', '["碧峰南一寺，最勝是仙源。","峻坂依巖壁，清泉泄洞门。","金函崇寶藏，玉樹閟靈根。","寄謝香花叟，高蹤不可援。"]', '诗', 'shi', '', NULL, '題善權寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbdc815b-beef-4b44-b0fa-1827783a7311', '題南陵隱靜寺', '題南陵隐静寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["松逕上登攀，深行煙靄間。","合流廚下水，對聳殿前山。","潤壁鳥音逈，泉源僧步閑。","更憐飛一錫，天外與雲還。"]', '["松逕上登攀，深行煙靄间。","合流廚下水，对聳殿前山。","潤壁鸟音逈，泉源僧步闲。","更怜飞一錫，天外與云還。"]', '诗', 'shi', '', NULL, '題南陵隱靜寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b0ad859-5403-4a15-949d-3eca181c104b', '題丘山寺', '題丘山寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["幾代儒家業，何年佛寺碑。","地平邊海處，江出上山時。","故國人長往，空門事可知。","淒涼問禪客，身外即無爲。"]', '["幾代儒家業，何年佛寺碑。","地平邊海处，江出上山时。","故国人长往，空门事可知。","淒涼问禪客，身外即無爲。"]', '诗', 'shi', '', NULL, '題丘山寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2eb9f22-3cee-4a3c-912b-5517e5b62b0e', '題道光上人山院', '題道光上人山院', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["真僧上方界，山路正巖巖。","地僻泉長冷，亭香草不凡。","火田生白菌，煙岫老青杉。","盡日唯山水，當知律行嚴。"]', '["真僧上方界，山路正巖巖。","地僻泉长冷，亭香草不凡。","火田生白菌，煙岫老青杉。","尽日唯山水，當知律行嚴。"]', '诗', 'shi', '', NULL, '題道光上人山院 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c0b135c-2944-43fa-9f8d-710552aa51cb', '贈廬山僧', '贈廬山僧', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一室鑪峰下，荒榛手自開。","粉牌新薤葉，竹援小葱臺。","樹黑雲歸去，山明日上來。","便知心是佛，堅坐對寒灰。"]', '["一室鑪峰下，荒榛手自开。","粉牌新薤葉，竹援小葱台。","樹黑云归去，山明日上来。","便知心是佛，堅坐对寒灰。"]', '诗', 'shi', '', NULL, '贈廬山僧 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2784a5e-182e-46d2-8c43-e31f57071b05', '題惠山寺', '題惠山寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["舊宅人何在，空門客自過。","泉聲到池盡，山色上樓多。","小洞生斜竹，重堦夾細莎。","殷勤望城市，雲水暮鐘和。"]', '["旧宅人何在，空门客自過。","泉声到池尽，山色上楼多。","小洞生斜竹，重堦夾細莎。","殷勤望城市，云水暮鐘和。"]', '诗', 'shi', '', NULL, '題惠山寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c02394-0732-4cea-b2bb-c794309774fb', '題虎丘寺', '題虎丘寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["輕櫂駐廻流，門登西虎丘。","霧青山月曉，雲白海天秋。","倚殿松株澀，欹庭石片幽。","青蛾幾時墓，空色尚悠悠。"]', '["轻櫂駐廻流，门登西虎丘。","霧青山月晓，云白海天秋。","倚殿松株澀，欹庭石片幽。","青蛾幾时墓，空色尚悠悠。"]', '诗', 'shi', '', NULL, '題虎丘寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5b7b747-6561-4c1d-a7f6-a2fe20bcfa79', '題普賢寺', '題普賢寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["何人知寺路，松竹暗春山。","潭黑龍應在，巢空鶴未還。","經年來客倦，半日與僧閑。","更共嘗新茗，聞鐘笑語間。"]', '["何人知寺路，松竹暗春山。","潭黑龙應在，巢空鹤未還。","經年来客倦，半日與僧闲。","更共嘗新茗，闻鐘笑語间。"]', '诗', 'shi', '', NULL, '題普賢寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00efc79c-9bb4-422b-91ef-17b63f75e523', '題虎丘東寺', '題虎丘东寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["雲樹擁崔嵬，深行異俗埃。","寺門山外入，石壁地中開。","仰砌池光動，登樓海氣來。","傷心萬古意，金玉葬寒灰。"]', '["云樹擁崔嵬，深行異俗埃。","寺门山外入，石壁地中开。","仰砌池光动，登楼海氣来。","傷心万古意，金玉葬寒灰。"]', '诗', 'shi', '', NULL, '題虎丘東寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dee45ee-d6ab-412c-af24-f2a9eb1eac05', '題虎丘西寺', '題虎丘西寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["囂塵楚城外，一寺枕通波。","松色入門遠，岡形連院多。","花時長到處，別路半經過。","惆悵舊禪客，空房深薜蘿。"]', '["囂塵楚城外，一寺枕通波。","松色入门远，岡形連院多。","花时长到处，別路半經過。","惆悵旧禪客，空房深薜蘿。"]', '诗', 'shi', '', NULL, '題虎丘西寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05b8984a-df8b-4921-9f58-1ab8e47143aa', '題招隱寺', '題招隐寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["千年戴顒宅，佛廟此崇修。","古井人名在，清泉鹿跡幽。","竹光寒閉院，山影夜藏樓。","未得高僧旨，烟霞空暫游。"]', '["千年戴顒宅，佛廟此崇修。","古井人名在，清泉鹿跡幽。","竹光寒閉院，山影夜藏楼。","未得高僧旨，烟霞空暫游。"]', '诗', 'shi', '', NULL, '題招隱寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e3011b-1b79-4444-bb8a-8b48a73833d5', '塞下曲', '塞下曲', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["二十逐嫖姚，分兵遠戍遼。","雪迷經塞夜，冰壯渡河朝。","促放雕難下，生騎馬未調。","小儒何足問，看取劒橫腰。"]', '["二十逐嫖姚，分兵远戍遼。","雪迷經塞夜，冰壯渡河朝。","促放雕难下，生騎马未調。","小儒何足问，看取劒橫腰。"]', '诗', 'shi', '', NULL, '塞下曲 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b29b23-4f34-431a-b26b-cdcc116d485c', '宿淮陰水館', '宿淮陰水館', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["積水自成陰，昏昏月映林。","五更離浦櫂，一夜隔淮砧。","漂母鄉非遠，王孫道豈沉。","不當無健嫗，誰肯效前心。"]', '["積水自成陰，昏昏月映林。","五更離浦櫂，一夜隔淮砧。","漂母乡非远，王孫道豈沉。","不當無健嫗，誰肯效前心。"]', '诗', 'shi', '', NULL, '宿淮陰水館 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f908feb-281c-4a58-8a88-bcef641a0ded', '題小松', '題小松', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["何處斸雲煙，新移此館前。","碧姿塵不染，清影露長鮮。","聳地心纔直，凌雲操未全。","可悲人自老，何日是千年。"]', '["何处斸云煙，新移此館前。","碧姿塵不染，清影露长鲜。","聳地心纔直，凌云操未全。","可悲人自老，何日是千年。"]', '诗', 'shi', '', NULL, '題小松 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06798167-53e9-4e1b-b84f-b150edd78eac', '夏日梅溪館寄龐舍人', '夏日梅溪館寄龐舍人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["東陽賓禮重，高館望行期。","埽簟因松葉，篸瓜使竹枝。","捲簾聞鳥近，翻枕夢人遲。","坐聽津橋說，今營太守碑。"]', '["东陽賓禮重，高館望行期。","埽簟因松葉，篸瓜使竹枝。","捲簾闻鸟近，翻枕梦人遲。","坐听津橋说，今營太守碑。"]', '诗', 'shi', '', NULL, '夏日梅溪館寄龐舍人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1baf79d-303c-4618-880a-4def8c930a78', '感河上兵', '感河上兵', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一聞河塞上，非是欲權兵。","首尾誠須畏，膏肓慎勿輕。","多門徒可入，盡室且思行。","莫爲無媒者，滄浪不濯纓。"]', '["一闻河塞上，非是欲權兵。","首尾誠須畏，膏肓慎勿轻。","多门徒可入，尽室且思行。","莫爲無媒者，滄浪不濯纓。"]', '诗', 'shi', '', NULL, '感河上兵 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9386657b-8cda-4db1-858e-5a8383d6314d', '贈淮南將', '贈淮南將', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["年少好風情，垂鞭眦睚行。","帶金獅子小，裘錦麒麟獰。","揀匠裝銀鐙，堆錢買鈿箏。","李陵雖效死，時論亦輕生。"]', '["年少好风情，垂鞭眦睚行。","带金獅子小，裘錦麒麟獰。","揀匠裝銀鐙，堆錢買鈿箏。","李陵雖效死，时論亦轻生。"]', '诗', 'shi', '', NULL, '贈淮南將 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('306a632c-38f4-4f3e-836b-dfa2bf80fcfc', '題惠昌上人', '題惠昌上人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["半巖開一室，香穟細氛氳。","石上漱秋水，月中行夏雲。","律持僧講疏，經誦梵書文。","好是風廊下，遙遙挂褐裙。"]', '["半巖开一室，香穟細氛氳。","石上漱秋水，月中行夏云。","律持僧講疏，經誦梵书文。","好是风廊下，遙遙挂褐裙。"]', '诗', 'shi', '', NULL, '題惠昌上人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bf0531a-3cb5-4466-a9cc-f6c4f17ff105', '塞上曲', '塞上曲', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["邊風捲地時，日暮帳初移。","磧逈三通角，山寒一點旗。","連收榻索馬，引滿射雕兒。","莫道功勳細，將軍昔戍師。"]', '["邊风捲地时，日暮帳初移。","磧逈三通角，山寒一点旗。","連收榻索马，引满射雕兒。","莫道功勳細，將軍昔戍師。"]', '诗', 'shi', '', NULL, '塞上曲 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32bc27d8-4816-4861-8d31-7f16bfee4a7b', '折楊柳', '折楊柳', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紅粉青樓曙，垂楊仲月春。","懷君重攀折，非妾妬腰身。","舞帶縈絲斷，嬌娥向葉嚬。","橫吹凡幾曲，獨自最愁人。"]', '["紅粉青楼曙，垂楊仲月春。","懷君重攀折，非妾妬腰身。","舞带縈絲斷，嬌娥向葉嚬。","橫吹凡幾曲，独自最愁人。"]', '诗', 'shi', '', NULL, '折楊柳 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('457215d8-5b31-4dd1-a740-44782cc8d86e', '採桑', '採桑', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["自古多征戰，由來尚甲兵。","長驅千里去，一舉兩番平。","按劒從沙漠，歌謠滿帝京。","寄言天下將，須立武功名。"]', '["自古多征戰，由来尚甲兵。","长驱千里去，一舉兩番平。","按劒從沙漠，歌謠满帝京。","寄言天下將，須立武功名。"]', '诗', 'shi', '', NULL, '採桑 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('611b2dc6-4b63-43d0-abd9-756e35877aa1', '禪智寺', '禪智寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["寶殿依山嶮，臨虛勢若吞。","畫簷齊木末，香砌壓雲根。","遠景窗中岫，孤煙竹裏村。","憑高聊一望，鄉思隔吳門。"]', '["寶殿依山嶮，臨虛勢若吞。","畫簷齊木末，香砌壓云根。","远景窗中岫，孤煙竹裏村。","憑高聊一望，乡思隔吳门。"]', '诗', 'shi', '', NULL, '禪智寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65a085c2-ae00-48e8-bd5b-e90e75ac846b', '寄題商洛王隱居', '寄題商洛王隐居', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["近逢商洛口，知爾坐南塘。","草閣平春水，柴門掩夕陽。","隨蜂收野蜜，尋麝採生香。","更憶前年醉，松花滿石牀。"]', '["近逢商洛口，知爾坐南塘。","草閣平春水，柴门掩夕陽。","隨蜂收野蜜，尋麝採生香。","更憶前年醉，松花满石牀。"]', '诗', 'shi', '', NULL, '寄題商洛王隱居 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c262e600-c86e-4305-a903-07c6c0095a5d', '送客歸湘楚', '送客归湘楚', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["無辭一杯酒，昔日與君深。","秋色換歸鬢，曙光生別心。","桂花山廟冷，楓樹水樓陰。","此路千餘里，應勞楚客吟。"]', '["無辞一杯酒，昔日與君深。","秋色換归鬢，曙光生別心。","桂花山廟冷，楓樹水楼陰。","此路千餘里，應勞楚客吟。"]', '诗', 'shi', '', NULL, '送客歸湘楚 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9a5351-1a97-4423-b912-224a05f6f7ac', '登金山寺', '登金山寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古今斯島絕，南北大江分。","水闊吞滄海，亭高宿斷雲。","返潮千澗落，啼鳥半空聞。","皆是登臨處，歸航酒半醺。"]', '["古今斯島絕，南北大江分。","水闊吞滄海，亭高宿斷云。","返潮千澗落，啼鸟半空闻。","皆是登臨处，归航酒半醺。"]', '诗', 'shi', '', NULL, '登金山寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432793dc-50bb-4dfc-8cad-af3bc0cc759f', '洛陽感寓', '洛陽感寓', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["擾擾都城曉四開，不關名利也塵埃。","千門甲第身遙入，萬里銘旌死後來。","洛水暮煙橫莽蒼，邙山秋日露崔嵬。","須知此事堪爲鏡，莫遣黃金漫作堆。"]', '["擾擾都城晓四开，不关名利也塵埃。","千门甲第身遙入，万里銘旌死後来。","洛水暮煙橫莽蒼，邙山秋日露崔嵬。","須知此事堪爲镜，莫遣黄金漫作堆。"]', '诗', 'shi', '', NULL, '洛陽感寓 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81852780-9711-4914-9ec8-02518757ca1f', '從軍行', '從軍行', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["少年金紫就光輝，直指邊城虎翼飛。","一卷旌收千騎虜，萬全身出百重圍。","黃雲斷塞尋鷹去，白草連天射鴈歸。","白首漢廷刀筆吏，丈夫功業本相依。"]', '["少年金紫就光輝，直指邊城虎翼飞。","一卷旌收千騎虜，万全身出百重圍。","黄云斷塞尋鷹去，白草連天射鴈归。","白首漢廷刀笔吏，丈夫功業本相依。"]', '诗', 'shi', '', NULL, '從軍行 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53de701e-8484-436d-96c1-baa1a45a3c05', '愛妾換馬 一', '愛妾換马 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一面妖桃千里蹄，嬌姿駿骨價應齊。","乍牽玉勒辭金棧，催整花鈿出繡閨。","去日豈無沾袂泣，歸時還有頓銜嘶。","嬋娟躞蹀春風裏，揮手搖鞭楊柳隄。"]', '["一面妖桃千里蹄，嬌姿駿骨價應齊。","乍牽玉勒辞金棧，催整花鈿出繡閨。","去日豈無沾袂泣，归时還有頓銜嘶。","嬋娟躞蹀春风裏，揮手搖鞭楊柳隄。"]', '诗', 'shi', '', NULL, '愛妾換馬 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb21aab-5fbe-48c0-a2cd-115f3f176a36', '愛妾換馬 二', '愛妾換马 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["綺閣香銷華廐空，忍將行雨換追風。","休憐柳葉雙眉翠，卻愛桃花兩耳紅。","侍宴永辭春色裏，趁朝休立漏聲中。","恩勞未盡情先盡，暗泣嘶風兩意同。"]', '["綺閣香銷华廐空，忍將行雨換追风。","休怜柳葉雙眉翠，卻愛桃花兩耳紅。","侍宴永辞春色裏，趁朝休立漏声中。","恩勞未尽情先尽，暗泣嘶风兩意同。"]', '诗', 'shi', '', NULL, '愛妾換馬 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b680d1fe-bf1e-4466-974a-de893bbf9b2a', '病宮人', '病宮人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["佳人臥病動經秋，簾幕繿縿不挂鉤。","四體強扶藤夾膝，雙鬟慵插玉搔頭。","花顏有幸君王問，藥餌無徵待詔愁。","惆悵近來消瘦盡，淚珠時傍枕函流。"]', '["佳人臥病动經秋，簾幕繿縿不挂鉤。","四體強扶藤夾膝，雙鬟慵插玉搔头。","花顏有幸君王问，藥餌無徵待詔愁。","惆悵近来消瘦尽，泪珠时傍枕函流。"]', '诗', 'shi', '', NULL, '病宮人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f11908ea-5957-4516-9d5b-469e17951926', '觀杭州柘枝', '观杭州柘枝', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["舞停歌罷鼓連摧，軟骨仙蛾暫起來。","紅罨畫衫纏腕出，碧排方胯背腰來。","旁收拍拍金鈴擺，却踏聲聲錦袎摧。","看著遍頭香袖褶，粉屏香帕又重隈。"]', '["舞停歌罷鼓連摧，軟骨仙蛾暫起来。","紅罨畫衫纏腕出，碧排方胯背腰来。","旁收拍拍金鈴擺，却踏声声錦袎摧。","看著遍头香袖褶，粉屏香帕又重隈。"]', '诗', 'shi', '', NULL, '觀杭州柘枝 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa73b90-73e9-4c75-a9aa-1674237b18af', '周員外席上觀柘枝', '周員外席上观柘枝', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["畫鼓拖環錦臂攘，小娥雙換舞衣裳。","金絲蹙霧紅衫薄，銀蔓垂花紫帶長。","鸞影乍迴頭並舉，鳳聲初歇翅齊張。","一時欻腕招殘拍，斜斂輕身拜玉郎。"]', '["畫鼓拖环錦臂攘，小娥雙換舞衣裳。","金絲蹙霧紅衫薄，銀蔓垂花紫带长。","鸾影乍迴头並舉，鳳声初歇翅齊張。","一时欻腕招殘拍，斜斂轻身拜玉郎。"]', '诗', 'shi', '', NULL, '周員外席上觀柘枝 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1b77311-782a-4896-ae57-eba253485995', '觀楊瑗柘枝', '观楊瑗柘枝', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["促疊蠻鼉引柘枝，卷簷虛帽帶交垂。","紫羅衫宛蹲身處，紅錦靴柔踏節時。","微動翠蛾拋舊態，緩遮檀口唱新詞。","看看舞罷輕雲起，却赴襄王夢裏期。"]', '["促叠蠻鼉引柘枝，卷簷虛帽带交垂。","紫羅衫宛蹲身处，紅錦靴柔踏節时。","微动翠蛾拋旧態，緩遮檀口唱新词。","看看舞罷轻云起，却赴襄王梦裏期。"]', '诗', 'shi', '', NULL, '觀楊瑗柘枝 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a11bdd12-03f3-452b-bede-bf2285567cf7', '感王將軍柘枝妓歿', '感王將軍柘枝妓歿', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["寂寞春風舊柘枝，舞人休唱曲休吹。","鴛鴦鈿帶拋何處，孔雀羅衫付阿誰。","畫鼓不聞招節拍，錦靴空想挫腰肢。","今來座上偏惆悵，曾是堂前教徹時。"]', '["寂寞春风旧柘枝，舞人休唱曲休吹。","鴛鴦鈿带拋何处，孔雀羅衫付阿誰。","畫鼓不闻招節拍，錦靴空想挫腰肢。","今来座上偏惆悵，曾是堂前教徹时。"]', '诗', 'shi', '', NULL, '感王將軍柘枝妓歿 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('961ac853-eb63-4444-8981-1b7cadbf7b0a', '揚州法雲寺雙檜', '揚州法云寺雙檜', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["謝家雙植本圖榮，樹老人因地變更。","朱頂鶴知深蓋偃，白眉僧見小枝生。","高臨月殿秋雲影，靜入風簷夜雨聲。","縱使百年爲上壽，綠陰終借暫時行。"]', '["謝家雙植本圖榮，樹老人因地变更。","朱頂鹤知深蓋偃，白眉僧见小枝生。","高臨月殿秋云影，静入风簷夜雨声。","縱使百年爲上壽，綠陰終借暫时行。"]', '诗', 'shi', '', NULL, '揚州法雲寺雙檜 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2779692f-7f70-4a58-b21d-3bdc8901aed4', '憶游天台寄道流', '憶游天台寄道流', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["憶昨天台到赤城，幾朝仙籟耳中生。","雲龍出水風聲過，海鶴鳴臯日色清。","石筍半山移步險，桂花當洞拂衣輕。"]', '["憶昨天台到赤城，幾朝仙籟耳中生。","云龙出水风声過，海鹤鳴臯日色清。","石筍半山移步險，桂花當洞拂衣轻。"]', '诗', 'shi', '', NULL, '憶游天台寄道流 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3372ccf7-d860-40e8-997f-cf7c6b84e045', '寄王尊師', '寄王尊師', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["天台南洞一靈仙，骨聳冰稜貌瑩然。","曾對浦雲長昧齒，重來華表不知年。","溪橋晚下玄龜出，草露朝行白鹿眠。","猶憶夜深華蓋上，更無人處話丹田。"]', '["天台南洞一靈仙，骨聳冰稜貌瑩然。","曾对浦云长昧齒，重来华表不知年。","溪橋晚下玄龟出，草露朝行白鹿眠。","猶憶夜深华蓋上，更無人处話丹田。"]', '诗', 'shi', '', NULL, '寄王尊師 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10bddc06-23bd-46ad-8693-0baacfde429a', '公子行', '公子行', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["錦堂晝永繡簾垂，立却花驄待出時。","紅粉美人擎酒勸，青衣年少臂鷹隨。","輕將玉杖敲花片，旋把金鞭約柳枝。","近地獨遊三五騎，等閑行傍曲江池。"]', '["錦堂晝永繡簾垂，立却花驄待出时。","紅粉美人擎酒勸，青衣年少臂鷹隨。","轻將玉杖敲花片，旋把金鞭約柳枝。","近地独游三五騎，等闲行傍曲江池。"]', '诗', 'shi', '', NULL, '公子行 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58555a27-99b1-4882-871a-ad83bf29e326', '寓懷寄蘇州劉郎中', '寓懷寄蘇州劉郎中', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一聞周召佐明時，西望都門強策羸。","天子好文才自薄，諸侯力薦命猶奇。","賀知章口徒勞說，孟浩然身更不疑。","唯是勝遊行未遍，欲離京國尚遲遲。"]', '["一闻周召佐明时，西望都门強策羸。","天子好文才自薄，諸侯力薦命猶奇。","賀知章口徒勞说，孟浩然身更不疑。","唯是勝游行未遍，欲離京国尚遲遲。"]', '诗', 'shi', '', NULL, '寓懷寄蘇州劉郎中 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50ccdb84-ebf0-4305-82ed-1fb40aa437f7', '和杜牧之齊山登高', '和杜牧之齊山登高', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["秋溪南岸菊霏霏，急管煩弦對落暉。","紅葉樹深山徑斷，碧雲江靜浦帆稀。","不堪孫盛嘲時笑，願送王弘醉夜歸。","流落正憐芳意在，砧聲徒促授寒衣。"]', '["秋溪南岸菊霏霏，急管煩弦对落暉。","紅葉樹深山徑斷，碧云江静浦帆稀。","不堪孫盛嘲时笑，願送王弘醉夜归。","流落正怜芳意在，砧声徒促授寒衣。"]', '诗', 'shi', '', NULL, '和杜牧之齊山登高 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00fd873f-2d0c-4a25-9293-993e9b6c5c83', '題于越亭', '題于越亭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["扁舟亭下駐煙波，十五年遊重此過。","洲觜露沙人渡淺，樹稍藏竹鳥啼多。","山銜落照欹紅蓋，水蹙斜文捲綠羅。","腸斷中秋正圓月，夜來誰唱異鄉歌。"]', '["扁舟亭下駐煙波，十五年游重此過。","洲觜露沙人渡淺，樹稍藏竹鸟啼多。","山銜落照欹紅蓋，水蹙斜文捲綠羅。","腸斷中秋正圓月，夜来誰唱異乡歌。"]', '诗', 'shi', '', NULL, '題于越亭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('157a64a0-b1f1-438e-9084-f57426ddd787', '秋夜登潤州慈和寺上方', '秋夜登潤州慈和寺上方', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["清夜浮埃暫歇鄽，塔輪金照露華鮮。","人行中路月生海，鶴語上方星滿天。","樓影半連深岸水，鐘聲寒徹遠林煙。","僧房閉盡下樓去，一半夢魂離世緣。"]', '["清夜浮埃暫歇鄽，塔輪金照露华鲜。","人行中路月生海，鹤語上方星满天。","楼影半連深岸水，鐘声寒徹远林煙。","僧房閉尽下楼去，一半梦魂離世緣。"]', '诗', 'shi', '', NULL, '秋夜登潤州慈和寺上方 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0de8d08-bafb-4837-a151-54eada922d85', '寄獻蕭相公', '寄獻蕭相公', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["東去江干是勝遊，鼎湖興望不堪愁。","謝安近日違朝旨，傅說當時允帝求。","暫向聊城飛一箭，長爲滄海繫扁舟。","分明此事無人見，白首相看未肯休。"]', '["东去江干是勝游，鼎湖兴望不堪愁。","謝安近日違朝旨，傅说當时允帝求。","暫向聊城飞一箭，长爲滄海繫扁舟。","分明此事無人见，白首相看未肯休。"]', '诗', 'shi', '', NULL, '寄獻蕭相公 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba7afd7-757e-4c18-8219-c58cc11fb9f6', '哭京兆龐尹', '哭京兆龐尹', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["楊子江頭昔共迷，一爲京兆隔雲泥。","故人昨日同時弔，舊馬今朝別處嘶。","向壁愁眉無復畫，扶牀稚齒已能啼。","也知世路名堪貴，誰信莊周論物齊。"]', '["楊子江头昔共迷，一爲京兆隔云泥。","故人昨日同时弔，旧马今朝別处嘶。","向壁愁眉無复畫，扶牀稚齒已能啼。","也知世路名堪貴，誰信莊周論物齊。"]', '诗', 'shi', '', NULL, '哭京兆龐尹 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e66d9b7-7d38-48ef-8ab5-2f4f2c4de829', '送周尚書赴滑臺', '送周尚书赴滑台', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["楚謠襦袴整三年，喉舌新恩下九天。","鼓角雄都分節鉞，蛇龍舊國罷樓船。","崑河已在兵鈐內，堂柳空留鶴嶺前。","多病無由酬一顧，鄢陵千騎去翩翩。"]', '["楚謠襦袴整三年，喉舌新恩下九天。","鼓角雄都分節鉞，蛇龙旧国罷楼船。","崑河已在兵鈐內，堂柳空留鹤嶺前。","多病無由酬一顧，鄢陵千騎去翩翩。"]', '诗', 'shi', '', NULL, '送周尚書赴滑臺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22d6a17d-b08b-4ed5-89a7-147753166d24', '和杜使君九華樓見寄', '和杜使君九华楼见寄', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["孤城高柳曉鳴鴉，風簾半鉤清露華。","九峰聚翠宿危檻，一夜孤光懸冷沙。","出岸遠暉帆欲落，入谿寒影鴈差斜。","杜陵歸去春應早，莫厭青山謝朓家。"]', '["孤城高柳晓鳴鴉，风簾半鉤清露华。","九峰聚翠宿危檻，一夜孤光懸冷沙。","出岸远暉帆欲落，入谿寒影鴈差斜。","杜陵归去春應早，莫厭青山謝朓家。"]', '诗', 'shi', '', NULL, '和杜使君九華樓見寄 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75df160d-ca74-43bc-91e8-cf4ca83929d1', '送人歸蜀', '送人归蜀', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["錦城春色泝江源，三峽經過幾夜猨。","紅樹兩厓開霽色，碧巖千仞漲波痕。","蕭蕭暮雨荆王夢，漠漠春煙蜀帝魂。","長怨相如留滯處，富家還憶卓王孫。"]', '["錦城春色泝江源，三峽經過幾夜猨。","紅樹兩厓开霽色，碧巖千仞漲波痕。","蕭蕭暮雨荆王梦，漠漠春煙蜀帝魂。","长怨相如留滯处，富家還憶卓王孫。"]', '诗', 'shi', '', NULL, '送人歸蜀 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0bda5e94-938b-4bdf-95ec-3d820a8c9e24', '酬答柳宗言秀才見贈', '酬答柳宗言秀才见贈', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南下天台厭絕冥，五湖波上汎如萍。","江鷗自戲爲蹤跡，野鹿閑驚是性靈。","任子偶垂滄海釣，戴逵虛認少微星。","金門後俊徒相唁，且爲人間寄茯苓。"]', '["南下天台厭絕冥，五湖波上汎如萍。","江鷗自戲爲蹤跡，野鹿闲驚是性靈。","任子偶垂滄海釣，戴逵虛認少微星。","金门後俊徒相唁，且爲人间寄茯苓。"]', '诗', 'shi', '', NULL, '酬答柳宗言秀才見贈 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74184ddc-8468-479e-aa57-fbf1b33c4cf1', '題杭州天竺寺', '題杭州天竺寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["西南山最勝，一界是諸天。","上路穿巖竹，分流入寺泉。","躡雲丹井畔，望月石橋邊。","洞壑江聲遠，樓臺海氣連。","塔明春嶺雪，鐘散暮松煙。","何處去猶恨，更看峰頂蓮。"]', '["西南山最勝，一界是諸天。","上路穿巖竹，分流入寺泉。","躡云丹井畔，望月石橋邊。","洞壑江声远，楼台海氣連。","塔明春嶺雪，鐘散暮松煙。","何处去猶恨，更看峰頂蓮。"]', '诗', 'shi', '', NULL, '題杭州天竺寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f664fc6-608d-42f2-b58c-ef3c705ebf84', '題杭州靈隱寺', '題杭州靈隐寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["峰巒開一掌，朱檻幾環延。","佛地花分界，僧房竹引泉。","五更樓下月，十里郭中煙。","後塔聳亭後，前山橫閣前。","溪沙涵水靜，澗石點苔鮮。","好是呼猨久，西巖深響連。"]', '["峰巒开一掌，朱檻幾环延。","佛地花分界，僧房竹引泉。","五更楼下月，十里郭中煙。","後塔聳亭後，前山橫閣前。","溪沙涵水静，澗石点苔鲜。","好是呼猨久，西巖深响連。"]', '诗', 'shi', '', NULL, '題杭州靈隱寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a52e078a-29ee-4bf2-ab6b-c52ee818fd23', '中秋夜杭州翫月', '中秋夜杭州翫月', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬古太陰精，中秋海上生。","鬼愁緣辟照，人愛爲高明。","歷歷華星遠，霏霏薄暈縈。","影流江不盡，輪曳谷無聲。","似鏡當樓曉，如珠出浦盈。","岸沙全借白，山木半含清。","小檻循環看，長堤蹋陣行。","殷勤未歸客，煙水夜來情。"]', '["万古太陰精，中秋海上生。","鬼愁緣辟照，人愛爲高明。","歷歷华星远，霏霏薄暈縈。","影流江不尽，輪曳谷無声。","似镜當楼晓，如珠出浦盈。","岸沙全借白，山木半含清。","小檻循环看，长堤蹋陣行。","殷勤未归客，煙水夜来情。"]', '诗', 'shi', '', NULL, '中秋夜杭州翫月 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4580450e-054a-41ee-ac7c-d573941e213f', '高閑上人', '高闲上人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["座上辭安國，禪房戀沃州。","道心黃葉老，詩思碧雲秋。","卷軸朝廷餞，書函內庫收。","陶欣入社叟，生怯論經儔。","日色屏初揭，風聲筆未休。","長波溢海岸，大點出嵩丘。","不絕羲之法，難窮智永流。","殷勤一牋在，留著看銀鉤。"]', '["座上辞安国，禪房戀沃州。","道心黄葉老，诗思碧云秋。","卷軸朝廷餞，书函內庫收。","陶欣入社叟，生怯論經儔。","日色屏初揭，风声笔未休。","长波溢海岸，大点出嵩丘。","不絕羲之法，难窮智永流。","殷勤一牋在，留著看銀鉤。"]', '诗', 'shi', '', NULL, '高閑上人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('679f1a3f-383d-4647-b6d2-8988e4267c73', '題靈隱寺師一上人十韻', '題靈隐寺師一上人十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["八十空門子，深山土木骸。","片衣閑自衲，單食老長齋。","道性終能遣，人情少不乖。","樔枸居上院，薜荔俯層階。","洗鉢前臨水，窺門外有柴。","朗吟揮竹拂，高楫曳芒鞋。","迸笋斜穿塢，飛泉下噴崖。","種花忻土潤，撥石慮沙埋。","舊往師招隱，初臨我詠懷。","何當緣興翫，更爲表新牌。"]', '["八十空门子，深山土木骸。","片衣闲自衲，單食老长斋。","道性終能遣，人情少不乖。","樔枸居上院，薜荔俯層階。","洗鉢前臨水，窺门外有柴。","朗吟揮竹拂，高楫曳芒鞋。","迸笋斜穿塢，飞泉下噴崖。","種花忻土潤，撥石慮沙埋。","旧往師招隐，初臨我詠懷。","何當緣兴翫，更爲表新牌。"]', '诗', 'shi', '', NULL, '題靈隱寺師一上人十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2fc68e1-b766-4d04-b8f0-26d923b4e5b0', '投常州從兄中丞', '投常州從兄中丞', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["扁舟何所往，言入善人邦。","舊愛鵬摶海，今聞虎渡江。","士因爲政樂，儒爲說詩降。","素履冰容靜，新詞玉潤樅。","金魚聊解帶，畫鷁稍移樁。","邀妓思逃席，留賓命倒缸。","史材誰是伍，經術世無雙。","廣廈當宏構，洪鐘併待撞。","成龍須講邴，展驥莫先龐。","應念宗中末，秋螢照一牕。"]', '["扁舟何所往，言入善人邦。","旧愛鵬摶海，今闻虎渡江。","士因爲政乐，儒爲说诗降。","素履冰容静，新词玉潤樅。","金鱼聊解带，畫鷁稍移樁。","邀妓思逃席，留賓命倒缸。","史材誰是伍，經術世無雙。","廣廈當宏構，洪鐘併待撞。","成龙須講邴，展驥莫先龐。","應念宗中末，秋螢照一牕。"]', '诗', 'shi', '', NULL, '投常州從兄中丞 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('738ea38e-7926-44cc-9ace-b644f3b4deac', '送王昌涉侍御', '送王昌涉侍御', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["十里指東平，軍前首出征。","諸侯青服舊，御史紫衣榮。","入陳梟心死，分圍虎力生。","畫時安楚塞，刻日下齊城。","號令朝移幕，偷蹤夜斫營。","雲梯曾險上，地道慣深行。","舉斾招降將，投戈趁敗兵。","自慙居虜者，當此立功名。"]', '["十里指东平，軍前首出征。","諸侯青服旧，御史紫衣榮。","入陳梟心死，分圍虎力生。","畫时安楚塞，刻日下齊城。","號令朝移幕，偷蹤夜斫營。","云梯曾險上，地道慣深行。","舉斾招降將，投戈趁敗兵。","自慙居虜者，當此立功名。"]', '诗', 'shi', '', NULL, '送王昌涉侍御 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5040a6b9-8575-4978-ae5f-eddedd82026f', '少年樂', '少年乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["二十便封侯，名居第一流。","綠鬟深小院，清管下高樓。","醉把金船擲，閑敲玉鐙遊。","帶盤紅鼴鼠，袍砑紫犀牛。","錦袋歸調箭，羅鞋起撥毬。","眼前長貴盛，那信世間愁。"]', '["二十便封侯，名居第一流。","綠鬟深小院，清管下高楼。","醉把金船擲，闲敲玉鐙游。","带盤紅鼴鼠，袍砑紫犀牛。","錦袋归調箭，羅鞋起撥毬。","眼前长貴盛，那信世间愁。"]', '诗', 'shi', '', NULL, '少年樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3880dd89-5719-4fa5-82e2-86bf6329a9d3', '華清宮和杜舍人', '华清宮和杜舍人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["五十年天子，離宮舊粉牆。","登封時正泰，御宇日初長。","上位先名實，中興事憲章。","舉戎輕甲胄，餘地取河湟。","道帝玄元祖，儒封孔子王。","因緣百司署，藂會一人湯。","渭水波搖綠，秦山草半黃。","馬頭開夜照，鷹眼利星芒。","下箭朱弓滿，鳴鞭皓腕攘。","畋思獲呂望，諫祇避周昌。","兔迹貪前逐，梟心不早防。","幾添鸚鵡勸，頻賜荔支嘗。","月鎖千門靜，天高一笛涼。","細音搖翠佩，輕步宛霓裳。","禍亂根潛結，昇平意遽忘。","衣冠逃犬虜，鼙鼓動漁陽。","外戚心殊迫，中途事可量。","雪埋妃子貌，刃斷祿兒腸。","近侍煙塵隔，前蹤輦路荒。","益知迷寵佞，惟恨喪忠良。","北闕尊明主，南宮遜上皇。","禁清餘鳳吹，池冷映龍光。","祝壽山猶在，流年水共傷。","杜鵑魂厭蜀，蝴蝶夢悲莊。","雀卵遺雕栱，蟲絲罥畫梁。","紫苔侵壁潤，紅樹閉門芳。","守吏齊鴛瓦，耕民得翠璫。","歡康昔時樂，講武舊兵場。","莫草深巖靄，幽花墜徑香。","不堪垂白叟，行折御溝楊。"]', '["五十年天子，離宮旧粉牆。","登封时正泰，御宇日初长。","上位先名實，中兴事憲章。","舉戎轻甲胄，餘地取河湟。","道帝玄元祖，儒封孔子王。","因緣百司署，藂會一人湯。","渭水波搖綠，秦山草半黄。","马头开夜照，鷹眼利星芒。","下箭朱弓满，鳴鞭皓腕攘。","畋思獲呂望，諫祇避周昌。","兔迹貪前逐，梟心不早防。","幾添鸚鵡勸，頻賜荔支嘗。","月鎖千门静，天高一笛涼。","細音搖翠佩，轻步宛霓裳。","禍亂根潛結，昇平意遽忘。","衣冠逃犬虜，鼙鼓动漁陽。","外戚心殊迫，中途事可量。","雪埋妃子貌，刃斷祿兒腸。","近侍煙塵隔，前蹤輦路荒。","益知迷寵佞，惟恨喪忠良。","北闕尊明主，南宮遜上皇。","禁清餘鳳吹，池冷映龙光。","祝壽山猶在，流年水共傷。","杜鵑魂厭蜀，蝴蝶梦悲莊。","雀卵遺雕栱，蟲絲罥畫梁。","紫苔侵壁潤，紅樹閉门芳。","守吏齊鴛瓦，耕民得翠璫。","歡康昔时乐，講武旧兵場。","莫草深巖靄，幽花墜徑香。","不堪垂白叟，行折御溝楊。"]', '诗', 'shi', '', NULL, '華清宮和杜舍人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f14db484-e8c2-4bfc-8a42-95ac02f41574', '穆護砂', '穆護砂', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["玉管朝朝弄，清歌日日新。","折花當驛路，寄與隴頭人。"]', '["玉管朝朝弄，清歌日日新。","折花當驛路，寄與隴头人。"]', '诗', 'shi', '', NULL, '穆護砂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cafbc059-b035-4aed-9592-01c51be8eb59', '思歸樂二首 一', '思归乐二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["晚日催弦管，春風入綺羅。","杏花如有意，偏落舞衫多。"]', '["晚日催弦管，春风入綺羅。","杏花如有意，偏落舞衫多。"]', '诗', 'shi', '', NULL, '思歸樂二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b81dffc-686b-453e-895a-cbec3df004d5', '思歸樂二首 二', '思归乐二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬里春應盡，三江鴈亦稀。","連天漢水廣，孤客未言歸。"]', '["万里春應尽，三江鴈亦稀。","連天漢水廣，孤客未言归。"]', '诗', 'shi', '', NULL, '思歸樂二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14b2dedc-2a6f-4550-8d59-d2a7cf0da41b', '金殿樂', '金殿乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["入夜秋砧動，千聲起四鄰。","不緣樓上月，應爲隴頭人。"]', '["入夜秋砧动，千声起四鄰。","不緣楼上月，應爲隴头人。"]', '诗', 'shi', '', NULL, '金殿樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bed546b2-19e6-4940-be52-b2483557522d', '牆頭花二首 一', '牆头花二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["蟋蟋鳴洞房，梧桐落金井。","爲君裁舞衣，天寒剪刀冷。"]', '["蟋蟋鳴洞房，梧桐落金井。","爲君裁舞衣，天寒剪刀冷。"]', '诗', 'shi', '', NULL, '牆頭花二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('254ad381-0c3f-4dcf-8c6a-cdf389ceeccf', '牆頭花二首 二', '牆头花二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["妾有羅衣裳，秦王在時作。","爲舞春風多，秋來不堪著。"]', '["妾有羅衣裳，秦王在时作。","爲舞春风多，秋来不堪著。"]', '诗', 'shi', '', NULL, '牆頭花二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18ccdbf3-09ed-4893-9cdd-786e3d946378', '胡渭州', '胡渭州', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["楊柳千尋色，桃花一苑芳。","風吹入簾裏，唯有惹衣香。"]', '["楊柳千尋色，桃花一苑芳。","风吹入簾裏，唯有惹衣香。"]', '诗', 'shi', '', NULL, '胡渭州 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf86c97f-7502-4ead-9ece-02ff58f90ff5', '白鼻騧', '白鼻騧', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["爲底胡姬酒，長來白鼻騧。","摘蓮拋水上，郎意在浮花。"]', '["爲底胡姬酒，长来白鼻騧。","摘蓮拋水上，郎意在浮花。"]', '诗', 'shi', '', NULL, '白鼻騧 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25d0c5c9-6f0f-4f35-be76-3938c71e5f26', '戎渾', '戎渾', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["風勁角弓鳴，將軍獵渭城。","草枯鷹眼疾，雪盡馬蹄輕。"]', '["风勁角弓鳴，將軍獵渭城。","草枯鷹眼疾，雪尽马蹄轻。"]', '诗', 'shi', '', NULL, '戎渾 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdec343a-78b2-49a6-ad70-4d7e307cd7e0', '楊下採桑', '楊下採桑', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["飛絲惹綠塵，軟葉對孤輪。","今朝入園去，物色強著人。"]', '["飞絲惹綠塵，軟葉对孤輪。","今朝入园去，物色強著人。"]', '诗', 'shi', '', NULL, '楊下採桑 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d850db6a-e07b-4fee-b642-57a70bdbbed2', '宮詞二首 一', '宮词二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["故國三千里，深宮二十年。","一聲河滿子，雙淚落君前。"]', '["故国三千里，深宮二十年。","一声河满子，雙泪落君前。"]', '诗', 'shi', '', NULL, '宮詞二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfed3ed9-5a99-4a60-8196-2d07cf5eedb4', '宮詞二首 二', '宮词二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["自倚能歌日，先皇掌上憐。","新聲何處唱，腸斷李延年。"]', '["自倚能歌日，先皇掌上怜。","新声何处唱，腸斷李延年。"]', '诗', 'shi', '', NULL, '宮詞二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb90dac8-fded-40fd-a0fe-2e53f35e657c', '昭君怨二首 一', '昭君怨二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬里邊城遠，千山行路難。","舉頭唯見日，何處是長安。"]', '["万里邊城远，千山行路难。","舉头唯见日，何处是长安。"]', '诗', 'shi', '', NULL, '昭君怨二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5ef8e80-5b17-448b-8980-8897ab63bfeb', '昭君怨二首 二', '昭君怨二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["漢庭無大議，戎虜幾先和。","莫羨傾城色，昭君恨最多。"]', '["漢庭無大議，戎虜幾先和。","莫羨傾城色，昭君恨最多。"]', '诗', 'shi', '', NULL, '昭君怨二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2589dabc-0548-4129-a2fb-3a630ecd2c41', '夕次竟陵', '夕次竟陵', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南風吹五兩，日暮竟陵城。","腸斷巴江月，夜蟬何處聲。"]', '["南风吹五兩，日暮竟陵城。","腸斷巴江月，夜蟬何处声。"]', '诗', 'shi', '', NULL, '夕次竟陵 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21178453-89ce-4dde-a734-b46f01f8d635', '信州水亭', '信州水亭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南簷架短廊，沙路白茫茫。","盡日不歸處，一庭梔子香。"]', '["南簷架短廊，沙路白茫茫。","尽日不归处，一庭梔子香。"]', '诗', 'shi', '', NULL, '信州水亭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f1d38c0-9ea8-44e5-9631-28d30f7f5921', '蘇小小歌三首 一', '蘇小小歌三首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["車輪不可遮，馬足不可絆。","長怨十字街，使郎心四散。"]', '["车輪不可遮，马足不可絆。","长怨十字街，使郎心四散。"]', '诗', 'shi', '', NULL, '蘇小小歌三首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f85d7a3-0e69-4c42-aeab-a45ac1d7e745', '蘇小小歌三首 二', '蘇小小歌三首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["新人千里去，故人千里來。","剪刀橫眼底，方覺淚難裁。"]', '["新人千里去，故人千里来。","剪刀橫眼底，方覺泪难裁。"]', '诗', 'shi', '', NULL, '蘇小小歌三首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('143208bf-8507-4b6e-b072-601f52da008f', '蘇小小歌三首 三', '蘇小小歌三首 三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["登山不愁峻，涉海不愁深。","中擘庭前棗，教郎見赤心。"]', '["登山不愁峻，涉海不愁深。","中擘庭前棗，教郎见赤心。"]', '诗', 'shi', '', NULL, '蘇小小歌三首 三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5cab02f-8419-4ab3-be95-9cfb618ad68e', '樹中草', '樹中草', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["青青樹中草，託根非不危。","草生樹却死，榮枯君可知。"]', '["青青樹中草，託根非不危。","草生樹却死，榮枯君可知。"]', '诗', 'shi', '', NULL, '樹中草 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99724de4-3c17-4e6f-bca9-7578e566cbce', '七里瀨漁家', '七里瀨漁家', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["七里垂釣叟，還傍釣臺居。","莫恨無姓名，嚴陵不賣魚。"]', '["七里垂釣叟，還傍釣台居。","莫恨無姓名，嚴陵不賣鱼。"]', '诗', 'shi', '', NULL, '七里瀨漁家 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('956838fa-7485-4042-acc3-6bfec3e17c6b', '讀曲歌五首 一', '读曲歌五首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["窗中獨自起，簾外獨自行。","愁見蜘蛛織，尋思直到明。"]', '["窗中独自起，簾外独自行。","愁见蜘蛛织，尋思直到明。"]', '诗', 'shi', '', NULL, '讀曲歌五首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c36f2d8-80fe-480c-8d0d-0ea1637f4c6b', '讀曲歌五首 二', '读曲歌五首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["碓上米不舂，窗中絲罷絡。","看渠駕去車，定是無四角。"]', '["碓上米不舂，窗中絲罷絡。","看渠駕去车，定是無四角。"]', '诗', 'shi', '', NULL, '讀曲歌五首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc5c492e-33e8-485b-938a-5258a13ddd19', '讀曲歌五首 三', '读曲歌五首 三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["不見心相許，徒云脚漫勤。","摘荷空摘葉，是底採蓮人。"]', '["不见心相許，徒云脚漫勤。","摘荷空摘葉，是底採蓮人。"]', '诗', 'shi', '', NULL, '讀曲歌五首 三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('693de188-bf8e-4eb1-9979-1c2e14013239', '讀曲歌五首 四', '读曲歌五首 四', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["窗外山魈立，知渠脚不多。","三更機底下，摸著是誰梭。"]', '["窗外山魈立，知渠脚不多。","三更機底下，摸著是誰梭。"]', '诗', 'shi', '', NULL, '讀曲歌五首 四 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('828a27b1-96b1-4699-b256-9452cd3e37f3', '讀曲歌五首 五', '读曲歌五首 五', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["郎去摘黃瓜，郎來收赤棗。","郎耕種麻地，今作西舍道。"]', '["郎去摘黄瓜，郎来收赤棗。","郎耕種麻地，今作西舍道。"]', '诗', 'shi', '', NULL, '讀曲歌五首 五 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e849eca7-308f-4be0-b5a8-6e406f7e3124', '玉樹後庭花', '玉樹後庭花', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["輕車何草草，獨唱後庭花。","玉座誰爲主，徒悲張麗華。"]', '["轻车何草草，独唱後庭花。","玉座誰爲主，徒悲張丽华。"]', '诗', 'shi', '', NULL, '玉樹後庭花 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd265781-69d8-4e8a-acf3-16af19549269', '莫愁樂', '莫愁乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["儂居石城下，郎到石城遊。","自郎石城出，長在石城頭。"]', '["儂居石城下，郎到石城游。","自郎石城出，长在石城头。"]', '诗', 'shi', '', NULL, '莫愁樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e17579c-fb53-4876-b996-a7d597f7a64d', '襄陽樂', '襄陽乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["大堤花月夜，長江春水流。","東風正上信，春夜特來遊。"]', '["大堤花月夜，长江春水流。","东风正上信，春夜特来游。"]', '诗', 'shi', '', NULL, '襄陽樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03b6a39e-d8b4-4f62-bc00-852dbb20f44f', '自君之出矣', '自君之出矣', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["自君之出矣，萬物看成古。","千尋葶藶枝，爭奈長長苦。"]', '["自君之出矣，万物看成古。","千尋葶藶枝，爭奈长长苦。"]', '诗', 'shi', '', NULL, '自君之出矣 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f36c078-ceba-492d-981d-27ecf8205220', '夢江南', '梦江南', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["行吟洞庭句，不見洞庭人。","盡日碧江夢，江南紅樹春。"]', '["行吟洞庭句，不见洞庭人。","尽日碧江梦，江南紅樹春。"]', '诗', 'shi', '', NULL, '夢江南 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e77c4ba-ca19-4723-9aa2-a655953ccaed', '將離岳州留獻徐員外', '將離岳州留獻徐員外', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["高齋長對酒，下客亦霑魚。","不爲江南去，還來郡北居。"]', '["高斋长对酒，下客亦霑鱼。","不爲江南去，還来郡北居。"]', '诗', 'shi', '', NULL, '將離岳州留獻徐員外 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27c49262-73aa-4c9d-bc0a-33f2f303aa31', '題彭澤盧明府新樓', '題彭澤盧明府新楼', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["碧落新樓迥，清池古樹閑。","先賢盡爲宰，空看縣南山。"]', '["碧落新楼迥，清池古樹闲。","先賢尽爲宰，空看縣南山。"]', '诗', 'shi', '', NULL, '題彭澤盧明府新樓 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2033d33d-e69f-4012-8a8d-956217d6b190', '贈禪師', '贈禪師', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["坐見三生事，宗傳一衲來。","已知無法說，心向定中灰。"]', '["坐见三生事，宗傳一衲来。","已知無法说，心向定中灰。"]', '诗', 'shi', '', NULL, '贈禪師 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc34398f-5765-49ad-be73-9f056ae5f642', '江南逢故人', '江南逢故人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["河洛多塵事，江山半舊遊。","春風故人夜，又醉白蘋洲。"]', '["河洛多塵事，江山半旧游。","春风故人夜，又醉白蘋洲。"]', '诗', 'shi', '', NULL, '江南逢故人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb2966a6-9139-40b7-95d3-2230a36ea9d8', '松江懷古', '松江懷古', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["碧樹吳洲遠，青山震澤深。","無人蹤范蠡，煙水暮沈沈。"]', '["碧樹吳洲远，青山震澤深。","無人蹤范蠡，煙水暮沈沈。"]', '诗', 'shi', '', NULL, '松江懷古 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7930ba58-b22b-4ee2-915a-0af65987caf2', '書憤', '书憤', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["三十未封侯，顛狂遍九州。","平生鏌鎁劍，不報小人讎。"]', '["三十未封侯，顛狂遍九州。","平生鏌鎁劍，不報小人讎。"]', '诗', 'shi', '', NULL, '書憤 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e2c719f-a70a-4460-9c5c-18515e331941', '題孟處士宅', '題孟处士宅', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["高才何必貴，下位不妨賢。","孟簡雖持節，襄陽屬浩然。"]', '["高才何必貴，下位不妨賢。","孟簡雖持節，襄陽屬浩然。"]', '诗', 'shi', '', NULL, '題孟處士宅 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c20ceca0-313e-4e57-9662-5783a1302cd1', '首陽行', '首陽行', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["首陽山下路，孤竹節長存。","爲問無心草，如何庇本根。"]', '["首陽山下路，孤竹節长存。","爲问無心草，如何庇本根。"]', '诗', 'shi', '', NULL, '首陽行 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6e59fd0-2744-4a71-ae57-f6d0ceb7f0eb', '題僧影堂', '題僧影堂', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["寒葉墜清霜，空簾著燼香。","生前既無事，何事更悲傷。"]', '["寒葉墜清霜，空簾著燼香。","生前既無事，何事更悲傷。"]', '诗', 'shi', '', NULL, '題僧影堂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5310de9-9593-48f2-98f0-1d692191d721', '邊思', '邊思', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["蘇武節旌盡，李陵音信稀。","花當隴上發，人向隴頭歸。"]', '["蘇武節旌尽，李陵音信稀。","花當隴上發，人向隴头归。"]', '诗', 'shi', '', NULL, '邊思 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72d0e603-51b8-4407-bb3b-247da5e3dec6', '題弋陽館', '題弋陽館', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一葉飄然下弋陽，殘霞昏日樹蒼蒼。","吳溪漫淬干將劍，却是猨聲斷客腸。"]', '["一葉飄然下弋陽，殘霞昏日樹蒼蒼。","吳溪漫淬干將劍，却是猨声斷客腸。"]', '诗', 'shi', '', NULL, '題弋陽館 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc614f21-94d1-4d02-bb5b-57b06d925530', '題秀師影堂', '題秀師影堂', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["陰陰古寺杉松下，記得長明一焰燈。","盡日看山人不會，影堂中是別來僧。"]', '["陰陰古寺杉松下，記得长明一焰灯。","尽日看山人不會，影堂中是別来僧。"]', '诗', 'shi', '', NULL, '題秀師影堂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90057e78-1459-405c-ad30-a6ce1fc7a62a', '贈李修源', '贈李修源', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["岳陽新尉曉衙參，却是傍人意未甘。","昨夜與君思賈誼，長沙猶在洞庭南。"]', '["岳陽新尉晓衙參，却是傍人意未甘。","昨夜與君思賈誼，长沙猶在洞庭南。"]', '诗', 'shi', '', NULL, '贈李修源 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b2c97b3-aee0-4fe7-92ae-757e927375fe', '瓜洲聞曉角', '瓜洲闻晓角', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["寒耿稀星照碧霄，月樓吹角夜江遙。","五更人起煙霜靜，一曲殘聲遍落潮。"]', '["寒耿稀星照碧霄，月楼吹角夜江遙。","五更人起煙霜静，一曲殘声遍落潮。"]', '诗', 'shi', '', NULL, '瓜洲聞曉角 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fa903bb-4ed5-416c-9dc3-135737cf492e', '元日仗', '元日仗', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["文武千官歲仗兵，萬方同軌奏昇平。","上皇一御含元殿，丹鳳門開白日明。"]', '["文武千官歲仗兵，万方同軌奏昇平。","上皇一御含元殿，丹鳳门开白日明。"]', '诗', 'shi', '', NULL, '元日仗 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77c338c2-cce1-4d31-8be4-e1965d50e355', '連昌宮', '連昌宮', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["龍虎旌旗雨露飄，玉樓歌斷碧山遙。","玄宗上馬太真去，紅樹滿園香自銷。"]', '["龙虎旌旗雨露飄，玉楼歌斷碧山遙。","玄宗上马太真去，紅樹满园香自銷。"]', '诗', 'shi', '', NULL, '連昌宮 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d9ab24a-3717-4627-8dce-23f953d6e82d', '正月十五夜燈', '正月十五夜灯', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["千門開鎖萬燈名，正月中旬動帝京。","三百內人連袖舞，一時天上著詞聲。"]', '["千门开鎖万灯名，正月中旬动帝京。","三百內人連袖舞，一时天上著词声。"]', '诗', 'shi', '', NULL, '正月十五夜燈 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3603a354-0dce-4c53-a47e-a4fce5ce12e9', '上巳樂', '上巳乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["猩猩血綵繫頭標，天上齊聲舉畫橈。","却是內人爭意切，六宮紅袖一時招。"]', '["猩猩血綵繫头標，天上齊声舉畫橈。","却是內人爭意切，六宮紅袖一时招。"]', '诗', 'shi', '', NULL, '上巳樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27fbdec-68f4-4a46-996a-45f9316dc25f', '千秋樂', '千秋乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["八月平時花蕚樓，萬方同樂奏千秋。","傾城人看長竿出，一伎初成趙解愁。"]', '["八月平时花蕚楼，万方同乐奏千秋。","傾城人看长竿出，一伎初成趙解愁。"]', '诗', 'shi', '', NULL, '千秋樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b486e7e-d873-4d31-97fc-acbd8a52319d', '春鶯囀', '春鶯囀', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["興慶池南柳未開，太真先把一枝梅。","內人已唱春鶯囀，花下傞傞軟舞來。"]', '["兴慶池南柳未开，太真先把一枝梅。","內人已唱春鶯囀，花下傞傞軟舞来。"]', '诗', 'shi', '', NULL, '春鶯囀 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad1af30b-d275-4d2f-8d3b-c1eeea8cc6da', '大酺樂二首 一', '大酺乐二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["車架東來值太平，大酺三日洛陽城。","小兒一伎竿頭絕，天下傳呼萬歲聲。"]', '["车架东来值太平，大酺三日洛陽城。","小兒一伎竿头絕，天下傳呼万歲声。"]', '诗', 'shi', '', NULL, '大酺樂二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('891617e6-6946-48ec-9200-6bcb45a67213', '大酺樂二首 二', '大酺乐二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紫陌酺歸日欲斜，紅塵開路薛王家。","雙鬟笑說樓前鼓，兩仗爭輪好落花。"]', '["紫陌酺归日欲斜，紅塵开路薛王家。","雙鬟笑说楼前鼓，兩仗爭輪好落花。"]', '诗', 'shi', '', NULL, '大酺樂二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55e2773-4a7a-435f-87d6-a255796f66a8', '邠王小管', '邠王小管', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["虢國潛行韓國隨，宜春深院映花枝。","金輿遠幸無人見，偷把邠王小管吹。"]', '["虢国潛行韓国隨，宜春深院映花枝。","金輿远幸無人见，偷把邠王小管吹。"]', '诗', 'shi', '', NULL, '邠王小管 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('198f9af8-7194-4615-8580-d0cbc9bc2e8b', '李謨笛', '李謨笛', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["平時東幸洛陽城，天樂宮中夜徹明。","無奈李謨偷曲譜，酒樓吹笛是新聲。"]', '["平时东幸洛陽城，天乐宮中夜徹明。","無奈李謨偷曲譜，酒楼吹笛是新声。"]', '诗', 'shi', '', NULL, '李謨笛 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc4334a-9a36-4aef-86bf-3e5be674c6cc', '寧哥來', '寧哥来', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日映宮城霧半開，太真簾下畏人猜。","黃翻綽指向西樹，不信寧哥回馬來。"]', '["日映宮城霧半开，太真簾下畏人猜。","黄翻綽指向西樹，不信寧哥回马来。"]', '诗', 'shi', '', NULL, '寧哥來 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91bc6aa8-c76d-463a-a9fe-339e340116e7', '丁巳年仲冬月江上作', '丁巳年仲冬月江上作', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南來驅馬渡江濆，消息前年此月聞。","唯是賈先生慟哭，不堪天意重陰雲。"]', '["南来驱马渡江濆，消息前年此月闻。","唯是賈先生慟哭，不堪天意重陰云。"]', '诗', 'shi', '', NULL, '丁巳年仲冬月江上作 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a47c97b-e000-4c42-8f21-e5c31b5fe7d2', '鄴中懷古', '鄴中懷古', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["鄴中城下漳河水，日夜東流莫記春。","腸斷宮中望陵處，不堪臺上也無人。"]', '["鄴中城下漳河水，日夜东流莫記春。","腸斷宮中望陵处，不堪台上也無人。"]', '诗', 'shi', '', NULL, '鄴中懷古 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab22ebc0-9fe5-40c9-a204-6141a57ce058', '讀池州杜員外杜秋娘詩', '读池州杜員外杜秋娘诗', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["年少多情杜牧之，風流仍作杜秋詩。","可知不是長門閉，也得相如第一詞。"]', '["年少多情杜牧之，风流仍作杜秋诗。","可知不是长门閉，也得相如第一词。"]', '诗', 'shi', '', NULL, '讀池州杜員外杜秋娘詩 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad79538-faa2-41f2-9351-5d4b1a1c7a95', '杭州開元寺牡丹', '杭州开元寺牡丹', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["濃豔初開小藥欄，人人惆悵出長安。","風流却是錢塘寺，不踏紅塵見牡丹。"]', '["濃豔初开小藥欄，人人惆悵出长安。","风流却是錢塘寺，不踏紅塵见牡丹。"]', '诗', 'shi', '', NULL, '杭州開元寺牡丹 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a32ec90-6da8-409c-8a7c-d56b8cf0f377', '招徐宗偃畫松石', '招徐宗偃畫松石', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["咫尺雲山便出塵，我生長日自因循。","憑君畫取江南勝，留向東齋伴老身。"]', '["咫尺云山便出塵，我生长日自因循。","憑君畫取江南勝，留向东斋伴老身。"]', '诗', 'shi', '', NULL, '招徐宗偃畫松石 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf054eae-2804-486f-b914-a3f4756b1cfb', '平陰夏日作', '平陰夏日作', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["西來漸覺細塵紅，擾擾舟車路向東。","可惜夏天明月夜，土山前面障南風。"]', '["西来漸覺細塵紅，擾擾舟车路向东。","可惜夏天明月夜，土山前面障南风。"]', '诗', 'shi', '', NULL, '平陰夏日作 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09fd1d22-6549-4282-bd04-1b3f21aae6a3', '贈處士', '贈处士', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["小徑上山山甚小，每憐僧院笑僧禪。","人間莫道無難事，二十年來已是玄。"]', '["小徑上山山甚小，每怜僧院笑僧禪。","人间莫道無难事，二十年来已是玄。"]', '诗', 'shi', '', NULL, '贈處士 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd1cc22-9a09-406e-8999-cb4db60e8744', '邠娘羯鼓', '邠娘羯鼓', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["新教邠娘羯鼓成，大酺初日最先呈。","冬兒指向貞貞說，一曲乾鳴兩杖輕。"]', '["新教邠娘羯鼓成，大酺初日最先呈。","冬兒指向貞貞说，一曲乾鳴兩杖轻。"]', '诗', 'shi', '', NULL, '邠娘羯鼓 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc463631-e58e-4f81-829b-ca4f338f3bdc', '退宮人二首 一', '退宮人二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["開元皇帝掌中憐，流落人間二十年。","長說承天門上宴，百官樓下拾金錢。"]', '["开元皇帝掌中怜，流落人间二十年。","长说承天门上宴，百官楼下拾金錢。"]', '诗', 'shi', '', NULL, '退宮人二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0c8b4eb-dc38-45bd-a9bb-2394f8b2eb1b', '退宮人二首 二', '退宮人二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["歌喉漸退出宮闈，泣話伶官上許歸。","猶說入時歡聖壽，內人初著五方衣。"]', '["歌喉漸退出宮闈，泣話伶官上許归。","猶说入时歡聖壽，內人初著五方衣。"]', '诗', 'shi', '', NULL, '退宮人二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('597c6a5a-9bbf-4b04-befd-3de5ba85f1b6', '耍娘歌', '耍娘歌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["宜春花夜雪千枝，妃子偷行上密隨。","便喚耍娘歌一曲，六宮生老是蛾眉。"]', '["宜春花夜雪千枝，妃子偷行上密隨。","便喚耍娘歌一曲，六宮生老是蛾眉。"]', '诗', 'shi', '', NULL, '耍娘歌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41da4e51-6e2a-49cb-af6a-1192a47d7914', '悖拏兒舞', '悖拏兒舞', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["春風南內百花時，道唱梁州急遍吹。","揭手便拈金椀舞，上皇驚笑悖拏兒。"]', '["春风南內百花时，道唱梁州急遍吹。","揭手便拈金椀舞，上皇驚笑悖拏兒。"]', '诗', 'shi', '', NULL, '悖拏兒舞 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4c98d52-feea-45f8-a801-c3336165e561', '題靈徹上人舊房', '題靈徹上人旧房', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["寂寞空門支道林，滿堂詩板舊知音。","秋風吹葉古廊下，一半繩牀燈影深。"]', '["寂寞空门支道林，满堂诗板旧知音。","秋风吹葉古廊下，一半繩牀灯影深。"]', '诗', 'shi', '', NULL, '題靈徹上人舊房 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03c2e3f3-b1c3-498f-9a4d-6c6877ec73e6', '晚秋潼關西門作', '晚秋潼关西门作', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日落寒郊煙物清，古槐陰黑少人行。","關門西去華山色，秦地東來河水聲。"]', '["日落寒郊煙物清，古槐陰黑少人行。","关门西去华山色，秦地东来河水声。"]', '诗', 'shi', '', NULL, '晚秋潼關西門作 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84bd91bd-11f7-4218-b9e2-b05b06ce8b99', '贈內人', '贈內人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["禁門宮樹月痕過，媚眼唯看宿燕窠。","斜拔玉釵燈影畔，剔開紅焰救飛蛾。"]', '["禁门宮樹月痕過，媚眼唯看宿燕窠。","斜拔玉釵灯影畔，剔开紅焰救飞蛾。"]', '诗', 'shi', '', NULL, '贈內人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59666ede-f247-486f-bbda-98efe92a5acb', '洛中作', '洛中作', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["元和天子昔平戎，惆悵金輿尚未通。","盡日洛橋閑處看，秋風時節上陽宮。"]', '["元和天子昔平戎，惆悵金輿尚未通。","尽日洛橋闲处看，秋风时節上陽宮。"]', '诗', 'shi', '', NULL, '洛中作 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('561524b4-f9d0-4f9e-ba79-a8423f3e97cb', '折楊柳枝二首 一', '折楊柳枝二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["莫折宮前楊柳枝，玄宗曾向笛中吹。","傷心日暮煙霞起，無限春愁生翠眉。"]', '["莫折宮前楊柳枝，玄宗曾向笛中吹。","傷心日暮煙霞起，無限春愁生翠眉。"]', '诗', 'shi', '', NULL, '折楊柳枝二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24a9647b-3da2-4fef-b2ad-71a7cd645f55', '折楊柳枝二首 二', '折楊柳枝二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["凝碧池邊斂翠眉，景陽樓下綰青絲。","那勝妃子朝元閣，玉手和煙弄一枝。"]', '["凝碧池邊斂翠眉，景陽楼下綰青絲。","那勝妃子朝元閣，玉手和煙弄一枝。"]', '诗', 'shi', '', NULL, '折楊柳枝二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5139807-ad11-47be-ba92-1461bc229e8f', '華清宮四首 一', '华清宮四首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["風樹離離月稍明，九天龍氣在華清。","宮門深鎖無人覺，半夜雲中羯鼓聲。"]', '["风樹離離月稍明，九天龙氣在华清。","宮门深鎖無人覺，半夜云中羯鼓声。"]', '诗', 'shi', '', NULL, '華清宮四首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25a1ccd0-99fb-45e1-b6f2-79106ae1cf3a', '華清宮四首 二', '华清宮四首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["天闕沈沈夜未央，碧雲仙曲舞霓裳。","一聲玉笛向空盡，月滿驪山宮漏長。"]', '["天闕沈沈夜未央，碧云仙曲舞霓裳。","一声玉笛向空尽，月满驪山宮漏长。"]', '诗', 'shi', '', NULL, '華清宮四首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14dec0ab-44a1-44f5-b43e-40199c18b443', '華清宮四首 三', '华清宮四首 三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紅樹蕭蕭閣半開，上皇曾幸此宮來。","至今風俗驪山下，村笛猶吹阿濫堆。"]', '["紅樹蕭蕭閣半开，上皇曾幸此宮来。","至今风俗驪山下，村笛猶吹阿濫堆。"]', '诗', 'shi', '', NULL, '華清宮四首 三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bb582e4-d604-4eb5-9cbd-773a7942403e', '華清宮四首 四', '华清宮四首 四', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["水遶宮牆處處聲，殘紅長綠露華清。","武皇一夕夢不覺，十二玉樓空月明。"]', '["水遶宮牆处处声，殘紅长綠露华清。","武皇一夕梦不覺，十二玉楼空月明。"]', '诗', 'shi', '', NULL, '華清宮四首 四 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87ca92e8-b148-4b68-a9bc-386243f043b0', '贈竇家小兒', '贈竇家小兒', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["深綠衣裳小小人，每來聽裏解相親。","天生合去雲霄上，一尺松栽已出塵。"]', '["深綠衣裳小小人，每来听裏解相親。","天生合去云霄上，一尺松栽已出塵。"]', '诗', 'shi', '', NULL, '贈竇家小兒 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e808dee-54f9-428c-a303-71ea2ee91df5', '聽崔莒侍御葉家歌', '听崔莒侍御葉家歌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["宛羅重縠起歌筵，活鳳生花動碧煙。","一聲唱斷無人和，觸破秋雲直上天。"]', '["宛羅重縠起歌筵，活鳳生花动碧煙。","一声唱斷無人和，觸破秋云直上天。"]', '诗', 'shi', '', NULL, '聽崔莒侍御葉家歌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9be5e1b5-2ab1-40f5-8478-34304b42605b', '長門怨', '长门怨', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日映宮牆柳色寒，笙歌遙指碧雲端。","珠鉛滴盡無心語，強把花枝冷笑看。"]', '["日映宮牆柳色寒，笙歌遙指碧云端。","珠鉛滴尽無心語，強把花枝冷笑看。"]', '诗', 'shi', '', NULL, '長門怨 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f2782a0-50ef-4c68-a5a7-700072bd18db', '讀老莊', '读老莊', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["等閑緝綴閑言語，誇向詩人喚作詩。","昨日偶拈莊老讀，萬尋山上一毫釐。"]', '["等闲緝綴闲言語，誇向诗人喚作诗。","昨日偶拈莊老读，万尋山上一毫釐。"]', '诗', 'shi', '', NULL, '讀老莊 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8336ca09-bc03-4fca-a089-158f0a4188c4', '偶題', '偶題', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古來名下豈虛爲，李白顛狂自稱時。","唯恨世間無賀老，謫仙長在沒人知。"]', '["古来名下豈虛爲，李白顛狂自稱时。","唯恨世间無賀老，謫仙长在沒人知。"]', '诗', 'shi', '', NULL, '偶題 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4502a4b6-020a-47d3-bb7c-6d2f259233ed', '別玉華僊侶', '別玉华僊侶', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["遶舍煙霞爲四鄰，寒泉白石日相親。","塵機不盡住不得，珍重玉山山上人。"]', '["遶舍煙霞爲四鄰，寒泉白石日相親。","塵機不尽住不得，珍重玉山山上人。"]', '诗', 'shi', '', NULL, '別玉華僊侶 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70852388-0a18-4ef0-85cb-e073eb2bf0b8', '汴上送客', '汴上送客', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["河流西下鴈南飛，楚客相逢淚濕衣。","張翰思歸何太切，扁舟不住又東歸。"]', '["河流西下鴈南飞，楚客相逢泪濕衣。","張翰思归何太切，扁舟不住又东归。"]', '诗', 'shi', '', NULL, '汴上送客 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75f42aef-c901-42c9-baec-9fdc1e3c56dc', '郵亭殘花', '郵亭殘花', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["雲暗山橫日欲斜，郵亭下馬對殘花。","自從身逐征西府，每到花時不在家。"]', '["云暗山橫日欲斜，郵亭下马对殘花。","自從身逐征西府，每到花时不在家。"]', '诗', 'shi', '', NULL, '郵亭殘花 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a38ea53c-814d-4ec5-a5cd-74038b475524', '秋時送鄭侍御', '秋时送鄭侍御', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["離鴻聲怨碧雲淨，楚瑟調高清曉天。","盡日相看俱不語，西風搖落數枝蓮。"]', '["離鴻声怨碧云淨，楚瑟調高清晓天。","尽日相看俱不語，西风搖落數枝蓮。"]', '诗', 'shi', '', NULL, '秋時送鄭侍御 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79d4c672-c1f8-466a-bb8a-97a22e2566e7', '宿武牢關', '宿武牢关', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["行人候曉久裴徊，不待雞鳴未得開。","堪羨寒溪自無事，潺潺一夜宿關來。"]', '["行人候晓久裴徊，不待雞鳴未得开。","堪羨寒溪自無事，潺潺一夜宿关来。"]', '诗', 'shi', '', NULL, '宿武牢關 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4568742a-6daa-4a29-ae37-faa48ac70301', '夜宿湓浦逢崔昇', '夜宿湓浦逢崔昇', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["江流不動月西沈，南北行人萬里心。","況是相逢鴈天夕，星河寥落水雲深。"]', '["江流不动月西沈，南北行人万里心。","況是相逢鴈天夕，星河寥落水云深。"]', '诗', 'shi', '', NULL, '夜宿湓浦逢崔昇 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1f83088-16fe-43a8-bf2d-7a118b7eb796', '京城寓懷', '京城寓懷', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["三十年持一釣竿，偶隨書薦入長安。","由來不是求名者，唯待春風看牡丹。"]', '["三十年持一釣竿，偶隨书薦入长安。","由来不是求名者，唯待春风看牡丹。"]', '诗', 'shi', '', NULL, '京城寓懷 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19867a30-1b67-4123-b367-44565bab6516', '集靈臺二首 一', '集靈台二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日光斜照集靈臺，紅樹花迎曉露開。","昨夜上皇新授籙，太真含笑入簾來。"]', '["日光斜照集靈台，紅樹花迎晓露开。","昨夜上皇新授籙，太真含笑入簾来。"]', '诗', 'shi', '', NULL, '集靈臺二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51262a8c-de53-41ee-958a-de08d5f5a446', '集靈臺二首 二', '集靈台二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["虢國夫人承主恩，平明騎馬入宮門。","却嫌脂粉汚顏色，淡掃蛾眉朝至尊。"]', '["虢国夫人承主恩，平明騎马入宮门。","却嫌脂粉汚顏色，淡掃蛾眉朝至尊。"]', '诗', 'shi', '', NULL, '集靈臺二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc066eb7-91af-499d-a691-8f9452b21011', '感歸', '感归', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["行却江南路幾千，歸來不把一文錢。","鄉人笑我窮寒鬼，還似襄陽孟浩然。"]', '["行却江南路幾千，归来不把一文錢。","乡人笑我窮寒鬼，還似襄陽孟浩然。"]', '诗', 'shi', '', NULL, '感歸 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d23945a1-9439-4bf5-9cf5-ce3d9f7291e6', '偶作', '偶作', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["徧識青霄路上人，相逢秖是語逡巡。","可勝飲盡江南酒，歲月猶殘李白身。"]', '["徧識青霄路上人，相逢秖是語逡巡。","可勝饮尽江南酒，歲月猶殘李白身。"]', '诗', 'shi', '', NULL, '偶作 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddb0a7ca-2de3-4720-9a8f-f6ce1c85d379', '勸飲酒', '勸饮酒', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["燒得硫黃漫學仙，未勝長付酒家錢。","竇常不喫齊推樂，却在人間八十年。"]', '["燒得硫黄漫学仙，未勝长付酒家錢。","竇常不喫齊推乐，却在人间八十年。"]', '诗', 'shi', '', NULL, '勸飲酒 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43518b8e-1d67-479d-8224-7fc6660d642a', '阿䳰湯', '阿䳰湯', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["月照宮城紅樹芳，綠窗燈影在雕梁。","金輿未到長生殿，妃子偷尋阿䳰湯。"]', '["月照宮城紅樹芳，綠窗灯影在雕梁。","金輿未到长生殿，妃子偷尋阿䳰湯。"]', '诗', 'shi', '', NULL, '阿䳰湯 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4f178b-0009-40ce-9c8d-2c76c6d58279', '馬嵬坡', '马嵬坡', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["旌旗不整奈君何，南去人稀北去多。","塵土已殘香粉豔，荔枝猶到馬嵬坡。"]', '["旌旗不整奈君何，南去人稀北去多。","塵土已殘香粉豔，荔枝猶到马嵬坡。"]', '诗', 'shi', '', NULL, '馬嵬坡 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad203d7d-aab8-4cc1-907d-e8976e174ff8', '太真香囊子', '太真香囊子', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["蹙金妃子小花囊，銷耗胸前結舊香。","誰爲君王重解得，一生遺恨繫心腸。"]', '["蹙金妃子小花囊，銷耗胸前結旧香。","誰爲君王重解得，一生遺恨繫心腸。"]', '诗', 'shi', '', NULL, '太真香囊子 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8e11414-a73c-4788-ba77-714875ed7bc0', '雨霖鈴', '雨霖鈴', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["雨霖鈴夜却歸秦，猶見張徽一曲新。","長說上皇和淚教，月明南內更無人。"]', '["雨霖鈴夜却归秦，猶见張徽一曲新。","长说上皇和泪教，月明南內更無人。"]', '诗', 'shi', '', NULL, '雨霖鈴 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83edf60f-b9dc-432f-a4cb-abb2db37ef5b', '聽歌二首 一', '听歌二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["兒郎漫說轉喉輕，須待情來意自生。","只是眼前絲竹和，大家聲裏唱新聲。"]', '["兒郎漫说轉喉轻，須待情来意自生。","只是眼前絲竹和，大家声裏唱新声。"]', '诗', 'shi', '', NULL, '聽歌二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f6ff2be-a9bf-4696-aa27-d634e2dc42f1', '聽歌二首 二', '听歌二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["十二年前邊塞行，坐中無語歎歌情。","不堪昨夜先垂淚，西去陽關第一聲。"]', '["十二年前邊塞行，坐中無語歎歌情。","不堪昨夜先垂泪，西去陽关第一声。"]', '诗', 'shi', '', NULL, '聽歌二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1fe451a-98dd-4fd3-86f2-5fd663d80cb7', '聽箏', '听箏', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["十指纖纖玉筍紅，鴈行輕遏翠弦中。","分明似說長城苦，水咽雲寒一夜風。"]', '["十指纖纖玉筍紅，鴈行轻遏翠弦中。","分明似说长城苦，水咽云寒一夜风。"]', '诗', 'shi', '', NULL, '聽箏 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5be9e8f8-8d23-4d21-8ae4-39de58fd0174', '王家琵琶', '王家琵琶', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["金屑檀槽玉腕明，子弦輕撚爲多情。","只愁拍盡涼州破，畫出風雷是撥聲。"]', '["金屑檀槽玉腕明，子弦轻撚爲多情。","只愁拍尽涼州破，畫出风雷是撥声。"]', '诗', 'shi', '', NULL, '王家琵琶 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67d38511-f8ce-4978-8159-bc6b08b9d731', '李家柘枝', '李家柘枝', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紅鉛拂臉細腰人，金繡羅衫軟著身。","長恐舞時殘拍盡，却思雲雨更無因。"]', '["紅鉛拂臉細腰人，金繡羅衫軟著身。","长恐舞时殘拍尽，却思云雨更無因。"]', '诗', 'shi', '', NULL, '李家柘枝 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88294ec1-a0b5-4d52-9395-71ee7919ab45', '楚州韋中丞箜篌', '楚州韋中丞箜篌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["千重鉤鎖撼金鈴，萬顆真珠瀉玉瓶。","恰值滿堂人欲醉，甲光纔觸一時醒。"]', '["千重鉤鎖撼金鈴，万顆真珠瀉玉瓶。","恰值满堂人欲醉，甲光纔觸一时醒。"]', '诗', 'shi', '', NULL, '楚州韋中丞箜篌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34a3f637-b340-4583-9248-c5a11ec0f693', '邊上逢歌者', '邊上逢歌者', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["垂老秋歌出塞庭，遏雲相付舊秦青。","少年翻擲新聲盡，却向人前側耳聽。"]', '["垂老秋歌出塞庭，遏云相付旧秦青。","少年翻擲新声尽，却向人前側耳听。"]', '诗', 'shi', '', NULL, '邊上逢歌者 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e7b635-8591-454e-882e-63e4bba14d6b', '馬嵬歸', '马嵬归', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["雲愁鳥恨驛坡前，孑孑龍旗指望賢。","無復一生重語事，柘黃衫袖掩潸然。"]', '["云愁鸟恨驛坡前，孑孑龙旗指望賢。","無复一生重語事，柘黄衫袖掩潸然。"]', '诗', 'shi', '', NULL, '馬嵬歸 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea796d03-30c2-43bf-afd3-cf5bb386c571', '塞上聞笛', '塞上闻笛', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一夜梅花笛裏飛，冷沙晴檻月光輝。","北風吹盡向何處，高入塞雲燕鴈稀。"]', '["一夜梅花笛裏飞，冷沙晴檻月光輝。","北风吹尽向何处，高入塞云燕鴈稀。"]', '诗', 'shi', '', NULL, '塞上聞笛 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c06b64c0-d919-489a-b080-a4714f6b994c', '經舊遊', '經旧游', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["去年來送行人處，依舊蟲聲古岸南。","斜日照溪雲影斷，水葓花穗倒空潭。"]', '["去年来送行人处，依旧蟲声古岸南。","斜日照溪云影斷，水葓花穗倒空潭。"]', '诗', 'shi', '', NULL, '經舊遊 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('758a9e19-1703-4928-9a29-401fbeae7c85', '東山寺', '东山寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["寒色蒼蒼老栢風，石苔清滑露光融。","半夜四山鐘磬盡，水精宮殿月玲瓏。"]', '["寒色蒼蒼老栢风，石苔清滑露光融。","半夜四山鐘磬尽，水精宮殿月玲瓏。"]', '诗', 'shi', '', NULL, '東山寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af71cc2-17df-4d25-b7bd-5002c18e1661', '峰頂寺', '峰頂寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["月明如水山頭寺，仰面看天石上行。","夜半深廊人語定，一枝松動鶴來聲。"]', '["月明如水山头寺，仰面看天石上行。","夜半深廊人語定，一枝松动鹤来声。"]', '诗', 'shi', '', NULL, '峰頂寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7d4285c-6ff4-4232-96de-273eda9bcbc9', '題潤州鶴林寺', '題潤州鹤林寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古寺名僧多異時，道情虛遣俗情悲。","千年鶴在市朝變，來去舊山人不知。"]', '["古寺名僧多異时，道情虛遣俗情悲。","千年鹤在市朝变，来去旧山人不知。"]', '诗', 'shi', '', NULL, '題潤州鶴林寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb80edc-7241-4419-b700-a8ecf6b95631', '題勝上人山房', '題勝上人山房', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["清晝房廊山半開，一瓶新汲灑莓苔。","古松百尺始生葉，颯颯風聲天上來。"]', '["清晝房廊山半开，一瓶新汲灑莓苔。","古松百尺始生葉，颯颯风声天上来。"]', '诗', 'shi', '', NULL, '題勝上人山房 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ab4c4c9-1503-4e44-a1f9-34e93173105c', '李夫人詞', '李夫人词', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["延年不語望三星，莫說夫人上涕零。","爭奈世間惆悵在，甘泉宮夜看圖形。"]', '["延年不語望三星，莫说夫人上涕零。","爭奈世间惆悵在，甘泉宮夜看圖形。"]', '诗', 'shi', '', NULL, '李夫人詞 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bce40ff4-816c-490c-be30-04de15f7c25e', '題金陵渡', '題金陵渡', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["金陵津渡小山樓，一宿行人自可愁。","潮落夜江斜月裏，兩三星火是瓜州。"]', '["金陵津渡小山楼，一宿行人自可愁。","潮落夜江斜月裏，兩三星火是瓜州。"]', '诗', 'shi', '', NULL, '題金陵渡 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72dea9b1-4650-4109-8621-8716b6b59cb2', '過陰陵', '過陰陵', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["壯士悽惶到山下，行人惆悵上山頭。","生前此路已迷失，寂寞孤魂何處遊。"]', '["壯士悽惶到山下，行人惆悵上山头。","生前此路已迷失，寂寞孤魂何处游。"]', '诗', 'shi', '', NULL, '過陰陵 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dd58129-5865-4990-9c13-23dea0823ac7', '縱遊淮南', '縱游淮南', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["十里長街市井連，月明橋上看神仙。","人生只合揚州死，禪智山光好墓田。"]', '["十里长街市井連，月明橋上看神仙。","人生只合揚州死，禪智山光好墓田。"]', '诗', 'shi', '', NULL, '縱遊淮南 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ac090d-48ac-4c2e-b60f-67b87bd453bb', '登樂遊原', '登乐游原', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["幾年詩酒滯江干，水積雲重思萬端。","今日南方惆悵盡，樂遊原上見長安。"]', '["幾年诗酒滯江干，水積云重思万端。","今日南方惆悵尽，乐游原上见长安。"]', '诗', 'shi', '', NULL, '登樂遊原 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07fb7700-b53a-4838-b1ac-8b76a5ca1d41', '過石頭城', '過石头城', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["纍纍墟墓葬西原，六代同歸蔓草根。","唯是歲華流盡處，石頭城下水千痕。"]', '["纍纍墟墓葬西原，六代同归蔓草根。","唯是歲华流尽处，石头城下水千痕。"]', '诗', 'shi', '', NULL, '過石頭城 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b79fd5-9abb-47cc-bbf7-1fa04a6b82d9', '黃蜀葵花', '黄蜀葵花', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["名花八葉嫩黃金，色照書窗透竹林。","無奈美人閑把嗅，直疑檀口印中心。"]', '["名花八葉嫩黄金，色照书窗透竹林。","無奈美人闲把嗅，直疑檀口印中心。"]', '诗', 'shi', '', NULL, '黃蜀葵花 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5258ac82-b83a-410b-b8f4-dabb2ec4cc82', '楊花', '楊花', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["散亂隨風處處勻，庭前幾日雪花新。","無端惹著潘郎鬢，驚殺綠窗紅粉人。"]', '["散亂隨风处处勻，庭前幾日雪花新。","無端惹著潘郎鬢，驚殺綠窗紅粉人。"]', '诗', 'shi', '', NULL, '楊花 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b69e2293-b675-44e4-9a21-410999606711', '薔薇花', '薔薇花', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["曉風抹盡燕支顆，夜雨催成蜀錦機。","當晝開時正明媚，故鄉疑是買臣歸。"]', '["晓风抹尽燕支顆，夜雨催成蜀錦機。","當晝开时正明媚，故乡疑是買臣归。"]', '诗', 'shi', '', NULL, '薔薇花 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('943cf843-d212-49e2-a12f-a8a4017d2e3d', '戲顏郎中獵', '戲顏郎中獵', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["忽聞射獵出軍城，人著戎衣馬帶纓。","倒把角弓呈一箭，滿川狐兔當頭行。"]', '["忽闻射獵出軍城，人著戎衣马带纓。","倒把角弓呈一箭，满川狐兔當头行。"]', '诗', 'shi', '', NULL, '戲顏郎中獵 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1587e65b-dc89-4473-a93e-d70be7f51a72', '江上旅泊呈杜員外', '江上旅泊呈杜員外', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["牛渚南來沙岸長，遠吟佳句望池陽。","野人未必非毛遂，太守還須是孟嘗。"]', '["牛渚南来沙岸长，远吟佳句望池陽。","野人未必非毛遂，太守還須是孟嘗。"]', '诗', 'shi', '', NULL, '江上旅泊呈杜員外 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a421cd8-5cc3-4700-aea8-7ced152d6642', '容兒鉢頭', '容兒鉢头', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["爭走金車叱鞅牛，笑聲唯是說千秋。","兩邊角子羊門裏，猶學容兒弄鉢頭。"]', '["爭走金车叱鞅牛，笑声唯是说千秋。","兩邊角子羊门裏，猶学容兒弄鉢头。"]', '诗', 'shi', '', NULL, '容兒鉢頭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8c7825-a0c7-42ec-af0a-4df5b3eea3b9', '熱戲樂', '熱戲乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["熱戲爭心劇火燒，銅槌暗熱不相饒。","上皇失喜寧王笑，百尺幢竿果動搖。"]', '["熱戲爭心劇火燒，銅槌暗熱不相饒。","上皇失喜寧王笑，百尺幢竿果动搖。"]', '诗', 'shi', '', NULL, '熱戲樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b72bb70-cd92-4576-9276-d04bcf825a4d', '玉環琵琶', '玉环琵琶', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["宮樓一曲琵琶聲，滿眼雲山是去程。","回顧段師非汝意，玉環休把恨分明。"]', '["宮楼一曲琵琶声，满眼云山是去程。","回顧段師非汝意，玉环休把恨分明。"]', '诗', 'shi', '', NULL, '玉環琵琶 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c24a4eed-3ab3-4bff-9252-27bfa2969661', '題酸棗驛前碑', '題酸棗驛前碑', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["蒼苔古澀自雕疎，誰道中郎筆力餘。","長愛當時遇王粲，每來碑下不關書。"]', '["蒼苔古澀自雕疎，誰道中郎笔力餘。","长愛當时遇王粲，每来碑下不关书。"]', '诗', 'shi', '', NULL, '題酸棗驛前碑 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06a74e5e-8124-49ec-9141-c9e51b37dd56', '題朱兵曹山居', '題朱兵曹山居', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["朱氏西齋萬卷書，水門山闊自高疎。","我來穿穴非無意，願向君家作壁魚。"]', '["朱氏西斋万卷书，水门山闊自高疎。","我来穿穴非無意，願向君家作壁鱼。"]', '诗', 'shi', '', NULL, '題朱兵曹山居 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddd714c0-2794-4771-baf4-3b49f8ba29aa', '題畫僧二首 一', '題畫僧二首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["骨峭情高彼岸人，一杯長泛海爲津。","僧儀又入清流品，却恐前生是許詢。"]', '["骨峭情高彼岸人，一杯长泛海爲津。","僧儀又入清流品，却恐前生是許詢。"]', '诗', 'shi', '', NULL, '題畫僧二首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77074d06-3f8b-4bb9-ae9e-8b7dab0ec38c', '題畫僧二首 二', '題畫僧二首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["瘦頸隆肩碧眼生，翰林親讚虎頭能。","終年不語看如意，似證禪心入大乘。"]', '["瘦頸隆肩碧眼生，翰林親讚虎头能。","終年不語看如意，似證禪心入大乘。"]', '诗', 'shi', '', NULL, '題畫僧二首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0bb3ee8-1aa5-44f9-b8be-2683c7156e42', '送走馬使', '送走马使', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["新樣花文配蜀羅，同心雙帶蹙金蛾。","慣將喉舌傳軍好，馬跡鈴聲遍兩河。"]', '["新樣花文配蜀羅，同心雙带蹙金蛾。","慣將喉舌傳軍好，马跡鈴声遍兩河。"]', '诗', 'shi', '', NULL, '送走馬使 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3570eb6-8824-4208-b631-42b081ac495a', '題御溝', '題御溝', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬樹垂楊拂御溝，溶溶漾漾遶神州。","都緣濟物心無阻，從此恩波處處流。"]', '["万樹垂楊拂御溝，溶溶漾漾遶神州。","都緣濟物心無阻，從此恩波处处流。"]', '诗', 'shi', '', NULL, '題御溝 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fa301e8-a913-411e-a6a3-0177c64861fc', '題青龍寺', '題青龙寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["二十年沈滄海間，一遊京國也應閑。","人人盡到求名處，獨向青龍寺看山。"]', '["二十年沈滄海间，一游京国也應闲。","人人尽到求名处，独向青龙寺看山。"]', '诗', 'shi', '', NULL, '題青龍寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1bdffac-a26f-46c0-adf9-0e6f2c413379', '硫黃', '硫黄', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一粒硫黃入貴門，寢堂深處問玄言。","時人盡說韋山甫，昨日餘干弔子孫。"]', '["一粒硫黄入貴门，寢堂深处问玄言。","时人尽说韋山甫，昨日餘干弔子孫。"]', '诗', 'shi', '', NULL, '硫黃 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0514299-96b8-4e28-92d2-5035b318f2be', '散花樓', '散花楼', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["錦江城外錦城頭，回望秦川上軫憂。","正值血魂來夢裏，杜鵑聲在散花樓。"]', '["錦江城外錦城头，回望秦川上軫憂。","正值血魂来梦裏，杜鵑声在散花楼。"]', '诗', 'shi', '', NULL, '散花樓 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('732acd2b-7a11-4e7f-92e3-eaecba012b2e', '王家五弦', '王家五弦', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["五條弦出萬端情，撚撥間關漫態生。","唯羨風流田太守，小金鈴子耳邊鳴。"]', '["五條弦出万端情，撚撥间关漫態生。","唯羨风流田太守，小金鈴子耳邊鳴。"]', '诗', 'shi', '', NULL, '王家五弦 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1814cae-ec73-4fc2-bb09-03dd658eba2d', '聽薛陽陶吹蘆管', '听薛陽陶吹蘆管', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紫清人下薛陽陶，末曲新笳調更高。","無奈一聲天外絕，百年已死斷腸刀。"]', '["紫清人下薛陽陶，末曲新笳調更高。","無奈一声天外絕，百年已死斷腸刀。"]', '诗', 'shi', '', NULL, '聽薛陽陶吹蘆管 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaaed3e5-9243-4aaa-812a-29e8aee24c82', '過汾水關', '過汾水关', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["千里南來背日行，關門無事一侯嬴。","山根百尺路前去，十夜耳中汾水聲。"]', '["千里南来背日行，关门無事一侯嬴。","山根百尺路前去，十夜耳中汾水声。"]', '诗', 'shi', '', NULL, '過汾水關 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9cfc2ae-3000-40f3-90d7-e094807a03d2', '櫻桃', '櫻桃', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["石榴未拆梅猶小，愛此山花四五株。","斜日庭前風嬝嬝，碧油千片漏紅珠。"]', '["石榴未拆梅猶小，愛此山花四五株。","斜日庭前风嬝嬝，碧油千片漏紅珠。"]', '诗', 'shi', '', NULL, '櫻桃 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('546b43ee-754f-4c16-9276-c4cb3f932c3d', '酬凌秀才惠枕', '酬凌秀才惠枕', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["八寸黃楊惠不輕，虎頭光照簟文清。","空心想此緣成夢，拔劍燈前一夜行。"]', '["八寸黄楊惠不轻，虎头光照簟文清。","空心想此緣成梦，拔劍灯前一夜行。"]', '诗', 'shi', '', NULL, '酬凌秀才惠枕 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9286550d-0d86-407f-b043-f0672b292058', '感春申君', '感春申君', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["薄俗何心議感恩，諂容卑迹賴君門。","春申還道三千客，寂寞無人殺李園。"]', '["薄俗何心議感恩，諂容卑迹賴君门。","春申還道三千客，寂寞無人殺李园。"]', '诗', 'shi', '', NULL, '感春申君 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8f3ea6d-cf39-424c-b483-3f557f56b0bf', '孟才人歎', '孟才人歎', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["偶因歌態詠嬌嚬，傳唱宮中十二春。","却爲一聲河滿子，下泉須弔舊才人。"]', '["偶因歌態詠嬌嚬，傳唱宮中十二春。","却爲一声河满子，下泉須弔旧才人。"]', '诗', 'shi', '', NULL, '孟才人歎 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27903dde-9692-4fc3-b9d2-c03a176e26be', '聽簡上人吹蘆管三首 一', '听簡上人吹蘆管三首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["蜀國僧吹蘆一枝，隴西游客淚先垂。","至今留得新聲在，却爲中原人不知。"]', '["蜀国僧吹蘆一枝，隴西游客泪先垂。","至今留得新声在，却爲中原人不知。"]', '诗', 'shi', '', NULL, '聽簡上人吹蘆管三首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea91be6d-fb29-44e1-aee5-53875699344e', '聽簡上人吹蘆管三首 二', '听簡上人吹蘆管三首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["細蘆僧管夜沈沈，越鳥巴猨寄恨吟。","吹到耳邊聲盡處，一條絲斷碧雲心。"]', '["細蘆僧管夜沈沈，越鸟巴猨寄恨吟。","吹到耳邊声尽处，一條絲斷碧云心。"]', '诗', 'shi', '', NULL, '聽簡上人吹蘆管三首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6790eaa6-d1c9-4868-a78d-08a0c7b6417b', '聽簡上人吹蘆管三首 三', '听簡上人吹蘆管三首 三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["月落江城樹繞鴉，一聲蘆管是天涯。","分明西國人來說，赤佛堂西是漢家。"]', '["月落江城樹繞鴉，一声蘆管是天涯。","分明西国人来说，赤佛堂西是漢家。"]', '诗', 'shi', '', NULL, '聽簡上人吹蘆管三首 三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9439f354-b5fd-49d2-8142-99828b73eab3', '聽岳州徐員外彈琴', '听岳州徐員外彈琴', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["玉律潛符一古琴，哲人心見聖人心。","盡日南風似遺意，九疑猨鳥滿山吟。"]', '["玉律潛符一古琴，哲人心见聖人心。","尽日南风似遺意，九疑猨鸟满山吟。"]', '诗', 'shi', '', NULL, '聽岳州徐員外彈琴 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f564bda-46fc-4dfd-b27e-d08725343e3e', '鉤弋夫人詞', '鉤弋夫人词', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["惆悵雲陵事不迴，萬金重更築仙臺。","莫言天上無消息，猶是夫人作鳥來。"]', '["惆悵云陵事不迴，万金重更築仙台。","莫言天上無消息，猶是夫人作鸟来。"]', '诗', 'shi', '', NULL, '鉤弋夫人詞 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac6cdfa4-14f4-401a-a4b7-b1d3354d623b', '鴻溝', '鴻溝', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["龍蛇百戰爭天下，各制雄心指此溝。","寧似九州分國土，地圖初割海中流。"]', '["龙蛇百戰爭天下，各制雄心指此溝。","寧似九州分国土，地圖初割海中流。"]', '诗', 'shi', '', NULL, '鴻溝 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63dbfe11-242b-4a60-8c55-bfe5f7230cae', '悲納鐵', '悲納鐵', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["長聞爲政古諸侯，使佩刀人盡佩牛。","誰謂今來正耕墾，却銷農器作戈矛。"]', '["长闻爲政古諸侯，使佩刀人尽佩牛。","誰謂今来正耕墾，却銷農器作戈矛。"]', '诗', 'shi', '', NULL, '悲納鐵 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8a64325-11a5-40b9-af4e-42f834e91395', '胡渭州', '胡渭州', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["亭亭孤月照行舟，寂寂長江萬里流。","鄉國不知何處是，雲山漫漫使人愁。"]', '["亭亭孤月照行舟，寂寂长江万里流。","乡国不知何处是，云山漫漫使人愁。"]', '诗', 'shi', '', NULL, '胡渭州 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bebccba0-7ac5-437e-a953-f91c86d7deda', '破陣樂', '破陣乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["秋風四面足風沙，塞外征人暫別家。","千里不辭行路遠，時光早晚到天涯。"]', '["秋风四面足风沙，塞外征人暫別家。","千里不辞行路远，时光早晚到天涯。"]', '诗', 'shi', '', NULL, '破陣樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f740d6e-dc77-436e-8743-64fd0cb8dc36', '楓橋', '楓橋', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["長洲苑外草蕭蕭，卻算游城歲月遙。","唯有別時今不忘，暮煙疎雨過楓橋。"]', '["长洲苑外草蕭蕭，卻算游城歲月遙。","唯有別时今不忘，暮煙疎雨過楓橋。"]', '诗', 'shi', '', NULL, '楓橋 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3561d89c-77fe-4e95-9d57-b2d718949259', '句', '句', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬國見清道，一身成白頭。","此地榮辱盛，豈宜山中人。","椿兒遶樹春園裏，桂子尋花夜月中。","一身扶杖二兒隨。","夏雨蓮苞破，秋風桂子彫。","杜鵑花發杜鵑叫，烏臼花生烏臼啼。","茶風無奈筆，酒禿不勝簪。"]', '["万国见清道，一身成白头。","此地榮辱盛，豈宜山中人。","椿兒遶樹春园裏，桂子尋花夜月中。","一身扶杖二兒隨。","夏雨蓮苞破，秋风桂子彫。","杜鵑花發杜鵑叫，烏臼花生烏臼啼。","茶风無奈笔，酒禿不勝簪。"]', '诗', 'shi', '', NULL, '句 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f9ded2c-701c-48c5-bb42-8148b98df9f0', '荅李昌期', '荅李昌期', '1c7aa80a-5048-440e-8587-9705420c5442', '唐', '["三山載羣仙，峨峨鹹浪中。","雲衣剪不得，此路安可從。","我生亦何事，出門如飛蓬。","白日又黃昏，所悲瑤草空。","蟲聲故鄉夢，枕上禾黍風。"]', '["三山載羣仙，峨峨鹹浪中。","云衣剪不得，此路安可從。","我生亦何事，出门如飞蓬。","白日又黄昏，所悲瑤草空。","蟲声故乡梦，枕上禾黍风。"]', '诗', 'shi', '', NULL, '荅李昌期 楊洵美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bcf3329-95e1-410f-b6fd-7f99bbdd191a', '宮詞', '宮词', '4e2cc224-ca9d-4abb-aebf-b388a99746f5', '唐', '["一道甘泉接御溝，上皇行處不曾秋。","誰言水是無情物，也到宮前咽不流。"]', '["一道甘泉接御溝，上皇行处不曾秋。","誰言水是無情物，也到宮前咽不流。"]', '诗', 'shi', '', NULL, '宮詞 長孫翱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5bff5dc-b6bc-4694-8aa9-1be72babf78a', '和于中丞登越王樓見寄', '和于中丞登越王楼见寄', 'ac154388-4d0b-4907-9f02-afb0246312d6', '唐', '["高情推謝守，善政屬綿州。","未落紫泥詔，閑登白雪樓。","晴江如送日，寒嶺鎮迎秋。","滿壁朝天士，唯予不繫舟。"]', '["高情推謝守，善政屬綿州。","未落紫泥詔，闲登白雪楼。","晴江如送日，寒嶺鎮迎秋。","满壁朝天士，唯予不繫舟。"]', '诗', 'shi', '', NULL, '和于中丞登越王樓見寄 盧求 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b604f1b-8e67-4786-b813-e73fda0f33ea', '雨', '雨', 'ae6538ef-2724-4e07-b5af-c6bcd0d8915e', '唐', '["細雨弄春陰，餘寒入晝深。","山姿輕薄霧，煙色澹幽林。","鹿踐莓苔滑，魚牽水荇沈。","懷情方未已，清酒漫須斟。"]', '["細雨弄春陰，餘寒入晝深。","山姿轻薄霧，煙色澹幽林。","鹿踐莓苔滑，鱼牽水荇沈。","懷情方未已，清酒漫須斟。"]', '诗', 'shi', '', NULL, '雨 歐陽衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10b5887d-00d2-4028-b30d-1554f6303e82', '田家', '田家', 'ae6538ef-2724-4e07-b5af-c6bcd0d8915e', '唐', '["黯黯日將夕，牛羊村外來。","巖阿青氣發，籬落杏花開。","草木應初感，鶬鶊亦已催。","晚間春作好，行樂不須猜。"]', '["黯黯日將夕，牛羊村外来。","巖阿青氣發，籬落杏花开。","草木應初感，鶬鶊亦已催。","晚间春作好，行乐不須猜。"]', '诗', 'shi', '', NULL, '田家 歐陽衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('518a8139-2a76-4240-a09c-c11cbbd7330f', '神光寺', '神光寺', 'ae6538ef-2724-4e07-b5af-c6bcd0d8915e', '唐', '["香剎懸青磴，飛樓界碧空。","石門棲怖鴿，慈塔繞歸鴻。","有法將心鏡，無名屬性通。","從來樂幽寂，尋覓未能窮。"]', '["香剎懸青磴，飞楼界碧空。","石门棲怖鴿，慈塔繞归鴻。","有法將心镜，無名屬性通。","從来乐幽寂，尋覓未能窮。"]', '诗', 'shi', '', NULL, '神光寺 歐陽衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2987bf38-3eb9-4921-997e-63f73ddb87c7', '和項斯遊頭陀寺上方', '和項斯游头陀寺上方', 'ae6538ef-2724-4e07-b5af-c6bcd0d8915e', '唐', '["步入桃源裏，晴花更滿枝。","峰迴山意曠，林杳竹光遲。","遠寺尋龍藏，名香發雁池。","間能將遠語，況及上陽時。"]', '["步入桃源裏，晴花更满枝。","峰迴山意曠，林杳竹光遲。","远寺尋龙藏，名香發雁池。","间能將远語，況及上陽时。"]', '诗', 'shi', '', NULL, '和項斯遊頭陀寺上方 歐陽衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d627c5e2-ffbc-46e5-a7c3-93bfa7acf5c9', '秦原道中', '秦原道中', 'ae6538ef-2724-4e07-b5af-c6bcd0d8915e', '唐', '["分險架長瀾，斜梁控夕巒。","宿雲依嶺斷，初月入江寒。","緇化秦裘敝，塵驚漢策殘。","無言倦行旅，遙路屬時難。"]', '["分險架长瀾，斜梁控夕巒。","宿云依嶺斷，初月入江寒。","緇化秦裘敝，塵驚漢策殘。","無言倦行旅，遙路屬时难。"]', '诗', 'shi', '', NULL, '秦原道中 歐陽衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adf79114-7087-45d8-aabd-0785e3b87c57', '月峰寺憶理公', '月峰寺憶理公', 'ae6538ef-2724-4e07-b5af-c6bcd0d8915e', '唐', '["共來江海上，清論一宵同。","禪榻渾依舊，心期浩已空。","驚春花落樹，聞梵澗搖風。","二諦欣咨啓，還應夢寐通。"]', '["共来江海上，清論一宵同。","禪榻渾依旧，心期浩已空。","驚春花落樹，闻梵澗搖风。","二諦欣咨啓，還應梦寐通。"]', '诗', 'shi', '', NULL, '月峰寺憶理公 歐陽衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eed70620-1d1b-4b42-979b-93d0c86a4b89', '寄陳去疾進士', '寄陳去疾進士', 'ae6538ef-2724-4e07-b5af-c6bcd0d8915e', '唐', '["放跡疑辭垢，棲心亦道門。","玄言蘿幌馥，詩思竹爐溫。","解帶搖花落，彈琴散鳥喧。","江山茲夕意，唯有素交存。"]', '["放跡疑辞垢，棲心亦道门。","玄言蘿幌馥，诗思竹爐溫。","解带搖花落，彈琴散鸟喧。","江山茲夕意，唯有素交存。"]', '诗', 'shi', '', NULL, '寄陳去疾進士 歐陽衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc996bf3-c19e-4646-9bf2-4a2985b40380', '聽郢客歌陽春白雪', '听郢客歌陽春白雪', 'ae6538ef-2724-4e07-b5af-c6bcd0d8915e', '唐', '["寂聽郢中人，高歌已絕倫。","臨風飄白雪，向日奏陽春。","調雅偏盈耳，聲長杳入神。","連連貫珠並，嬝嬝遏雲頻。","度曲知難和，凝情想任真。","周郎如賞羨，莫使滯芳晨。"]', '["寂听郢中人，高歌已絕倫。","臨风飄白雪，向日奏陽春。","調雅偏盈耳，声长杳入神。","連連貫珠並，嬝嬝遏云頻。","度曲知难和，凝情想任真。","周郎如賞羨，莫使滯芳晨。"]', '诗', 'shi', '', NULL, '聽郢客歌陽春白雪 歐陽衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d794d28c-ae8b-4aed-95b5-ba69e8b876ec', '南澗寺', '南澗寺', 'ae6538ef-2724-4e07-b5af-c6bcd0d8915e', '唐', '["春寺無人亂鳥啼，藤蘿陰磴野僧迷。","雲藏古壁遺龍象，草沒香臺抱鹿麛。","松籟泠泠疑梵唄，柳煙歷歷見招提。","爲耽寂樂親禪侶，莫怪閑行費馬蹄。"]', '["春寺無人亂鸟啼，藤蘿陰磴野僧迷。","云藏古壁遺龙象，草沒香台抱鹿麛。","松籟泠泠疑梵唄，柳煙歷歷见招提。","爲耽寂乐親禪侶，莫怪闲行費马蹄。"]', '诗', 'shi', '', NULL, '南澗寺 歐陽衮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c11f31b0-1281-4177-b874-b85ce67272e4', '獻歲書情', '獻歲书情', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["白髮添雙鬢，空宮又一年。","音書鴻不到，夢寐兔空懸。","地遠星辰側，天高雨露偏。","聖期知有感，雲海漫相連。"]', '["白髮添雙鬢，空宮又一年。","音书鴻不到，梦寐兔空懸。","地远星辰側，天高雨露偏。","聖期知有感，云海漫相連。"]', '诗', 'shi', '', NULL, '獻歲書情 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3730d401-ecd8-46d1-acb3-f8c577d7e1da', '奉和大梁相公重九日軍中宴會之什', '奉和大梁相公重九日軍中宴會之什', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["今古同嘉節，歡娛但異名。","陶公緣綠醑，謝傅爲蒼生。","酒泛金英麗，詩通玉律清。","何言辭物累，方繫萬人情。"]', '["今古同嘉節，歡娛但異名。","陶公緣綠醑，謝傅爲蒼生。","酒泛金英丽，诗通玉律清。","何言辞物累，方繫万人情。"]', '诗', 'shi', '', NULL, '奉和大梁相公重九日軍中宴會之什 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc7e2e0-9bf5-4198-8d41-53a109a56646', '奉和大梁相公同張員外重九日宴集', '奉和大梁相公同張員外重九日宴集', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["重九思嘉節，追歡從謝公。","酒清欺玉露，菊盛愧金風。","不待秋蟾白，須沈落照紅。","更將門下客，酬和管弦中。"]', '["重九思嘉節，追歡從謝公。","酒清欺玉露，菊盛愧金风。","不待秋蟾白，須沈落照紅。","更將门下客，酬和管弦中。"]', '诗', 'shi', '', NULL, '奉和大梁相公同張員外重九日宴集 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('582a0b30-3ddf-4db9-bbcd-dd0f231c46bf', '同樂天中秋夜洛河翫月二首 一', '同乐天中秋夜洛河翫月二首 一', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["清洛半秋懸璧月，綵船當夕泛銀河。","蒼龍頷底珠皆沒，白帝心邊鏡乍磨。","海上幾時霜雪積，人間此夜管弦多。","須知天地爲鑪意，盡取黃金鑄作波。"]', '["清洛半秋懸璧月，綵船當夕泛銀河。","蒼龙頷底珠皆沒，白帝心邊镜乍磨。","海上幾时霜雪積，人间此夜管弦多。","須知天地爲鑪意，尽取黄金鑄作波。"]', '诗', 'shi', '', NULL, '同樂天中秋夜洛河翫月二首 一 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ca69275-b6e0-4ba4-b6bb-15c60e2755d8', '同樂天中秋夜洛河翫月二首 二', '同乐天中秋夜洛河翫月二首 二', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["不熱不寒三五夕，晴川明月正相臨。","千珠競沒蒼龍頷，一鏡高懸白帝心。","幾處淒涼緣地遠，有時惆悵值雲陰。","如何清洛如清晝，共見初升又見沈。"]', '["不熱不寒三五夕，晴川明月正相臨。","千珠競沒蒼龙頷，一镜高懸白帝心。","幾处淒涼緣地远，有时惆悵值云陰。","如何清洛如清晝，共见初升又见沈。"]', '诗', 'shi', '', NULL, '同樂天中秋夜洛河翫月二首 二 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39a9c5be-5c56-4a01-9634-3f20c87910f4', '和邢郎中病中重陽強遊樂遊原', '和邢郎中病中重陽強游乐游原', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["嘉晨令節共陶陶，風景牽情並不勞。","曉日整冠蘭室靜，秋原騎馬菊花高。","晴光一一呈金剎，詩思浸浸逼水曹。","何必銷憂憑外物，祗將清韻敵春醪。"]', '["嘉晨令節共陶陶，风景牽情並不勞。","晓日整冠蘭室静，秋原騎马菊花高。","晴光一一呈金剎，诗思浸浸逼水曹。","何必銷憂憑外物，祗將清韻敵春醪。"]', '诗', 'shi', '', NULL, '和邢郎中病中重陽強遊樂遊原 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d9d4cb8-12a4-4302-9e2d-97518ef94a2c', '觀淬龍泉劒', '观淬龙泉劒', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["歐冶將成器，風胡幸見逢。","發硎思剸玉，投水化爲龍。","詎肯藏深匣，終朝用刜鐘。","蓮花生寶鍔，秋日勵霜鋒。","鍊質纔三尺，吹毛過百重。","擊磨如不倦，提握願長從。"]', '["歐冶將成器，风胡幸见逢。","發硎思剸玉，投水化爲龙。","詎肯藏深匣，終朝用刜鐘。","蓮花生寶鍔，秋日勵霜鋒。","鍊質纔三尺，吹毛過百重。","擊磨如不倦，提握願长從。"]', '诗', 'shi', '', NULL, '觀淬龍泉劒 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9880bab3-5a87-4657-a6f4-c66ce5931fb5', '春色滿皇州', '春色满皇州', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["寒銷山水地，春遍帝王州。","北闕晴光動，南山喜氣浮。","夭紅粧暖樹，急綠走陰溝。","思婦開香閣，王孫上玉樓。","氛氳直城北，駘蕩曲江頭。","今日靈臺下，翻然却是愁。"]', '["寒銷山水地，春遍帝王州。","北闕晴光动，南山喜氣浮。","夭紅粧暖樹，急綠走陰溝。","思婦开香閣，王孫上玉楼。","氛氳直城北，駘蕩曲江头。","今日靈台下，翻然却是愁。"]', '诗', 'shi', '', NULL, '春色滿皇州 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a929a248-6353-4d90-9a93-d68c1906a77b', '亞夫碎玉斗', '亞夫碎玉斗', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["雄謀竟不決，寶玉終不愛。","倏爾霜刃揮，颯然春冰碎。","飛光動旗幟，散響驚環珮。","霜灑繡障前，星流錦筵內。","圖王業已失，爲虜言空悔。","獨有青史中，英風觀千載。"]', '["雄謀竟不決，寶玉終不愛。","倏爾霜刃揮，颯然春冰碎。","飞光动旗幟，散响驚环珮。","霜灑繡障前，星流錦筵內。","圖王業已失，爲虜言空悔。","独有青史中，英风观千載。"]', '诗', 'shi', '', NULL, '亞夫碎玉斗 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72ba6026-1a1a-45e5-9cda-3f2f7658d3c3', '水亭', '水亭', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["歲律行將變，君恩竟未回。","門前即潮水，朝去暮常來。"]', '["歲律行將变，君恩竟未回。","门前即潮水，朝去暮常来。"]', '诗', 'shi', '', NULL, '水亭 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3dfda23-2574-40f6-a9f6-7b959ec7e6a9', '揚州寄諸子', '揚州寄諸子', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["千里隔烟波，孤舟宿何處？遙思耿不眠，淮南夜風雨。"]', '["千里隔烟波，孤舟宿何处？遙思耿不眠，淮南夜风雨。"]', '诗', 'shi', '', NULL, '揚州寄諸子 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4869e77e-9503-47b5-aaeb-0dabb8044034', '酬盧郎中遊寺見招不遇', '酬盧郎中游寺见招不遇', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["偶出送山客，不知遊梵宮。","秋光古松下，誰伴一仙翁。"]', '["偶出送山客，不知游梵宮。","秋光古松下，誰伴一仙翁。"]', '诗', 'shi', '', NULL, '酬盧郎中遊寺見招不遇 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0383802f-8df0-48e7-8b03-a5fe917219b8', '寓言', '寓言', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["秋樹却逢暖，未凋能幾時。","何須尚松桂，搖動暫青枝。"]', '["秋樹却逢暖，未凋能幾时。","何須尚松桂，搖动暫青枝。"]', '诗', 'shi', '', NULL, '寓言 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13b17855-ecdd-4c6b-bc27-3e3058342d95', '唁人喪侍兒', '唁人喪侍兒', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["夜情河耿耿，春恨草綿綿。","唯有嫦娥月，從今照墓田。"]', '["夜情河耿耿，春恨草綿綿。","唯有嫦娥月，從今照墓田。"]', '诗', 'shi', '', NULL, '唁人喪侍兒 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('740f7f75-3cd3-40b3-9db0-193d38ba6427', '席上夜別張主簿', '席上夜別張主簿', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["紅燭剪還明，綠尊添又滿。","不愁前路長，只畏今宵短。"]', '["紅燭剪還明，綠尊添又满。","不愁前路长，只畏今宵短。"]', '诗', 'shi', '', NULL, '席上夜別張主簿 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('949f2149-80c4-4124-b7d2-62385bc304b0', '方丈泉', '方丈泉', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["循涯不知淺，見底似非深。","永日無波浪，澄澄照我心。"]', '["循涯不知淺，见底似非深。","永日無波浪，澄澄照我心。"]', '诗', 'shi', '', NULL, '方丈泉 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f6a6a7-b517-4a68-9943-1b38e7e64443', '晚望', '晚望', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["日下夕陰長，前山凝積翠。","白鳥一行飛，聯聯粉書字。"]', '["日下夕陰长，前山凝積翠。","白鸟一行飞，聯聯粉书字。"]', '诗', 'shi', '', NULL, '晚望 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c917902-e58b-4003-bc0b-49566ea06222', '前山', '前山', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["只謂一蒼翠，不知猶數重。","晚來雲映處，更見兩三峰。"]', '["只謂一蒼翠，不知猶數重。","晚来云映处，更见兩三峰。"]', '诗', 'shi', '', NULL, '前山 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df1d6ea3-1664-4261-a5ae-36efee30fbd7', '發交州日留題解鍊師房', '發交州日留題解鍊師房', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["久喜房廊接，今成道路賒。","明朝回首處，此地是天涯。"]', '["久喜房廊接，今成道路賒。","明朝回首处，此地是天涯。"]', '诗', 'shi', '', NULL, '發交州日留題解鍊師房 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('906f6ab4-fdda-41f8-91d9-d20f60ae6bb3', '令和州買松', '令和州買松', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["好覓凌霜質，仍須帶雨栽。","須知剖竹日，便是看松來。"]', '["好覓凌霜質，仍須带雨栽。","須知剖竹日，便是看松来。"]', '诗', 'shi', '', NULL, '令和州買松 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de128788-7eef-4d87-a60c-5152856bd7f4', '題斷金集後', '題斷金集後', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["一覽斷金集，再悲埋玉人。","牙弦千古絕，珠淚萬行新。"]', '["一覽斷金集，再悲埋玉人。","牙弦千古絕，珠泪万行新。"]', '诗', 'shi', '', NULL, '題斷金集後 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b82f94fe-d45c-460e-b3fb-2561a407f4ec', '晚涼', '晚涼', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["簷前蔽日多高樹，竹下添池有小渠。","山客野僧歸去後，晚涼移案獨臨書。"]', '["簷前蔽日多高樹，竹下添池有小渠。","山客野僧归去後，晚涼移案独臨书。"]', '诗', 'shi', '', NULL, '晚涼 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88dc28ce-3d20-4cd7-868a-7b2bfcca3409', '和周侍御洛城雪', '和周侍御洛城雪', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["天街飛轡踏瓊英，四顧全疑在玉京。","一種相如抽祕思，兔園那比鳳凰城。"]', '["天街飞轡踏瓊英，四顧全疑在玉京。","一種相如抽祕思，兔园那比鳳凰城。"]', '诗', 'shi', '', NULL, '和周侍御洛城雪 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9bd587e-9af3-49a9-a0ff-7addb0037627', '奉和大梁相公送人二首 一', '奉和大梁相公送人二首 一', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["謝公日日傷離別，又向西堂送阿連。","想到越中秋已盡，鏡河應羨月團圓。"]', '["謝公日日傷離別，又向西堂送阿連。","想到越中秋已尽，镜河應羨月團圓。"]', '诗', 'shi', '', NULL, '奉和大梁相公送人二首 一 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f8a6d72-8e29-4466-b249-f4c80165ed15', '奉和大梁相公送人二首 二', '奉和大梁相公送人二首 二', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["北津楊柳迎烟綠，南岸闌干映水紅。","君到襄陽渡江處，始應回首憶羊公。"]', '["北津楊柳迎烟綠，南岸闌干映水紅。","君到襄陽渡江处，始應回首憶羊公。"]', '诗', 'shi', '', NULL, '奉和大梁相公送人二首 二 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fd0402b-5e34-4b02-937b-4bcbf3368b12', '酬唐仁烈相別後喜阻風未發見寄', '酬唐仁烈相別後喜阻风未發见寄', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["離心一起淚雙流，春浪無情也白頭。","風若有知須放去，莫教重別又重愁。"]', '["離心一起泪雙流，春浪無情也白头。","风若有知須放去，莫教重別又重愁。"]', '诗', 'shi', '', NULL, '酬唐仁烈相別後喜阻風未發見寄 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebf1be33-e0ab-4659-9d0c-5e3ef6c6c06e', '秦中臥病思歸', '秦中臥病思归', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["索索涼風滿樹頭，破窗殘月五更秋。","病身歸處吳江上，一寸心中萬里愁。"]', '["索索涼风满樹头，破窗殘月五更秋。","病身归处吳江上，一寸心中万里愁。"]', '诗', 'shi', '', NULL, '秦中臥病思歸 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9d6c3ff-165e-4e52-a810-63d544b9afea', '送王繢', '送王繢', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["翠羽長將玉樹期，偶然飛下肯多時。","翩翩一路嵐陰晚，却入青葱宿舊枝。"]', '["翠羽长將玉樹期，偶然飞下肯多时。","翩翩一路嵐陰晚，却入青葱宿旧枝。"]', '诗', 'shi', '', NULL, '送王繢 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb90f26f-4c0f-4d55-a65c-aa23ed550ef6', '贈美人琴絃', '贈美人琴絃', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["應從玉指到金徽，萬態千情料可知。","今夜燈前湘水怨，殷勤封在七條絲。"]', '["應從玉指到金徽，万態千情料可知。","今夜灯前湘水怨，殷勤封在七條絲。"]', '诗', 'shi', '', NULL, '贈美人琴絃 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('267b9325-1630-4ee9-bd02-d24b45af8338', '病中知皇子陂荷花盛發寄王繢', '病中知皇子陂荷花盛發寄王繢', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["十里蓮塘路不賒，病來簾外是天涯。","煩君四句遙相寄，應得詩中便看花。"]', '["十里蓮塘路不賒，病来簾外是天涯。","煩君四句遙相寄，應得诗中便看花。"]', '诗', 'shi', '', NULL, '病中知皇子陂荷花盛發寄王繢 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88e8dc78-b2ca-48a3-a980-dfed27b83bd1', '戲唐仁烈', '戲唐仁烈', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["自知年幾偏應少，先把屠蘇不讓春。","儻更數年逢此日，還應惆悵羨他人。"]', '["自知年幾偏應少，先把屠蘇不讓春。","儻更數年逢此日，還應惆悵羨他人。"]', '诗', 'shi', '', NULL, '戲唐仁烈 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a93800bc-9f72-4a28-b6e9-559244a382c8', '上下七盤二首 一', '上下七盤二首 一', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["斗回山路掩皇州，二載歡娛一望休。","從此萬重青嶂合，無因更得重回頭。"]', '["斗回山路掩皇州，二載歡娛一望休。","從此万重青嶂合，無因更得重回头。"]', '诗', 'shi', '', NULL, '上下七盤二首 一 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0905ae6f-f389-4d57-91d6-f1013f5ce8fd', '上下七盤二首 二', '上下七盤二首 二', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["商山半月雨漫漫，偶值新晴下七盤。","山似換來天似洗，可憐風日到長安。"]', '["商山半月雨漫漫，偶值新晴下七盤。","山似換来天似洗，可怜风日到长安。"]', '诗', 'shi', '', NULL, '上下七盤二首 二 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22b4e3e6-44af-4666-8316-1293c3daa861', '八月十五日夜', '八月十五日夜', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["去年今夜在商州，還爲清光上驛樓。","宛是依依舊顏色，自憐人換幾般愁。"]', '["去年今夜在商州，還爲清光上驛楼。","宛是依依旧顏色，自怜人換幾般愁。"]', '诗', 'shi', '', NULL, '八月十五日夜 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4707beb7-4039-41f6-a587-21d15b54358f', '南詔朱藤杖', '南詔朱藤杖', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["六節南藤色似朱，拄行階砌勝人扶。","會須將入深山去，倚看雲泉作老夫。"]', '["六節南藤色似朱，拄行階砌勝人扶。","會須將入深山去，倚看云泉作老夫。"]', '诗', 'shi', '', NULL, '南詔朱藤杖 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e386882b-d0cd-480a-8c38-08ad675c36f8', '夜意', '夜意', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["蕭疎盡地林無影，浩蕩連天月有波。","獨立空亭人睡後，洛橋風便水聲多。"]', '["蕭疎尽地林無影，浩蕩連天月有波。","独立空亭人睡後，洛橋风便水声多。"]', '诗', 'shi', '', NULL, '夜意 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffd11ad7-83bd-45e1-824a-44767f23f200', '漫作', '漫作', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["月色莫來孤寢處，春風又向別人家。","梁園桃李雖無數，斷定今年不看花。"]', '["月色莫来孤寢处，春风又向別人家。","梁园桃李雖無數，斷定今年不看花。"]', '诗', 'shi', '', NULL, '漫作 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc6f8268-7565-4789-9e03-bca065508f47', '訪劉君', '訪劉君', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["擾擾馳蹄又走輪，五更飛盡九衢塵。","靈芝破觀深松院，還有齋時未起人。"]', '["擾擾驰蹄又走輪，五更飞尽九衢塵。","靈芝破观深松院，還有斋时未起人。"]', '诗', 'shi', '', NULL, '訪劉君 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dac1571e-697d-44bb-9e4d-d10febd20d3b', '楊柳枝詞', '楊柳枝词', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["已作綠絲籠曉日，又成飛絮撲晴波。","隋家不合栽楊柳，長遣行人春恨多。"]', '["已作綠絲籠晓日，又成飞絮撲晴波。","隋家不合栽楊柳，长遣行人春恨多。"]', '诗', 'shi', '', NULL, '楊柳枝詞 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81763d8b-d9a8-446e-8abf-c33ebb1bb604', '寄杭州崔使君', '寄杭州崔使君', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["朝下歸來只閉關，羨君高步出人寰。","三年不見塵中事，滿眼江濤送雪山。"]', '["朝下归来只閉关，羨君高步出人寰。","三年不见塵中事，满眼江濤送雪山。"]', '诗', 'shi', '', NULL, '寄杭州崔使君 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b84a089-3498-4aa7-9249-8a6390b0b631', '窮冬曲江閑步', '窮冬曲江闲步', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["雪盡南坡鴈北飛，草根春意勝春暉。","曲江永日無人到，獨遶寒池又獨歸。"]', '["雪尽南坡鴈北飞，草根春意勝春暉。","曲江永日無人到，独遶寒池又独归。"]', '诗', 'shi', '', NULL, '窮冬曲江閑步 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f168ea1d-968d-464a-b7b0-1fc9bd1b0b5b', '省中題新植雙松', '省中題新植雙松', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["端坐高宮起遠心，雲高水闊共幽沈。","更堂寓直將誰語，自種雙松伴夜吟。"]', '["端坐高宮起远心，云高水闊共幽沈。","更堂寓直將誰語，自種雙松伴夜吟。"]', '诗', 'shi', '', NULL, '省中題新植雙松 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('568b1483-0cc5-44d9-b0b1-a8c56462dc28', '崇山郡', '崇山郡', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["地盡炎荒瘴海頭，聖朝今又放驩兜。","交州已在南天外，更過交州四五州。"]', '["地尽炎荒瘴海头，聖朝今又放驩兜。","交州已在南天外，更過交州四五州。"]', '诗', 'shi', '', NULL, '崇山郡 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5dc4fdc-10ec-4d67-8b84-a94d039a23e7', '臨水', '臨水', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["一見心原斷百憂，益知身世兩悠悠。","江亭獨倚闌干處，人亦無言水自流。"]', '["一见心原斷百憂，益知身世兩悠悠。","江亭独倚闌干处，人亦無言水自流。"]', '诗', 'shi', '', NULL, '臨水 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8eeefaa-8d04-47d0-b1a8-3b6bb7568e55', '題江上柳寄李使君', '題江上柳寄李使君', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["桂江南渡無楊柳，見此令人眼暫明。","應學郡中賢太守，依依相向許多情。"]', '["桂江南渡無楊柳，见此令人眼暫明。","應学郡中賢太守，依依相向許多情。"]', '诗', 'shi', '', NULL, '題江上柳寄李使君 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a638998-267d-4ec3-b561-706e818cadd5', '江上見月懷古', '江上见月懷古', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["月上江平夜不風，伏波遺跡半成空。","今宵倍欲悲陵谷，銅柱分明在水中。"]', '["月上江平夜不风，伏波遺跡半成空。","今宵倍欲悲陵谷，銅柱分明在水中。"]', '诗', 'shi', '', NULL, '江上見月懷古 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64c5e24c-c5d3-47c5-98fd-8eb5961e1f78', '鸚鵡', '鸚鵡', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["勸爾莫移禽鳥性，翠毛紅觜任天真。","如今漫學人言巧，解語終須累爾身。"]', '["勸爾莫移禽鸟性，翠毛紅觜任天真。","如今漫学人言巧，解語終須累爾身。"]', '诗', 'shi', '', NULL, '鸚鵡 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c1842c-f5ee-4737-816d-b4849264e56f', '寄婺州李給事二首 一', '寄婺州李給事二首 一', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["心盡玉皇恩已遠，跡留江郡宦應孤。","不知壯氣今何似，猶得凌雲貫日無。"]', '["心尽玉皇恩已远，跡留江郡宦應孤。","不知壯氣今何似，猶得凌云貫日無。"]', '诗', 'shi', '', NULL, '寄婺州李給事二首 一 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff034545-4628-48e5-807e-b50583f8c907', '寄婺州李給事二首 二', '寄婺州李給事二首 二', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["瘴鬼翻能念直心，五年相遇不相侵。","目前唯有思君病，無底滄溟未是深。"]', '["瘴鬼翻能念直心，五年相遇不相侵。","目前唯有思君病，無底滄溟未是深。"]', '诗', 'shi', '', NULL, '寄婺州李給事二首 二 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00b6726-356f-4788-a808-e1183268d964', '秋日', '秋日', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["六眸龜北涼應早，三足烏南日正長。","常記京關怨搖落，如今目斷滿林霜。"]', '["六眸龟北涼應早，三足烏南日正长。","常記京关怨搖落，如今目斷满林霜。"]', '诗', 'shi', '', NULL, '秋日 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ae868cd-3210-4e46-89c8-034fb2ec3bc5', '遣意', '遣意', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["梧桐墜露悲先朽，松桂凌霜倚後枯。","不是世間長在物，蹔分貞脆竟何殊。"]', '["梧桐墜露悲先朽，松桂凌霜倚後枯。","不是世间长在物，蹔分貞脆竟何殊。"]', '诗', 'shi', '', NULL, '遣意 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f380223e-fb6e-415c-bf49-96719507967e', '戲酬惟賞上人', '戲酬惟賞上人', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["師是浮雲無著身，我居塵網敢相親。","應從海上秋風便，偶自飛來不爲人。"]', '["師是浮云無著身，我居塵網敢相親。","應從海上秋风便，偶自飞来不爲人。"]', '诗', 'shi', '', NULL, '戲酬惟賞上人 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e090d81a-0753-4556-a91b-1f78e3c87df9', '寓言', '寓言', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["流水頹陽不暫停，東流西落兩無情。","不是世間人自老，古來華髮此中生。"]', '["流水頹陽不暫停，东流西落兩無情。","不是世间人自老，古来华髮此中生。"]', '诗', 'shi', '', NULL, '寓言 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96797f24-909e-4fbd-88a8-4576d3bd6a14', '憶家', '憶家', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["天海相連無盡處，夢魂來往尚應難。","誰言南海無霜雪，試向愁人兩鬢看。"]', '["天海相連無尽处，梦魂来往尚應难。","誰言南海無霜雪，試向愁人兩鬢看。"]', '诗', 'shi', '', NULL, '憶家 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca25d9b3-ed25-44d9-9976-700b5475edd2', '留客', '留客', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["青梅欲熟笋初長，嫩綠新陰遶砌涼。","湖館翛然無俗客，白衣居士且匡牀。"]', '["青梅欲熟笋初长，嫩綠新陰遶砌涼。","湖館翛然無俗客，白衣居士且匡牀。"]', '诗', 'shi', '', NULL, '留客 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1d8d427-9ddb-47dd-9702-f1ddbda34bd7', '別蘄春王判官', '別蘄春王判官', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["四十年來[真]久故，三千里外暫相逢。","今日一杯成遠別，烟波眇眇恨重重。"]', '["四十年来[真]久故，三千里外暫相逢。","今日一杯成远別，烟波眇眇恨重重。"]', '诗', 'shi', '', NULL, '別蘄春王判官 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8eb0d609-7145-40c2-a553-1890da2c70ec', '將發循州社日於所居館宴送', '將發循州社日於所居館宴送', '35e51a6b-95aa-4940-8b1a-2e891bd43959', '唐', '["浪花如雪疊江風，社過高秋萬恨中。","明日便隨江燕去，依依俱是故巢空。"]', '["浪花如雪叠江风，社過高秋万恨中。","明日便隨江燕去，依依俱是故巢空。"]', '诗', 'shi', '', NULL, '將發循州社日於所居館宴送 裴夷直 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('028b1794-eae0-4142-aef7-d25b2cc2afc6', '泛溪', '泛溪', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["曲渚迴花舫，生衣臥向風。","鳥飛溪色裏，人語棹聲中。","餘卉纔分影，新蒲自作叢。","前灣更幽絕，雖淺去猶通。"]', '["曲渚迴花舫，生衣臥向风。","鸟飞溪色裏，人語棹声中。","餘卉纔分影，新蒲自作叢。","前灣更幽絕，雖淺去猶通。"]', '诗', 'shi', '', NULL, '泛溪 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f206dce-b488-46c6-8ec7-ffd730373db9', '宿陳處士書齋', '宿陳处士书斋', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["結茅當此地，下馬見高情。","菰葉寒塘晚，杉陰白石明。","向爐新茗色，隔雪遠鐘聲。","閑得相逢少，吟多寐不成。"]', '["結茅當此地，下马见高情。","菰葉寒塘晚，杉陰白石明。","向爐新茗色，隔雪远鐘声。","闲得相逢少，吟多寐不成。"]', '诗', 'shi', '', NULL, '宿陳處士書齋 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcf41cfc-d052-44b3-8f5c-e52eee610cda', '上宣州沈大夫', '上宣州沈大夫', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["科名繼世古來稀，高步何年下紫微。","帝命幾曾移重鎮，時清猶望領春闈。","登朝舊友常思見，開幕賢人併望歸。","今日得遊風化地，却回滄海有光輝。"]', '["科名繼世古来稀，高步何年下紫微。","帝命幾曾移重鎮，时清猶望領春闈。","登朝旧友常思见，开幕賢人併望归。","今日得游风化地，却回滄海有光輝。"]', '诗', 'shi', '', NULL, '上宣州沈大夫 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1147a91-a65d-4449-a3c0-e6b177b511c9', '杭州送蕭寶校書', '杭州送蕭寶校书', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["馬識青山路，人隨白浪船。","別君猶有淚，學道謾經年。"]', '["马識青山路，人隨白浪船。","別君猶有泪，学道謾經年。"]', '诗', 'shi', '', NULL, '杭州送蕭寶校書 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('996a613d-4623-416f-925f-7b3b4034f997', '送盛長史', '送盛长史', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["莫辭東路遠，此別豈閑行。","職處中軍要，官兼上佐榮。","野亭楓葉暗，秋水藕花明。","拜省期將近，孤舟促去程。"]', '["莫辞东路远，此別豈闲行。","職处中軍要，官兼上佐榮。","野亭楓葉暗，秋水藕花明。","拜省期將近，孤舟促去程。"]', '诗', 'shi', '', NULL, '送盛長史 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02836fc6-a0f8-4b4a-8bc2-d4ac59990067', '宿道士觀', '宿道士观', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["堂閉僊人影，空壇月露初。","閑聽道家子，盥漱讀靈書。"]', '["堂閉僊人影，空壇月露初。","闲听道家子，盥漱读靈书。"]', '诗', 'shi', '', NULL, '宿道士觀 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c45eef97-a07f-4999-9f67-e863e9828310', '湖州韓使君置宴', '湖州韓使君置宴', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["老大成名仍足病，縱聽絲竹也無歡。","高情太守容閑坐，借與青山盡日看。"]', '["老大成名仍足病，縱听絲竹也無歡。","高情太守容闲坐，借與青山尽日看。"]', '诗', 'shi', '', NULL, '湖州韓使君置宴 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e63f4cf-a078-44df-814f-8bea0929e526', '題僊遊寺', '題僊游寺', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["石抱龍堂蘚石乾，山遮白日寺門寒。","長松瀑布饒奇狀，曾有仙人駐鶴看。"]', '["石抱龙堂蘚石乾，山遮白日寺门寒。","长松瀑布饒奇狀，曾有仙人駐鹤看。"]', '诗', 'shi', '', NULL, '題僊遊寺 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab4b1a7f-4fbe-438b-817f-9e1ed2d39f4f', '宮詞', '宮词', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["寂寂花時閉院門，美人相並立瓊軒。","含情欲說宮中事，鸚鵡前頭不敢言。"]', '["寂寂花时閉院门，美人相並立瓊軒。","含情欲说宮中事，鸚鵡前头不敢言。"]', '诗', 'shi', '', NULL, '宮詞 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dcb7fd8-a1a6-434b-bb80-fa6923197085', '公子行', '公子行', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["閑從結客冶遊時，忘却紅樓薄暮期。","醉上黃金堤上去，馬鞭捎斷綠楊絲。"]', '["闲從結客冶游时，忘却紅楼薄暮期。","醉上黄金堤上去，马鞭捎斷綠楊絲。"]', '诗', 'shi', '', NULL, '公子行 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6e38b16-b83d-41e0-8839-d6d29bb3bf15', '送陳摽', '送陳摽', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["滿酌勸童僕，好隨郎馬蹄。","春風慎行李，莫上白銅鞮。"]', '["满酌勸童僕，好隨郎马蹄。","春风慎行李，莫上白銅鞮。"]', '诗', 'shi', '', NULL, '送陳摽 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c7e86af-7eac-43e4-95ff-e1e4c3cd9ab0', '尋古觀', '尋古观', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["僊觀曾過知不遠，花藏石室杳難尋。","泉邊白鹿聞人語，看過天壇漸入深。"]', '["僊观曾過知不远，花藏石室杳难尋。","泉邊白鹿闻人語，看過天壇漸入深。"]', '诗', 'shi', '', NULL, '尋古觀 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b92e129-ad6b-4fd6-a097-20aff22782bf', '南嶺路', '南嶺路', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["越嶺向南風景異，人人傳說到京城。","經冬來往不踏雪，盡在刺桐花下行。"]', '["越嶺向南风景異，人人傳说到京城。","經冬来往不踏雪，尽在刺桐花下行。"]', '诗', 'shi', '', NULL, '南嶺路 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a94fee19-9e17-47d9-a9c2-7c1d6536d14b', '陪江州李使君重陽宴百花亭', '陪江州李使君重陽宴百花亭', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["閑攜九日酒，共到百花亭。","醉裏求詩境，回看島嶼青。"]', '["闲携九日酒，共到百花亭。","醉裏求诗境，回看島嶼青。"]', '诗', 'shi', '', NULL, '陪江州李使君重陽宴百花亭 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a741fa0a-099c-425e-91c5-e1d67a946da2', '上張水部', '上張水部', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["出入門闌久，兒童亦有情。","不忘將姓字，常說向公卿。","每許連牀坐，仍容並馬行。","恩深轉無語，懷抱甚分明。"]', '["出入门闌久，兒童亦有情。","不忘將姓字，常说向公卿。","每許連牀坐，仍容並马行。","恩深轉無語，懷抱甚分明。"]', '诗', 'shi', '', NULL, '上張水部 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('062ac841-d778-469b-ae73-3dcc872b25a9', '鳳翔西池與賈島納涼', '鳳翔西池與賈島納涼', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["四面無炎氣，清池闊復深。","蝶飛逢草住，魚戲見人沉。","拂石安茶器，移牀選樹陰。","幾迴同到此，盡日得閑吟。"]', '["四面無炎氣，清池闊复深。","蝶飞逢草住，鱼戲见人沉。","拂石安茶器，移牀選樹陰。","幾迴同到此，尽日得闲吟。"]', '诗', 'shi', '', NULL, '鳳翔西池與賈島納涼 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b980f56-638a-45b7-8466-99a3be06dcc7', '上汴州令狐相公', '上汴州令狐相公', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["罷相恩猶在，那容處靜司。","政嚴初領節，名重更因詩。","公事巡營外，戎裝拜勅時。","恭聞長與善，應念出身遲。"]', '["罷相恩猶在，那容处静司。","政嚴初領節，名重更因诗。","公事巡營外，戎裝拜勅时。","恭闻长與善，應念出身遲。"]', '诗', 'shi', '', NULL, '上汴州令狐相公 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ce4374a-ac10-45b6-9a47-cc5582ed76f1', '送于中丞入蕃冊立', '送于中丞入蕃冊立', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["上馬生邊思，戎裝別衆僚。","雙旌銜命重，空磧去程遙。","迥沒沙中樹，孤飛雪外鵰。","蕃庭過冊禮，幾日却回朝。"]', '["上马生邊思，戎裝別衆僚。","雙旌銜命重，空磧去程遙。","迥沒沙中樹，孤飞雪外鵰。","蕃庭過冊禮，幾日却回朝。"]', '诗', 'shi', '', NULL, '送于中丞入蕃冊立 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52fef130-01f0-46c7-987a-5bd24ec02b44', '送淮陰丁明府', '送淮陰丁明府', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["之官未入境，已有愛人心。","遣吏回中路，停舟對遠林。","島聲淮浪靜，雨色稻苗深。","暇日公門掩，唯應伴客吟。"]', '["之官未入境，已有愛人心。","遣吏回中路，停舟对远林。","島声淮浪静，雨色稻苗深。","暇日公门掩，唯應伴客吟。"]', '诗', 'shi', '', NULL, '送淮陰丁明府 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc2c5e6b-d9f7-4fdd-913b-875760551bea', '送韋校書佐靈州幕', '送韋校书佐靈州幕', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["共知行處樂，猶惜此時分。","職已爲書記，官曾校典墳。","寒城初落葉，高戍遠生雲。","邊事何須問，深謀祗在君。"]', '["共知行处乐，猶惜此时分。","職已爲书記，官曾校典墳。","寒城初落葉，高戍远生云。","邊事何須问，深謀祗在君。"]', '诗', 'shi', '', NULL, '送韋校書佐靈州幕 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0487b39-8c88-4ca4-b541-f83ebfd93c3b', '上江州李史君', '上江州李史君', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["起家聲望重，自古更誰過。","得在朝廷少，還因諫諍多。","經年愁瘴癘，幾處遇恩波。","入境無餘事，唯聞父老歌。"]', '["起家声望重，自古更誰過。","得在朝廷少，還因諫諍多。","經年愁瘴癘，幾处遇恩波。","入境無餘事，唯闻父老歌。"]', '诗', 'shi', '', NULL, '上江州李史君 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6714559c-639e-4b92-8354-b78a55e2fd27', '發鳳翔後塗中懷田少府', '發鳳翔後塗中懷田少府', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["識君春未半，意欲住經秋。","見酒連詩句，逢花跋馬頭。","別來唯獨宿，夢裏尚同游。","所在求飱過，無因離得愁。"]', '["識君春未半，意欲住經秋。","见酒連诗句，逢花跋马头。","別来唯独宿，梦裏尚同游。","所在求飱過，無因離得愁。"]', '诗', 'shi', '', NULL, '發鳳翔後塗中懷田少府 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('446315f0-3740-4248-8cf7-1dce97d9336e', '雪夜與真上人宿韓協律宅', '雪夜與真上人宿韓協律宅', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["斜雪微霑砌，空堂夜語清。","逆風聽漏短，回燭向樓明。","盥漱隨禪伴，謳吟得野情。","此歡那敢忘，世貴丈夫名。"]', '["斜雪微霑砌，空堂夜語清。","逆风听漏短，回燭向楼明。","盥漱隨禪伴，謳吟得野情。","此歡那敢忘，世貴丈夫名。"]', '诗', 'shi', '', NULL, '雪夜與真上人宿韓協律宅 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f56607-3ef1-4686-b1b6-2c9c3ff3fd48', '與賈島顧非熊無可上人宿萬年姚少府宅', '與賈島顧非熊無可上人宿万年姚少府宅', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["莫厭通宵坐，貧中會聚難。","堂虛雪氣入，燈在漏聲殘。","役思因生病，當禪豈覺寒。","開門各有事，非不惜餘歡。"]', '["莫厭通宵坐，貧中會聚难。","堂虛雪氣入，灯在漏声殘。","役思因生病，當禪豈覺寒。","开门各有事，非不惜餘歡。"]', '诗', 'shi', '', NULL, '與賈島顧非熊無可上人宿萬年姚少府宅 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efd28f83-a3b4-4297-9de7-80a215b4f84d', '震爲蒼筤竹', '震爲蒼筤竹', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["爲擢東方秀，修然異衆筠。","青蒼纔映粉，蒙密正含春。","嫩籜霑微雨，幽根絕細塵。","乍憐分徑小，偏覺帶煙新。","結實皆留鳳，垂陰似庇人。","顧唯竿在手，深水掛頳鱗。"]', '["爲擢东方秀，修然異衆筠。","青蒼纔映粉，蒙密正含春。","嫩籜霑微雨，幽根絕細塵。","乍怜分徑小，偏覺带煙新。","結實皆留鳳，垂陰似庇人。","顧唯竿在手，深水掛頳鱗。"]', '诗', 'shi', '', NULL, '震爲蒼筤竹 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba7b4d84-d1e4-4ca1-96c1-06c5fbf84549', '題青龍寺', '題青龙寺', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["寺好因崗勢，登臨值夕陽。","青山當佛閣，紅葉滿僧廊。","竹色連平地，蟲聲在上方。","最憐東面靜，爲近楚城牆。"]', '["寺好因崗勢，登臨值夕陽。","青山當佛閣，紅葉满僧廊。","竹色連平地，蟲声在上方。","最怜东面静，爲近楚城牆。"]', '诗', 'shi', '', NULL, '題青龍寺 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44b4e1e8-5c87-4cd6-8bbd-9b702a9d1ab8', '送滕庶子致仕歸江南', '送滕庶子致仕归江南', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["常懷獨往意，此日去朝簪。","丹詔榮歸騎，清風滿故林。","諸侯新起敬，遺老重相尋。","在處饒山水，堪行慰所心。"]', '["常懷独往意，此日去朝簪。","丹詔榮归騎，清风满故林。","諸侯新起敬，遺老重相尋。","在处饒山水，堪行慰所心。"]', '诗', 'shi', '', NULL, '送滕庶子致仕歸江南 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24066101-5b6f-4fea-9e95-bd01a687c6ed', '夏日題武功姚主簿', '夏日題武功姚主簿', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["亭午無公事，垂簾樹色間。","僧來茶竈動，吏去印牀閑。","傍竹行尋巷，當門立看山。","吟詩老不倦，未省話官班。"]', '["亭午無公事，垂簾樹色间。","僧来茶竈动，吏去印牀闲。","傍竹行尋巷，當门立看山。","吟诗老不倦，未省話官班。"]', '诗', 'shi', '', NULL, '夏日題武功姚主簿 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25bc9104-e1ed-4156-a8f0-757d015e7b8c', '送張景宣下第東歸', '送張景宣下第东归', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["歸省值花時，閑吟落第詩。","高情憐道在，公論覺才遺。","春雨連淮暗，私船過馬遲。","離心可惆悵，爲有入城期。"]', '["归省值花时，闲吟落第诗。","高情怜道在，公論覺才遺。","春雨連淮暗，私船過马遲。","離心可惆悵，爲有入城期。"]', '诗', 'shi', '', NULL, '送張景宣下第東歸 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59c05369-714c-43ba-842a-76548b3f21d7', '送顧非熊下第歸', '送顧非熊下第归', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["但取詩名遠，寧論下第頻。","惜爲今日別，共受幾年貧。","聽雨宿吳寺，過江逢越人。","知從本府薦，秋晚又辭親。"]', '["但取诗名远，寧論下第頻。","惜爲今日別，共受幾年貧。","听雨宿吳寺，過江逢越人。","知從本府薦，秋晚又辞親。"]', '诗', 'shi', '', NULL, '送顧非熊下第歸 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94810bad-0859-4cac-894c-e0de17e1a50e', '送韋繇校書赴浙東幕', '送韋繇校书赴浙东幕', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["丞相辟書新，秋關獨去人。","官離芸閣早，名占甲科頻。","水驛迎船火，山城候騎塵。","湖邊寄家久，到日喜榮親。"]', '["丞相辟书新，秋关独去人。","官離芸閣早，名占甲科頻。","水驛迎船火，山城候騎塵。","湖邊寄家久，到日喜榮親。"]', '诗', 'shi', '', NULL, '送韋繇校書赴浙東幕 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('432dda35-564f-44cf-b5a8-a5dc9b75f544', '尋賈島所居', '尋賈島所居', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["求閑身未得，此日到京東。","獨在鐘聲外，相逢樹色中。","誰言人漸老，所向意皆同。","月上因留宿，移牀對藥叢。"]', '["求闲身未得，此日到京东。","独在鐘声外，相逢樹色中。","誰言人漸老，所向意皆同。","月上因留宿，移牀对藥叢。"]', '诗', 'shi', '', NULL, '尋賈島所居 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f39a48-846f-4b29-9a0e-3b9cce64608b', '題毗陵上人院', '題毗陵上人院', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["院深終日靜，落葉覆秋蟲。","盥漱新齋後，修行未老中。","映松山色遠，隔水磬聲通。","此處宜清夜，高吟永與同。"]', '["院深終日静，落葉覆秋蟲。","盥漱新斋後，修行未老中。","映松山色远，隔水磬声通。","此处宜清夜，高吟永與同。"]', '诗', 'shi', '', NULL, '題毗陵上人院 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57c950fd-3711-48dc-8df3-09555f1d7a7c', '送李侍御入蕃', '送李侍御入蕃', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["遠使隨雙節，新官屬外臺。","戎裝非好武，書記本多才。","移帳依泉宿，迎人帶雪來。","心知玉關道，稀見一花開。"]', '["远使隨雙節，新官屬外台。","戎裝非好武，书記本多才。","移帳依泉宿，迎人带雪来。","心知玉关道，稀见一花开。"]', '诗', 'shi', '', NULL, '送李侍御入蕃 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b5093e-0faf-4f93-ab77-a843168acea5', '望蕭關', '望蕭关', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["漸見風沙暗，蕭關欲到時。","兒童能探火，婦女解縫旗。","川絕銜魚鷺，林多帶箭麋。","暫來戎馬地，不敢苦吟詩。"]', '["漸见风沙暗，蕭关欲到时。","兒童能探火，婦女解縫旗。","川絕銜鱼鷺，林多带箭麋。","暫来戎马地，不敢苦吟诗。"]', '诗', 'shi', '', NULL, '望蕭關 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40401dc2-a6a3-46f2-bd6f-68198b7a2309', '送韓校書赴江西幕', '送韓校书赴江西幕', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["從軍五湖外，終是稱詩人。","酒後愁將別，塗中過却春。","山橋槲葉暗，水館燕巢新。","驛舫迎應遠，京書寄自頻。","野情隨到處，公務日關身。","久共趨名利，龍鍾獨滯秦。"]', '["從軍五湖外，終是稱诗人。","酒後愁將別，塗中過却春。","山橋槲葉暗，水館燕巢新。","驛舫迎應远，京书寄自頻。","野情隨到处，公務日关身。","久共趨名利，龙鍾独滯秦。"]', '诗', 'shi', '', NULL, '送韓校書赴江西幕 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7a50917-4a37-4197-9af5-dd104c82d60c', '題寄王秘書', '題寄王秘书', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["唯求買藥價，此外更無機。","扶病看紅葉，辭官著白衣。","斷籬通野徑，高樹蔭鄰扉。","時復留僧宿，餘人得見稀。"]', '["唯求買藥價，此外更無機。","扶病看紅葉，辞官著白衣。","斷籬通野徑，高樹蔭鄰扉。","时复留僧宿，餘人得见稀。"]', '诗', 'shi', '', NULL, '題寄王秘書 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e58addbd-ee94-461a-9905-8423b62f91ac', '山居', '山居', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["歸來青壁下，又見滿籬霜。","轉覺琴齋靜，閑從菊地荒。","山泉共鹿飲，林果讓僧嘗。","時復收新藥，隨雲過石梁。"]', '["归来青壁下，又见满籬霜。","轉覺琴斋静，闲從菊地荒。","山泉共鹿饮，林果讓僧嘗。","时复收新藥，隨云過石梁。"]', '诗', 'shi', '', NULL, '山居 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c01fed66-e625-4e38-b851-055447c08c02', '重過惟貞上人院', '重過惟貞上人院', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["老去唯求靜，都忘外學名。","掃牀秋葉滿，對客遠雲生。","香閤閑留宿，晴階暖共行。","窗西暮山色，依舊入詩情。"]', '["老去唯求静，都忘外学名。","掃牀秋葉满，对客远云生。","香閤闲留宿，晴階暖共行。","窗西暮山色，依旧入诗情。"]', '诗', 'shi', '', NULL, '重過惟貞上人院 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcb03337-0b1d-4b63-b8e1-2cb73ed4aca3', '與石晝秀才過普照寺', '與石晝秀才過普照寺', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["問人知寺路，松竹暗春山。","潭黑龍應在，巢空鶴未還。","經年爲客倦，半日與僧閑。","更共嘗新茗，聞鐘笑語間。"]', '["问人知寺路，松竹暗春山。","潭黑龙應在，巢空鹤未還。","經年爲客倦，半日與僧闲。","更共嘗新茗，闻鐘笑語间。"]', '诗', 'shi', '', NULL, '與石晝秀才過普照寺 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7429e111-8b2d-4626-8d4e-f6630e6734b5', '題任處士幽居', '題任处士幽居', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["惜與幽人別，停舟對草堂。","湖雲侵臥位，杉露滴茶牀。","山月吟時在，池花覺後香。","生涯無一物，誰與讀書糧。"]', '["惜與幽人別，停舟对草堂。","湖云侵臥位，杉露滴茶牀。","山月吟时在，池花覺後香。","生涯無一物，誰與读书糧。"]', '诗', 'shi', '', NULL, '題任處士幽居 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a18165e9-9e12-4231-b2b3-19c8b0bcc87f', '送僧往太原謁李司空', '送僧往太原謁李司空', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["已共鄰房別，應無更住心。","中時過野店，後夜宿寒林。","寺去人煙遠，城連塞雪深。","禪餘得新句，堪對上公吟。"]', '["已共鄰房別，應無更住心。","中时過野店，後夜宿寒林。","寺去人煙远，城連塞雪深。","禪餘得新句，堪对上公吟。"]', '诗', 'shi', '', NULL, '送僧往太原謁李司空 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('237b7a55-7821-44b5-b17f-4d30fa311028', '將之上京別淮南書記李侍御', '將之上京別淮南书記李侍御', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["心地偶相見，語多爲別難。","詩成公府晚，路入翠微寒。","逢石自應坐，有花誰共看。","身爲當去鴈，雲盡到長安。"]', '["心地偶相见，語多爲別难。","诗成公府晚，路入翠微寒。","逢石自應坐，有花誰共看。","身爲當去鴈，云尽到长安。"]', '诗', 'shi', '', NULL, '將之上京別淮南書記李侍御 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f91a91-b322-4bc3-b9d1-ac8e7987cc4a', '韓協律相送精舍讀書四韻奉寄呈陸補闕', '韓協律相送精舍读书四韻奉寄呈陸補闕', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["白鶴西山別，更看上去船。","遙知尋寺路，應念宿江煙。","到處無閑日，迴期已隔年。","何因陪夜坐，清論諫臣邊。"]', '["白鹤西山別，更看上去船。","遙知尋寺路，應念宿江煙。","到处無闲日，迴期已隔年。","何因陪夜坐，清論諫臣邊。"]', '诗', 'shi', '', NULL, '韓協律相送精舍讀書四韻奉寄呈陸補闕 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aefce4bf-8330-4f8e-9600-ab3b575b8a02', '過蘇州曉上人院', '過蘇州晓上人院', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["夏滿律當清，無中景自生。","移松不避遠，取石亦親行。","經案離時少，繩牀著處平。","若將林下比，應只欠泉聲。"]', '["夏满律當清，無中景自生。","移松不避远，取石亦親行。","經案離时少，繩牀著处平。","若將林下比，應只欠泉声。"]', '诗', 'shi', '', NULL, '過蘇州曉上人院 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38c18497-8dd9-4940-b53f-1f8c5e3bc7c4', '送僧遊縉雲', '送僧游縉云', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["但望青山去，何山不是緣。","寺幽堪講律，月冷稱當禪。","水落無風夜，猨吟欲雨天。","尋師若有路，終作緩歸年。"]', '["但望青山去，何山不是緣。","寺幽堪講律，月冷稱當禪。","水落無风夜，猨吟欲雨天。","尋師若有路，終作緩归年。"]', '诗', 'shi', '', NULL, '送僧遊縉雲 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('866579dd-6f4f-4eb0-817a-c6cc917efcbf', '贈道者', '贈道者', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["自識來清瘦，尋常語論真。","藥成休伏火，符驗不傳人。","獨有年過鶴，曾無病到身。","潛教問弟子，居處與誰鄰。"]', '["自識来清瘦，尋常語論真。","藥成休伏火，符驗不傳人。","独有年過鹤，曾無病到身。","潛教问弟子，居处與誰鄰。"]', '诗', 'shi', '', NULL, '贈道者 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00854a31-c67d-4724-b749-4d4b543d2495', '杭州盧錄事山亭', '杭州盧錄事山亭', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["山色滿公署，到來詩景饒。","解衣臨曲榭，隔竹見紅蕉。","清漏焚香夕，輕嵐視事朝。","靜中看鎖印，高處見迎潮。","曳履庭蕪近，當身樹葉飄。","傍城餘菊在，步入一僊瓢。"]', '["山色满公署，到来诗景饒。","解衣臨曲榭，隔竹见紅蕉。","清漏焚香夕，轻嵐視事朝。","静中看鎖印，高处见迎潮。","曳履庭蕪近，當身樹葉飄。","傍城餘菊在，步入一僊瓢。"]', '诗', 'shi', '', NULL, '杭州盧錄事山亭 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceee9e38-7bac-40f6-a79f-653de2f95342', '送品上人入秦', '送品上人入秦', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["獨去何人見，林塘共寂寥。","生緣聞磬早，覺路出塵遙。","江雪霑新草，秦園發故條。","心知禪定處，石室對芭蕉。"]', '["独去何人见，林塘共寂寥。","生緣闻磬早，覺路出塵遙。","江雪霑新草，秦园發故條。","心知禪定处，石室对芭蕉。"]', '诗', 'shi', '', NULL, '送品上人入秦 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('740f2c1c-7c58-49eb-b30e-858618452344', '題薔薇花', '題薔薇花', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["四面垂條密，浮陰入夏清。","綠攢傷手刺，紅墮斷腸英。","粉著蜂鬚膩，光凝蝶翅明。","雨中看亦好，況復值初晴。"]', '["四面垂條密，浮陰入夏清。","綠攢傷手刺，紅墮斷腸英。","粉著蜂鬚膩，光凝蝶翅明。","雨中看亦好，況复值初晴。"]', '诗', 'shi', '', NULL, '題薔薇花 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e43abe1-a112-48be-b127-cb3c98ddf730', '題胡氏溪亭', '題胡氏溪亭', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["亭與溪相近，無時不有風。","澗松生便黑，野蘚看多紅。","雨足秋聲後，山沈夜色中。","主人能守靜，略與客心同。"]', '["亭與溪相近，無时不有风。","澗松生便黑，野蘚看多紅。","雨足秋声後，山沈夜色中。","主人能守静，略與客心同。"]', '诗', 'shi', '', NULL, '題胡氏溪亭 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('626c0e84-2b71-4040-abb5-23eaee8b2bc8', '看濤', '看濤', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["不知來遠近，但見白峨峨。","風雨驅寒玉，魚龍迸上波。","聲長勢未盡，曉去夕還過。","要路橫天塹，其如造化何。"]', '["不知来远近，但见白峨峨。","风雨驱寒玉，鱼龙迸上波。","声长勢未尽，晓去夕還過。","要路橫天塹，其如造化何。"]', '诗', 'shi', '', NULL, '看濤 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7a55c9e-f269-4647-abd8-5144b1d2d5c3', '和劉補闕秋園寓興之什十首 一', '和劉補闕秋园寓兴之什十首 一', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["閑園清氣滿，新興日堪追。","隔水蟬鳴後，當簷鴈過時。","雨餘槐穟重，霜近藥苗衰。","不以朝簪貴，多將野客期。"]', '["闲园清氣满，新兴日堪追。","隔水蟬鳴後，當簷鴈過时。","雨餘槐穟重，霜近藥苗衰。","不以朝簪貴，多將野客期。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 一 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('742ce4e4-6412-4efc-a47f-3d4b15dd32a2', '和劉補闕秋園寓興之什十首 二', '和劉補闕秋园寓兴之什十首 二', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["誰言高靜意，不異在衡茅。","竹冷人離洞，天晴鶴出巢。","深籬藏白菌，荒蔓露青匏。","幾見中宵月，清光墜樹梢。"]', '["誰言高静意，不異在衡茅。","竹冷人離洞，天晴鹤出巢。","深籬藏白菌，荒蔓露青匏。","幾见中宵月，清光墜樹梢。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 二 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a97886d-adff-46aa-b290-53c15483b422', '和劉補闕秋園寓興之什十首 三', '和劉補闕秋园寓兴之什十首 三', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["逍遙人事外，杖屨入杉蘿。","草色寒猶在，蟲聲晚漸多。","靜逢山鳥下，幽稱野僧過。","幾許新開菊，閑從落葉和。"]', '["逍遙人事外，杖屨入杉蘿。","草色寒猶在，蟲声晚漸多。","静逢山鸟下，幽稱野僧過。","幾許新开菊，闲從落葉和。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 三 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13f57522-5598-45e2-a2fb-9a5bab404e40', '和劉補闕秋園寓興之什十首 四', '和劉補闕秋园寓兴之什十首 四', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["留情清景宴，朝罷有餘閑。","蝶散紅蘭外，螢飛白露間。","牆高微見寺，林靜遠分山。","吟足期相訪，殘陽自掩關。"]', '["留情清景宴，朝罷有餘闲。","蝶散紅蘭外，螢飞白露间。","牆高微见寺，林静远分山。","吟足期相訪，殘陽自掩关。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 四 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8508c729-7862-49a8-9719-4daf82d09f99', '和劉補闕秋園寓興之什十首 五', '和劉補闕秋园寓兴之什十首 五', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["深齋嘗獨處，詎肯厭秋聲。","翠篠寒愈靜，孤花晚更明。","每因逢石坐，多見抱書行。","入夜聽疎杵，遙知耿此情。"]', '["深斋嘗独处，詎肯厭秋声。","翠篠寒愈静，孤花晚更明。","每因逢石坐，多见抱书行。","入夜听疎杵，遙知耿此情。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 五 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d819d49f-09dd-475d-a058-6b91807fbd63', '和劉補闕秋園寓興之什十首 六', '和劉補闕秋园寓兴之什十首 六', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["蒼翠經宵在，園廬景自深。","風淒欲去燕，月思向來砧。","碧石當莎逕，寒煙冒竹林。","桮瓢閑寄詠，清絕是知音。"]', '["蒼翠經宵在，园廬景自深。","风淒欲去燕，月思向来砧。","碧石當莎逕，寒煙冒竹林。","桮瓢闲寄詠，清絕是知音。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 六 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e03ecf1-12f3-40f5-97b9-1a01f6531da6', '和劉補闕秋園寓興之什十首 七', '和劉補闕秋园寓兴之什十首 七', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["門巷唯苔蘚，誰言不稱貧。","臺閑人下晚，果熟鳥來頻。","石脈潛通井，松枝靜離塵。","殘蔬得晴後，又見一番新。"]', '["门巷唯苔蘚，誰言不稱貧。","台闲人下晚，果熟鸟来頻。","石脈潛通井，松枝静離塵。","殘蔬得晴後，又见一番新。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 七 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1952331a-e5be-4fba-93f5-44fc83d86553', '和劉補闕秋園寓興之什十首 八', '和劉補闕秋园寓兴之什十首 八', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["捲簾天色靜，近瀨覺衣單。","蕉葉猶停翠，桐陰已爽寒。","雲從高處望，琴愛靜時彈。","正去重陽近，吟秋意未闌。"]', '["捲簾天色静，近瀨覺衣單。","蕉葉猶停翠，桐陰已爽寒。","云從高处望，琴愛静时彈。","正去重陽近，吟秋意未闌。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 八 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf1cf560-66f2-4f61-8506-91e8e6feed2e', '和劉補闕秋園寓興之什十首 九', '和劉補闕秋园寓兴之什十首 九', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["竹逕通鄰圃，清深稱獨遊。","蟲絲交影細，藤子墜聲幽。","積潤苔紋厚，迎寒薺葉稠。","閑來尋古畫，未廢執茶甌。"]', '["竹逕通鄰圃，清深稱独游。","蟲絲交影細，藤子墜声幽。","積潤苔紋厚，迎寒薺葉稠。","闲来尋古畫，未廢執茶甌。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 九 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dbd00e7-6f2e-4b19-8fde-03a101627155', '和劉補闕秋園寓興之什十首 十', '和劉補闕秋园寓兴之什十首 十', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["風物已蕭颯，晚煙生霽容。","斜分紫陌樹，遠隔翠微鐘。","宿客論文靜，閑燈落燼重。","無窮林下意，真得古人風。"]', '["风物已蕭颯，晚煙生霽容。","斜分紫陌樹，远隔翠微鐘。","宿客論文静，闲灯落燼重。","無窮林下意，真得古人风。"]', '诗', 'shi', '', NULL, '和劉補闕秋園寓興之什十首 十 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9056d4f-9c7b-47e9-ab49-0df20de7e568', '上翰林蔣防舍人', '上翰林蔣防舍人', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["清重可過知內制，從前禮絕外庭人。","看花在處多隨駕，召宴無時不及旬。","馬自賜來騎覺穩，詩緣得後意長新。","應憐獨在文場久，十有餘年浪過春。"]', '["清重可過知內制，從前禮絕外庭人。","看花在处多隨駕，召宴無时不及旬。","马自賜来騎覺穩，诗緣得後意长新。","應怜独在文場久，十有餘年浪過春。"]', '诗', 'shi', '', NULL, '上翰林蔣防舍人 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6771f89-b3a9-4c0a-a607-a28a1c701dba', '上翰林李舍人', '上翰林李舍人', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["記得早年曾拜識，便憐孤進賞文章。","免令汩沒慙時輩，與作聲名徹舉場。","一自鳳池承密旨，今因世路接餘光。","雲泥雖隔思長在，縱使無成也不忘。"]', '["記得早年曾拜識，便怜孤進賞文章。","免令汩沒慙时輩，與作声名徹舉場。","一自鳳池承密旨，今因世路接餘光。","云泥雖隔思长在，縱使無成也不忘。"]', '诗', 'shi', '', NULL, '上翰林李舍人 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad651546-e699-4073-9524-0c502f06b2cd', '題章正字道正新居', '題章正字道正新居', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["獨在御樓南畔住，生涯還似舊時貧。","全無竹可侵行逕，一半花猶屬別人。","吟處不妨嫌鼓鬧，眼前唯稱與僧鄰。","近來漸覺青莎巷，車馬過從已有塵。"]', '["独在御楼南畔住，生涯還似旧时貧。","全無竹可侵行逕，一半花猶屬別人。","吟处不妨嫌鼓鬧，眼前唯稱與僧鄰。","近来漸覺青莎巷，车马過從已有塵。"]', '诗', 'shi', '', NULL, '題章正字道正新居 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9134dd15-a8de-470a-9b0b-67882f053ad2', '送李餘及第歸蜀', '送李餘及第归蜀', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["從得高科名轉盛，亦言歸去滿城知。","發時誰不開筵送，到處人爭與馬騎。","劍路紅蕉明棧閣，巴村綠樹蔭神祠。","鄉中後輩遊門館，半是來求近日詩。"]', '["從得高科名轉盛，亦言归去满城知。","發时誰不开筵送，到处人爭與马騎。","劍路紅蕉明棧閣，巴村綠樹蔭神祠。","乡中後輩游门館，半是来求近日诗。"]', '诗', 'shi', '', NULL, '送李餘及第歸蜀 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d04cc1d-1ad6-472c-9de3-75695aae467c', '送唐中丞開淘西湖夏日遊泛因書示郡人', '送唐中丞开淘西湖夏日游泛因书示郡人', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["萍岸新淘見碧霄，中流相去忽成遙。","空餘孤嶼來詩景，無復橫槎礙柳條。","紅斾路幽山翠濕，錦帆風起浪花飄。","共知浸潤同雷澤，何慮川源有旱苗。"]', '["萍岸新淘见碧霄，中流相去忽成遙。","空餘孤嶼来诗景，無复橫槎礙柳條。","紅斾路幽山翠濕，錦帆风起浪花飄。","共知浸潤同雷澤，何慮川源有旱苗。"]', '诗', 'shi', '', NULL, '送唐中丞開淘西湖夏日遊泛因書示郡人 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('135f397f-79dc-4e50-8f5f-274f59c3ccf5', '過舊宅', '過旧宅', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["古巷戟門誰舊宅，早曾聞說屬官家。","更無新燕來巢屋，唯有閑人去看花。","空廐欲摧塵滿櫪，小池初涸草侵沙。","榮華事歇皆如此，立馬踟躕到日斜。"]', '["古巷戟门誰旧宅，早曾闻说屬官家。","更無新燕来巢屋，唯有闲人去看花。","空廐欲摧塵满櫪，小池初涸草侵沙。","榮华事歇皆如此，立马踟躕到日斜。"]', '诗', 'shi', '', NULL, '過舊宅 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d76058cf-498c-4b25-bfa4-f88124a662c7', '鄂渚送白舍人赴杭州', '鄂渚送白舍人赴杭州', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["豈知鸚鵡洲邊路，得見鳳皇池上人。","從此不同諸客禮，故鄉西與郡城鄰。"]', '["豈知鸚鵡洲邊路，得见鳳皇池上人。","從此不同諸客禮，故乡西與郡城鄰。"]', '诗', 'shi', '', NULL, '鄂渚送白舍人赴杭州 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b0b920d-2e23-4075-8766-efcfb52cf365', '題崔駙馬林亭', '題崔駙马林亭', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["選居幽近御街東，易得詩人聚會同。","白練鳥飛深竹裏，朱弦琴在亂書中。","亭開山色當高枕，樓靜簫聲落遠風。","何事宦塗猶寂寞，都緣清苦道難通。"]', '["選居幽近御街东，易得诗人聚會同。","白練鸟飞深竹裏，朱弦琴在亂书中。","亭开山色當高枕，楼静簫声落远风。","何事宦塗猶寂寞，都緣清苦道难通。"]', '诗', 'shi', '', NULL, '題崔駙馬林亭 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ae54ca9-b3d5-468c-99cd-89105be7c74d', '贈韓協律', '贈韓協律', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["永日微吟在竹前，骨清唯愛漱寒泉。","門閑多有投文客，身病長無買藥錢。","嶺寺聽猨頻獨宿，湖亭避宴動經年。","親知盡怪疎榮祿，的是將心暗學禪。"]', '["永日微吟在竹前，骨清唯愛漱寒泉。","门闲多有投文客，身病长無買藥錢。","嶺寺听猨頻独宿，湖亭避宴动經年。","親知尽怪疎榮祿，的是將心暗学禪。"]', '诗', 'shi', '', NULL, '贈韓協律 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52ed960a-431b-4146-91bf-97f54e37634e', '自蕭關望臨洮', '自蕭关望臨洮', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["玉關西路出臨洮，風卷邊沙入馬毛。","寺寺院中無竹樹，家家壁上有弓刀。","惟憐戰士垂金甲，不尚游人著白袍。","日暮獨吟秋色裏，平原一望戍樓高。"]', '["玉关西路出臨洮，风卷邊沙入马毛。","寺寺院中無竹樹，家家壁上有弓刀。","惟怜戰士垂金甲，不尚游人著白袍。","日暮独吟秋色裏，平原一望戍楼高。"]', '诗', 'shi', '', NULL, '自蕭關望臨洮 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed92ee70-1aef-49a2-8524-3f1c45ceb69b', '送崔約下第歸淮南覲省', '送崔約下第归淮南覲省', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["遠憶拜親留不住，出門行計與誰同。","程塗半是依船上，請謁多愁值雨中。","堰水靜連隄樹綠，村橋時映野花紅。","迴期須及來春事，莫便江邊逐釣翁。"]', '["远憶拜親留不住，出门行計與誰同。","程塗半是依船上，請謁多愁值雨中。","堰水静連隄樹綠，村橋时映野花紅。","迴期須及来春事，莫便江邊逐釣翁。"]', '诗', 'shi', '', NULL, '送崔約下第歸淮南覲省 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7ff924e-3483-4eac-aa32-ed49102a9a08', '羽林郎', '羽林郎', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["紫髯年少奉恩初，直閤將軍盡不如。","酒後引兵圍百草，風前駐斾領邊書。","宅將公主同時賜，官與中郎共日除。","大笑魯儒年四十，腰間猶未識金魚。"]', '["紫髯年少奉恩初，直閤將軍尽不如。","酒後引兵圍百草，风前駐斾領邊书。","宅將公主同时賜，官與中郎共日除。","大笑魯儒年四十，腰间猶未識金鱼。"]', '诗', 'shi', '', NULL, '羽林郎 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55030410-716b-4d67-a1b0-e0a4c5879e0d', '歸故園', '归故园', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["桑柘駢闐數畝間，門前五柳正堪攀。","尊中美酒長須滿，身外浮名總是閑。","竹逕有時風爲掃，柴門無事日常關。","於焉已是忘機地，何用將金別買山。"]', '["桑柘駢闐數畝间，门前五柳正堪攀。","尊中美酒长須满，身外浮名總是闲。","竹逕有时风爲掃，柴门無事日常关。","於焉已是忘機地，何用將金別買山。"]', '诗', 'shi', '', NULL, '歸故園 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d397f9ff-61b3-4a59-896a-2ecbbb1086e0', '同友人看花', '同友人看花', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["尋花不問春深淺，縱是殘紅也入詩。","每箇樹邊行一匝，誰家園裏最多時。"]', '["尋花不问春深淺，縱是殘紅也入诗。","每箇樹邊行一匝，誰家园裏最多时。"]', '诗', 'shi', '', NULL, '同友人看花 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28dc6a9c-4ddc-469b-b67c-f0644feed392', '種花', '種花', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["憶昔兩京官道上，可憐桃李晝陰垂。","不知誰作巡花使，空記玄宗遣種時。"]', '["憶昔兩京官道上，可怜桃李晝陰垂。","不知誰作巡花使，空記玄宗遣種时。"]', '诗', 'shi', '', NULL, '種花 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d37ca52-f091-4b6e-974c-2b1426c9647d', '早發廬江塗中遇雪寄李侍御', '早發廬江塗中遇雪寄李侍御', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["蘆葦聲多雁滿陂，濕雲連野見山稀。","遙知將吏相逢處，半是春城賀雪歸。"]', '["蘆葦声多雁满陂，濕云連野见山稀。","遙知將吏相逢处，半是春城賀雪归。"]', '诗', 'shi', '', NULL, '早發廬江塗中遇雪寄李侍御 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a69a13-5946-44c8-99d1-fb2f5871aeef', '登望雲亭招友', '登望云亭招友', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["日日恐無雲可望，不辭逐靜望來頻。","共知亭下眠雲遠，解到上頭能幾人。"]', '["日日恐無云可望，不辞逐静望来頻。","共知亭下眠云远，解到上头能幾人。"]', '诗', 'shi', '', NULL, '登望雲亭招友 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e22c844d-82f0-4e04-8ccf-5315e4651e8d', '劉補闕西亭晚宴', '劉補闕西亭晚宴', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["蟲聲已盡菊花乾，共立松陰向晚寒。","對酒看山俱惜去，不知斜月下欄干。"]', '["蟲声已尽菊花乾，共立松陰向晚寒。","对酒看山俱惜去，不知斜月下欄干。"]', '诗', 'shi', '', NULL, '劉補闕西亭晚宴 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9f8b755-0cf3-4caf-8b6b-cb9e944ce223', '送長安羅少府', '送长安羅少府', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["科名再得年猶少，今日休官更覺賢。","去國已辭趨府伴，向家還入渡江船。","雪晴新雁斜行出，潮落殘雲遠色鮮。","在處若逢山水住，到時應不及秋前。"]', '["科名再得年猶少，今日休官更覺賢。","去国已辞趨府伴，向家還入渡江船。","雪晴新雁斜行出，潮落殘云远色鲜。","在处若逢山水住，到时應不及秋前。"]', '诗', 'shi', '', NULL, '送長安羅少府 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ac93167-4230-4482-b86a-252d3d3b42e2', '林下招胡長官', '林下招胡长官', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["語低清貌似休糧，稱著朱衣入草堂。","銷暑近來無別物，桂陰當午滿繩牀。"]', '["語低清貌似休糧，稱著朱衣入草堂。","銷暑近来無別物，桂陰當午满繩牀。"]', '诗', 'shi', '', NULL, '林下招胡長官 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84a0479f-69ed-4692-adf0-2cfc09356831', '與真上人一二禪師題玢寺主院', '與真上人一二禪師題玢寺主院', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["杖屨相隨任處便，不唯空寄上方眠。","歸時亦取湖邊路，晚映楓林共上船。"]', '["杖屨相隨任处便，不唯空寄上方眠。","归时亦取湖邊路，晚映楓林共上船。"]', '诗', 'shi', '', NULL, '與真上人一二禪師題玢寺主院 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebcb0204-5d42-4df4-bb14-899d6595524b', '尋僧', '尋僧', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["吟背春城出草遲，天晴紫閣赴僧期。","山邊樹下行人少，一派新泉日午時。"]', '["吟背春城出草遲，天晴紫閣赴僧期。","山邊樹下行人少，一派新泉日午时。"]', '诗', 'shi', '', NULL, '尋僧 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5aa4669-250b-4f48-ba8c-bea506b3b046', '題王丘長史宅', '題王丘长史宅', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["更無人吏在門前，不似居官似學僊。","藥氣暗侵朝服上，花陰晚到簿書邊。","玉琴閑把看山坐，筒簟長鋪與客眠。","時見街中騎瘦馬，低頭只是爲詩篇。"]', '["更無人吏在门前，不似居官似学僊。","藥氣暗侵朝服上，花陰晚到簿书邊。","玉琴闲把看山坐，筒簟长鋪與客眠。","时见街中騎瘦马，低头只是爲诗篇。"]', '诗', 'shi', '', NULL, '題王丘長史宅 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef86d45a-dd2b-4fd4-b278-423814d09cb1', '寄劉少府', '寄劉少府', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["唯愛圖書兼古器，在官猶自未離貧。","更聞縣去青山近，稱與詩人作主人。"]', '["唯愛圖书兼古器，在官猶自未離貧。","更闻縣去青山近，稱與诗人作主人。"]', '诗', 'shi', '', NULL, '寄劉少府 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb702bdc-4e71-4794-b520-f32b0ce31945', '哭胡遇', '哭胡遇', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["尋僧昨日尚相隨，忽見緋幡意可知。","題處舊詩休更讀，買來新馬憶曾騎。","不應隨分空營奠，終擬求人與立碑。","每向宣陽里中過，遙聞哭臨淚先垂。"]', '["尋僧昨日尚相隨，忽见緋幡意可知。","題处旧诗休更读，買来新马憶曾騎。","不應隨分空營奠，終擬求人與立碑。","每向宣陽里中過，遙闻哭臨泪先垂。"]', '诗', 'shi', '', NULL, '哭胡遇 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0cfda5e-1d17-4f80-96b6-5594df5cdc31', '自述', '自述', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["詩人甘寂寞，居處遍蒼苔。","後夜蟾光滿，鄰家樹影來。","豈知蓮帳好，自愛草堂開。","願答相思意，援毫愧不才。"]', '["诗人甘寂寞，居处遍蒼苔。","後夜蟾光满，鄰家樹影来。","豈知蓮帳好，自愛草堂开。","願答相思意，援毫愧不才。"]', '诗', 'shi', '', NULL, '自述 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f3d01f4-dafd-4b90-b1e8-144e6f0e39e9', '省試晦日與同志昆明池泛舟', '省試晦日與同志昆明池泛舟', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["故人同泛處，遠色望中明。","靜見沙痕露，微思月魄生。","周回餘雪在，浩渺暮雲平。","戲鳥隨蘭棹，空波盪石鯨。","劫灰難問理，島樹偶知名。","自省曾追賞，無如此日情。"]', '["故人同泛处，远色望中明。","静见沙痕露，微思月魄生。","周回餘雪在，浩渺暮云平。","戲鸟隨蘭棹，空波盪石鯨。","劫灰难问理，島樹偶知名。","自省曾追賞，無如此日情。"]', '诗', 'shi', '', NULL, '省試晦日與同志昆明池泛舟 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2adcf850-97db-4e8f-8bc8-fa473122a1c1', '送崔拾遺赴闕', '送崔拾遺赴闕', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["清貌淩寒玉，朝來拜拾遺。","行承天子詔，去感主人知。","劒佩分班日，風霜獨立時。","名高住不得，非與九霄期。"]', '["清貌淩寒玉，朝来拜拾遺。","行承天子詔，去感主人知。","劒佩分班日，风霜独立时。","名高住不得，非與九霄期。"]', '诗', 'shi', '', NULL, '送崔拾遺赴闕 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c7f3ee-93d1-4ed0-99da-cd401181d030', '酬李處士見贈', '酬李处士见贈', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["干上非無援，才多却累身。","雲霄未得路，江海作閑人。","久別唯謀道，相逢不話貧。","行藏一如此，可便老風塵。"]', '["干上非無援，才多却累身。","云霄未得路，江海作闲人。","久別唯謀道，相逢不話貧。","行藏一如此，可便老风塵。"]', '诗', 'shi', '', NULL, '酬李處士見贈 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d45680-0b25-46ca-9d61-656bfb18f605', '送僧遊溫州', '送僧游溫州', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["夏滿隨所適，江湖非繫緣。","卷經離嶠寺，隔葦上秋船。","水落無風夜，猨啼欲雨天。","石門期獨往，謝守有遺篇。"]', '["夏满隨所適，江湖非繫緣。","卷經離嶠寺，隔葦上秋船。","水落無风夜，猨啼欲雨天。","石门期独往，謝守有遺篇。"]', '诗', 'shi', '', NULL, '送僧遊溫州 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21bb6db5-e3c2-448d-9258-096e0bbda95d', '夢謝亭', '梦謝亭', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["夢後何人見，孤亭似舊時。","褰開誠得地，冥感竟因詩。","不往過應少，悲來下獨遲。","顧慙非謝客，靈貺杳難追。"]', '["梦後何人见，孤亭似旧时。","褰开誠得地，冥感竟因诗。","不往過應少，悲来下独遲。","顧慙非謝客，靈貺杳难追。"]', '诗', 'shi', '', NULL, '夢謝亭 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6221209e-61c5-44ad-93ae-6198ffe21510', '河亭', '河亭', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["孤亭臨絕岸，猨鳥識幽蹊。","花落曾誰到，詩成獨未題。","潮痕經雨在，石筍與杉齊。","謝守便登陟，秋來屐齒低。"]', '["孤亭臨絕岸，猨鸟識幽蹊。","花落曾誰到，诗成独未題。","潮痕經雨在，石筍與杉齊。","謝守便登陟，秋来屐齒低。"]', '诗', 'shi', '', NULL, '河亭 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13e0fbbf-4cf6-4435-9062-186db1e23400', '送吳秀才之山西', '送吳秀才之山西', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["澤潞西邊路，蘭橈北去人。","出門誰恨別，投分不緣貧。","桮酒從年少，知音在日新。","東湖發詩意，夏卉竟如春。"]', '["澤潞西邊路，蘭橈北去人。","出门誰恨別，投分不緣貧。","桮酒從年少，知音在日新。","东湖發诗意，夏卉竟如春。"]', '诗', 'shi', '', NULL, '送吳秀才之山西 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b99d9eb-c052-4422-b5d1-245028e52f53', '和處州嚴郎中遊南溪', '和处州嚴郎中游南溪', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["四望非人境，從前洞穴深。","潭清蒲遠岸，嵐積樹無陰。","看草初移屐，捫蘿忽並簪。","世嫌山水僻，誰伴謝公吟。"]', '["四望非人境，從前洞穴深。","潭清蒲远岸，嵐積樹無陰。","看草初移屐，捫蘿忽並簪。","世嫌山水僻，誰伴謝公吟。"]', '诗', 'shi', '', NULL, '和處州嚴郎中遊南溪 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0105e62d-6794-41bd-beaa-f7f52e2badad', '秋宵讌別盧侍御', '秋宵讌別盧侍御', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["風亭弦管絕，玉漏一聲新。","綠茗香醒酒，寒燈靜照人。","清班無意戀，素業本來貧。","明發青山道，誰逢去馬塵。"]', '["风亭弦管絕，玉漏一声新。","綠茗香醒酒，寒灯静照人。","清班無意戀，素業本来貧。","明發青山道，誰逢去马塵。"]', '诗', 'shi', '', NULL, '秋宵讌別盧侍御 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd28681-ff10-48a6-ae7f-9b2ab52f702d', '酬于訢校書見貽', '酬于訢校书见貽', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["能□得從軍，清嬴□□□。","綺羅徒滿目，山水不離心。","暫別愁花老，相思倚竹陰。","家貧無以養，未可話抽簪。"]', '["能□得從軍，清嬴□□□。","綺羅徒满目，山水不離心。","暫別愁花老，相思倚竹陰。","家貧無以養，未可話抽簪。"]', '诗', 'shi', '', NULL, '酬于訢校書見貽 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ec9ae57-d8b4-40bd-8db6-d2a279bbc828', '送石協律歸吳興別業', '送石協律归吳兴別業', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["識來無定居，此去復何如。","一與耕者遇，轉將朝客疎。","資身唯藥草，教子但詩書。","曾許黃庭本，斯言豈合虛。"]', '["識来無定居，此去复何如。","一與耕者遇，轉將朝客疎。","資身唯藥草，教子但诗书。","曾許黄庭本，斯言豈合虛。"]', '诗', 'shi', '', NULL, '送石協律歸吳興別業 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('700bbfba-a827-4381-9702-1545490581b5', '同盧校書遊新興寺', '同盧校书游新兴寺', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["山深雲景別，有寺亦堪過。","才子將迎遠，林僧氣性和。","潭清蒲影定，松老鶴聲多。","豈不思公府，其如野興何。"]', '["山深云景別，有寺亦堪過。","才子將迎远，林僧氣性和。","潭清蒲影定，松老鹤声多。","豈不思公府，其如野兴何。"]', '诗', 'shi', '', NULL, '同盧校書遊新興寺 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bff10ce6-0511-4977-b5af-593caa8027f7', '送馬秀才', '送马秀才', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["清貌不識睡，見來嘗苦吟。","風塵歸省日，江海寄家心。","與鶴期前島，隨僧過遠林。","相於竟何事，無語與知音。"]', '["清貌不識睡，见来嘗苦吟。","风塵归省日，江海寄家心。","與鹤期前島，隨僧過远林。","相於竟何事，無語與知音。"]', '诗', 'shi', '', NULL, '送馬秀才 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1caa4d86-6876-4497-80b4-331a71d7e71b', '贈律師院', '贈律師院', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["粉壁通蓮徑，扁舟到不迷。","葦聲過枕上，湖色滿窗西。","但見修行苦，誰論夏臘低。","閑看種來樹，已覺與身齊。"]', '["粉壁通蓮徑，扁舟到不迷。","葦声過枕上，湖色满窗西。","但见修行苦，誰論夏臘低。","闲看種来樹，已覺與身齊。"]', '诗', 'shi', '', NULL, '贈律師院 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d52c524c-0492-4b47-9833-06872932ce06', '送僧往台嶽', '送僧往台嶽', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["五城初罷講，海上憶閑行。","觸雪麻衣靜，登山竹錫輕。","天寒嶽寺出，日晚島泉清。","坐與幽期遇，何人識此情。"]', '["五城初罷講，海上憶闲行。","觸雪麻衣静，登山竹錫轻。","天寒嶽寺出，日晚島泉清。","坐與幽期遇，何人識此情。"]', '诗', 'shi', '', NULL, '送僧往台嶽 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dc1d88a-8fd6-4f39-b1a3-cea6d1b1d796', '送惠雅上人西遊', '送惠雅上人西游', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["五湖僧獨往，此去與誰期。","興遠常憐鶴，禪餘肯廢詩。","望雲回寺晚，爲講到城遲。","還想安居日，應當後夏時。"]', '["五湖僧独往，此去與誰期。","兴远常怜鹤，禪餘肯廢诗。","望云回寺晚，爲講到城遲。","還想安居日，應當後夏时。"]', '诗', 'shi', '', NULL, '送惠雅上人西遊 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1374f24-b406-4143-9b5c-22e1d3256261', '將之上京留別淮南書記李侍御', '將之上京留別淮南书記李侍御', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["半似無名位，門當靜處開。","人心皆向德，物色不供才。","酒興春邊過，軍謀意外來。","取名榮相府，却慮詔書催。"]', '["半似無名位，门當静处开。","人心皆向德，物色不供才。","酒兴春邊過，軍謀意外来。","取名榮相府，却慮詔书催。"]', '诗', 'shi', '', NULL, '將之上京留別淮南書記李侍御 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e83f8747-d008-461c-ad9e-344166891581', '送祝秀才歸衢州', '送祝秀才归衢州', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["舊隱縠溪上，憶歸年已深。","學徒花下別，鄉路雪邊尋。","騎吏陪春賞，江僧伴晚吟。","高科如在意，當自惜光陰。"]', '["旧隐縠溪上，憶归年已深。","学徒花下別，乡路雪邊尋。","騎吏陪春賞，江僧伴晚吟。","高科如在意，當自惜光陰。"]', '诗', 'shi', '', NULL, '送祝秀才歸衢州 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('902a47f7-664b-4ff9-bb26-2977375cd042', '過孟浩然舊居', '過孟浩然旧居', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["命合終山水，才非不稱時。","冢邊空有樹，身後獨無兒。","散盡詩篇本，長存道德碑。","平生誰見重，應只是王維。"]', '["命合終山水，才非不稱时。","冢邊空有樹，身後独無兒。","散尽诗篇本，长存道德碑。","平生誰见重，應只是王維。"]', '诗', 'shi', '', NULL, '過孟浩然舊居 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db3e56f-0386-4132-87d4-c5d969e7bdb3', '送虛上人遊天台', '送虛上人游天台', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["青冥通去路，誰見獨隨緣。","此地春前別，何山夜後禪。","石橋隱深樹，朱闕見晴天。","好是修行處，師當住幾年。"]', '["青冥通去路，誰见独隨緣。","此地春前別，何山夜後禪。","石橋隐深樹，朱闕见晴天。","好是修行处，師當住幾年。"]', '诗', 'shi', '', NULL, '送虛上人遊天台 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f6fd6a6-9fcc-4f91-869e-34cc83469a4f', '孔尚書致仕因而有寄贈', '孔尚书致仕因而有寄贈', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["高人心易足，三表乞身閑。","與世長疎索，唯僧得往還。","直聲留闕下，生事在林間。","時復逢清景，乘車看遠山。"]', '["高人心易足，三表乞身闲。","與世长疎索，唯僧得往還。","直声留闕下，生事在林间。","时复逢清景，乘车看远山。"]', '诗', 'shi', '', NULL, '孔尚書致仕因而有寄贈 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('808b90bd-cca2-4269-9726-6d73c3742f66', '和處州韋使君新開南溪', '和处州韋使君新开南溪', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["地里光圖讖，樵人共說深。","悠然想高躅，坐使變荒岑。","疏鑿因殊舊，亭臺亦自今。","靜容猨暫下，閑與鶴同尋。","轉斾馴禽起，褰帷瀑溜侵。","石稀潭見底，嵐暗樹無陰。","躋險難通屐，攀栖稱抱琴。","雲風開物意，潭水識人心。","攜榼巡花遍，移舟惜景沈。","世嫌山水僻，誰伴謝公吟。"]', '["地里光圖讖，樵人共说深。","悠然想高躅，坐使变荒岑。","疏鑿因殊旧，亭台亦自今。","静容猨暫下，闲與鹤同尋。","轉斾馴禽起，褰帷瀑溜侵。","石稀潭见底，嵐暗樹無陰。","躋險难通屐，攀栖稱抱琴。","云风开物意，潭水識人心。","携榼巡花遍，移舟惜景沈。","世嫌山水僻，誰伴謝公吟。"]', '诗', 'shi', '', NULL, '和處州韋使君新開南溪 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d60d838-c54b-4e42-957c-0e60151892d3', '送羅先輩書記歸後却還閩中留別', '送羅先輩书記归後却還閩中留別', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["同是越人從小別，忽歸鄉里見皆驚。","湖邊訪舊知誰在，幕下留歡但覺榮。","望嶺又生紅槿思，登車豈倦白雲程。","況當季父承恩日，廉問南州政已成。"]', '["同是越人從小別，忽归乡里见皆驚。","湖邊訪旧知誰在，幕下留歡但覺榮。","望嶺又生紅槿思，登车豈倦白云程。","況當季父承恩日，廉问南州政已成。"]', '诗', 'shi', '', NULL, '送羅先輩書記歸後却還閩中留別 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1749d518-b7ef-4958-b7a8-f82c3f0e30d2', '送浙東陸中丞', '送浙东陸中丞', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["坐將文教鎮藩維，花滿東南聖主知。","公務肯容私暫入，豐年長與德相隨。","無賢不是朱門客，有子皆如玉樹枝。","自愛此身居樂土，詠歌林下日忘疲。"]', '["坐將文教鎮藩維，花满东南聖主知。","公務肯容私暫入，豐年长與德相隨。","無賢不是朱门客，有子皆如玉樹枝。","自愛此身居乐土，詠歌林下日忘疲。"]', '诗', 'shi', '', NULL, '送浙東陸中丞 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d99b5dd-863a-4b50-ad3d-fe5c9ea8a8d9', '送元處士遊天台', '送元处士游天台', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["青冥路口絕人行，獨與僧期上赤城。","樹列煙嵐春更好，溪藏冰雪夜偏明。","空山雉雊禾苗短，野館風來竹氣清。","若過石橋看瀑布，不妨高處便題名。"]', '["青冥路口絕人行，独與僧期上赤城。","樹列煙嵐春更好，溪藏冰雪夜偏明。","空山雉雊禾苗短，野館风来竹氣清。","若過石橋看瀑布，不妨高处便題名。"]', '诗', 'shi', '', NULL, '送元處士遊天台 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd3f74e0-af6f-412a-ac49-1a5ed59a4acb', '吳興新隄', '吳兴新隄', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["春隄一望思無涯，樹勢還同水勢斜。","深映菰蒲三十里，晴分功利幾千家。","謀成既不勞人力，境遠偏宜隔浪花。","若與青山長作固，汀洲肯恨柳絲遮。"]', '["春隄一望思無涯，樹勢還同水勢斜。","深映菰蒲三十里，晴分功利幾千家。","謀成既不勞人力，境远偏宜隔浪花。","若與青山长作固，汀洲肯恨柳絲遮。"]', '诗', 'shi', '', NULL, '吳興新隄 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1afdc43-3cc3-4a9d-bf37-845f03fbf6d6', '酬蕭員外見寄', '酬蕭員外见寄', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["麥風吹雨正徘徊，忽報書從郡閤來。","道薄謬應宗伯選，詩成徒費謝公才。","九霄示路空知感，十上驚魂尚未回。","勝寄幸容溪館宿，龍鍾慙見妓筵開。","儻期霽後陪新興，一滴還須當一桮。"]', '["麦风吹雨正徘徊，忽報书從郡閤来。","道薄謬應宗伯選，诗成徒費謝公才。","九霄示路空知感，十上驚魂尚未回。","勝寄幸容溪館宿，龙鍾慙见妓筵开。","儻期霽後陪新兴，一滴還須當一桮。"]', '诗', 'shi', '', NULL, '酬蕭員外見寄 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd222bd4-4e40-4f32-90d1-ef505a11cac7', '台州鄭員外郡齋雙鶴', '台州鄭員外郡斋雙鹤', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["丹頂分明音響別，況聞來處隔雲濤。","情懸碧落飛何晚，立近清池意自高。","向夜雙栖驚玉漏，臨軒對舞拂朱袍。","仙郎爲爾開籠早，莫慮回翔損羽毛。"]', '["丹頂分明音响別，況闻来处隔云濤。","情懸碧落飞何晚，立近清池意自高。","向夜雙栖驚玉漏，臨軒对舞拂朱袍。","仙郎爲爾开籠早，莫慮回翔損羽毛。"]', '诗', 'shi', '', NULL, '台州鄭員外郡齋雙鶴 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ac43bcf-beef-4718-8823-44558246b01a', '送竇秀才', '送竇秀才', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["江南才子日紛紛，少有篇章得似君。","清話未同山寺宿，離歌已向客亭聞。","梅天馬上愁黃鳥，澤國帆前見白雲。","通籍名高年又少，回頭應笑晚從軍。"]', '["江南才子日紛紛，少有篇章得似君。","清話未同山寺宿，離歌已向客亭闻。","梅天马上愁黄鸟，澤国帆前见白云。","通籍名高年又少，回头應笑晚從軍。"]', '诗', 'shi', '', NULL, '送竇秀才 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('682a20c9-ff54-4cd2-8889-77725520aa47', '送邵州林使君', '送邵州林使君', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["軒車此去也逢時，地近湘南頗入詩。","一月計程那是遠，中年出守未爲遲。","水邊花氣熏章服，嶺上嵐光照畫旗。","想得化行風土變，州人應爲立生祠。"]', '["軒车此去也逢时，地近湘南頗入诗。","一月計程那是远，中年出守未爲遲。","水邊花氣熏章服，嶺上嵐光照畫旗。","想得化行风土变，州人應爲立生祠。"]', '诗', 'shi', '', NULL, '送邵州林使君 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b46c2a3b-9446-489e-893d-83d9a39a1f92', '送饒州張使君', '送饒州張使君', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["白頭爲郡清秋別，山水南行豈覺賒。","楚老只應思入境，吳兒從此去移家。","館依高嶺分樟葉，路出重江見葦花。","務退唯當吟詠苦，留心曾不在生涯。"]', '["白头爲郡清秋別，山水南行豈覺賒。","楚老只應思入境，吳兒從此去移家。","館依高嶺分樟葉，路出重江见葦花。","務退唯當吟詠苦，留心曾不在生涯。"]', '诗', 'shi', '', NULL, '送饒州張使君 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e2d06b2-71ce-4998-80c8-5a5e8babf791', '題開元寺', '題开元寺', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["西入山門十里程，粉牆書字甚分明。","蕭帝壞陵深虎跡，廣師遺院閉松聲。","長廊畫剝僧形影，石壁塵昏客姓名。","何必更將空色遣，眼前人事是浮生。"]', '["西入山门十里程，粉牆书字甚分明。","蕭帝壞陵深虎跡，廣師遺院閉松声。","长廊畫剝僧形影，石壁塵昏客姓名。","何必更將空色遣，眼前人事是浮生。"]', '诗', 'shi', '', NULL, '題開元寺 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6545b7fb-2947-4cbb-8e58-54a3eb3d5aa0', '與龐復言攜酒望洞庭', '與龐复言携酒望洞庭', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["南湖春色通平遠，貪記詩情忘酒桮。","帆自巴陵山下過，雨從神女峽邊來。","青蒲映水疎還密，白鳥飜空去復回。","盡日與君同看望，了然勝見畫屏開。"]', '["南湖春色通平远，貪記诗情忘酒桮。","帆自巴陵山下過，雨從神女峽邊来。","青蒲映水疎還密，白鸟飜空去复回。","尽日與君同看望，了然勝见畫屏开。"]', '诗', 'shi', '', NULL, '與龐復言攜酒望洞庭 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86aa3f64-8b5f-4f93-b92f-c6a5bf32c8bb', '送浙東周判官', '送浙东周判官', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["久聞從事滄江外，誰謂無官已白頭。","來備戎裝嘶數騎，去持丹詔入孤舟。","蟬鳴遠驛殘陽樹，鷺起湖田片雨秋。","到日重陪丞相宴，鏡湖新月在城樓。"]', '["久闻從事滄江外，誰謂無官已白头。","来備戎裝嘶數騎，去持丹詔入孤舟。","蟬鳴远驛殘陽樹，鷺起湖田片雨秋。","到日重陪丞相宴，镜湖新月在城楼。"]', '诗', 'shi', '', NULL, '送浙東周判官 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae49d63-b763-4c87-b7f3-a97a413b048e', '塞下曲', '塞下曲', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["萬里去長征，連年慣野營。","入羣來擇馬，拋伴去擒生。","箭撚雕翎闊，弓盤鵲角輕。","問看行近遠，西過受降城。"]', '["万里去长征，連年慣野營。","入羣来擇马，拋伴去擒生。","箭撚雕翎闊，弓盤鵲角轻。","问看行近远，西過受降城。"]', '诗', 'shi', '', NULL, '塞下曲 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b18a5e2-6bf7-4ec7-82c7-a637082395a4', '送僧', '送僧', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["客行皆有爲，師去是閑遊。","野望攜金策，禪棲寄石樓。","山深松翠冷，潭靜菊花秋。","幾處題青壁，袈裟濺瀑流。"]', '["客行皆有爲，師去是闲游。","野望携金策，禪棲寄石楼。","山深松翠冷，潭静菊花秋。","幾处題青壁，袈裟濺瀑流。"]', '诗', 'shi', '', NULL, '送僧 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4f9a0ca-0711-4034-8bbb-243ab2db8089', '望早日', '望早日', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["窗下聞雞後，蒼茫映遠林。","纔分天地色，便禁虎狼心。","是處程塗遠，何山洞府深。","此時堪竚望，萬象豁塵襟。"]', '["窗下闻雞後，蒼茫映远林。","纔分天地色，便禁虎狼心。","是处程塗远，何山洞府深。","此时堪竚望，万象豁塵襟。"]', '诗', 'shi', '', NULL, '望早日 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87f011af-0982-4eb7-afe9-52056720f955', '旅中秋月有懷', '旅中秋月有懷', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["久客未還鄉，中秋倍可傷。","暮天飛旅鴈，故國在衡陽。","島外歸雲迥，林間墜葉黃。","數宵千里夢，時見舊書堂。"]', '["久客未還乡，中秋倍可傷。","暮天飞旅鴈，故国在衡陽。","島外归云迥，林间墜葉黄。","數宵千里梦，时见旧书堂。"]', '诗', 'shi', '', NULL, '旅中秋月有懷 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c551a9b5-7f99-41ba-987b-e9913b4f461b', '十六夜月', '十六夜月', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["昨夜忽已過，冰輪始覺虧。","孤光猶不定，浮世更堪疑。","影落澄江海，寒生靜路岐。","皎然銀漢外，長有衆星隨。"]', '["昨夜忽已過，冰輪始覺虧。","孤光猶不定，浮世更堪疑。","影落澄江海，寒生静路岐。","皎然銀漢外，长有衆星隨。"]', '诗', 'shi', '', NULL, '十六夜月 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9c65d21-b81a-429e-8c82-a1a488e9196c', '行路難', '行路难', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["世事澆浮後，艱難向此生。","人心不自足，公道爲誰平。","德喪淳風盡，年荒蔓草盈。","堪悲山下路，非祗客中行。"]', '["世事澆浮後，艱难向此生。","人心不自足，公道爲誰平。","德喪淳风尽，年荒蔓草盈。","堪悲山下路，非祗客中行。"]', '诗', 'shi', '', NULL, '行路難 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bab1e9fc-3843-4daf-a620-8d764ad5725d', '閑居冬末寄友人', '闲居冬末寄友人', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["短亭分袂後，倚檻思偏孤。","雨雪落殘臘，輪蹄在遠塗。","人情難故舊，草色易凋枯。","共有男兒事，何年入帝都。"]', '["短亭分袂後，倚檻思偏孤。","雨雪落殘臘，輪蹄在远塗。","人情难故旧，草色易凋枯。","共有男兒事，何年入帝都。"]', '诗', 'shi', '', NULL, '閑居冬末寄友人 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d6be75a-8988-4ff2-b5eb-3fb57e72a204', '望九疑', '望九疑', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["浮生猶役役，未得便尋真。","白日如無路，青山豈有人。","煙收遙岫小，雨過晚川新。","倚杖何凝望，中宵夢往頻。"]', '["浮生猶役役，未得便尋真。","白日如無路，青山豈有人。","煙收遙岫小，雨過晚川新。","倚杖何凝望，中宵梦往頻。"]', '诗', 'shi', '', NULL, '望九疑 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7b172a2-7feb-4eeb-8841-20743489010b', '贈陳逸人', '贈陳逸人', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["樂道辭榮祿，安居桂水東。","得閑多事外，知足少年中。","藥圃無凡草，松庭有素風。","朝昏吟步處，琴酒與誰同。"]', '["乐道辞榮祿，安居桂水东。","得闲多事外，知足少年中。","藥圃無凡草，松庭有素风。","朝昏吟步处，琴酒與誰同。"]', '诗', 'shi', '', NULL, '贈陳逸人 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('488a2521-03b3-4764-9014-68bc23f55ca4', '湖中閑夜遣興', '湖中闲夜遣兴', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["釣艇同琴酒，良宵背水濱。","風波不起處，星月盡隨身。","浦迥湘煙卷，林香嶽氣春。","誰知此中興，寧羨五湖人。"]', '["釣艇同琴酒，良宵背水濱。","风波不起处，星月尽隨身。","浦迥湘煙卷，林香嶽氣春。","誰知此中兴，寧羨五湖人。"]', '诗', 'shi', '', NULL, '湖中閑夜遣興 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c025561-8e38-4a43-bb1b-103e2caab179', '題娥皇廟', '題娥皇廟', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["娥皇揮涕處，東望九疑天。","往事難重問，孤峰尚慘然。","夜深寒峒響，秋近碧蘿鮮。","未省明君意，遺蹤萬古傳。"]', '["娥皇揮涕处，东望九疑天。","往事难重问，孤峰尚慘然。","夜深寒峒响，秋近碧蘿鲜。","未省明君意，遺蹤万古傳。"]', '诗', 'shi', '', NULL, '題娥皇廟 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd228c0b-0c2e-4029-b701-1a28a3fdb1de', '送友人赴舉', '送友人赴舉', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["世路□□久，嗟君進取身。","十年雖苦志，萬里託何人。","處困非乖道，求名本爲親。","惟應□□意，先與化龍鱗。"]', '["世路□□久，嗟君進取身。","十年雖苦志，万里託何人。","处困非乖道，求名本爲親。","惟應□□意，先與化龙鱗。"]', '诗', 'shi', '', NULL, '送友人赴舉 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02663621-0eb3-4a54-a3cc-d8093e02d35d', '中秋月', '中秋月', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["自古分功定，唯應缺又盈。","一宵當皎潔，四海盡澄清。","靜覺風微起，寒過雪乍傾。","孤高稀此遇，吟賞倍牽情。"]', '["自古分功定，唯應缺又盈。","一宵當皎潔，四海尽澄清。","静覺风微起，寒過雪乍傾。","孤高稀此遇，吟賞倍牽情。"]', '诗', 'shi', '', NULL, '中秋月 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53da8995-85e6-450b-bcef-1f1434c6152a', '宿山居', '宿山居', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["山店燈前客，醻身未有媒。","鄉關貧後別，風雨夜深來。","上國求丹桂，衡門長綠苔。","堪驚雙鬢雪，不待歲寒催。"]', '["山店灯前客，醻身未有媒。","乡关貧後別，风雨夜深来。","上国求丹桂，衡门长綠苔。","堪驚雙鬢雪，不待歲寒催。"]', '诗', 'shi', '', NULL, '宿山居 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('376d8569-1634-4549-9e2a-4f5ae128a1dd', '夏末留別洞庭知己', '夏末留別洞庭知己', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["清秋時節近，分袂獨淒然。","此地折高柳，何門聽暮蟬。","浪搖湖外日，山背楚南天。","空感迢迢事，榮歸在幾年。"]', '["清秋时節近，分袂独淒然。","此地折高柳，何门听暮蟬。","浪搖湖外日，山背楚南天。","空感迢迢事，榮归在幾年。"]', '诗', 'shi', '', NULL, '夏末留別洞庭知己 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa9589ad-2b7a-40d5-9486-8c865d1b884d', '過洞庭', '過洞庭', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["帆挂狂風起，茫茫既往時。","波濤如未息，舟楫亦堪疑。","旅鴈投孤島，長天下四維。","前程有平處，誰敢與心期。"]', '["帆挂狂风起，茫茫既往时。","波濤如未息，舟楫亦堪疑。","旅鴈投孤島，长天下四維。","前程有平处，誰敢與心期。"]', '诗', 'shi', '', NULL, '過洞庭 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b804d84-a944-450e-84c5-dcf889b2b47b', '旅中過重陽', '旅中過重陽', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["一歲重陽至，羈遊在異鄉。","登高思舊友，滿目是窮荒。","草際飛雲片，天涯落鴈行。","故山籬畔菊，今日爲誰黃。"]', '["一歲重陽至，羈游在異乡。","登高思旧友，满目是窮荒。","草際飞云片，天涯落鴈行。","故山籬畔菊，今日爲誰黄。"]', '诗', 'shi', '', NULL, '旅中過重陽 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8492d4-bf1f-494b-a473-51093ac68abf', '送人下第歸', '送人下第归', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["獨立身難達，新春與志違。","異鄉青草長，故國白頭歸。","岸闊湖波溢，程遙楚岫微。","高秋期再會，此去莫忘機。"]', '["独立身难達，新春與志違。","異乡青草长，故国白头归。","岸闊湖波溢，程遙楚岫微。","高秋期再會，此去莫忘機。"]', '诗', 'shi', '', NULL, '送人下第歸 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e543f8-132e-491a-abe9-c1501f07c210', '敘吟', '敘吟', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["雅道辛勤久，潛疑鬢雪侵。","未能酬片善，難更免孤吟。","有景皆牽思，無愁不到心。","遙天一輪月，幾夜見西沈。"]', '["雅道辛勤久，潛疑鬢雪侵。","未能酬片善，难更免孤吟。","有景皆牽思，無愁不到心。","遙天一輪月，幾夜见西沈。"]', '诗', 'shi', '', NULL, '敘吟 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a68da77-b66a-4d2c-89c2-9e0acc450006', '塞下感懷', '塞下感懷', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["塞下閑爲客，鄉心豈易安。","程塗過萬里，身事尚孤寒。","竟日風沙急，臨秋草木殘。","何年方致主，時拂劒塵看。"]', '["塞下闲爲客，乡心豈易安。","程塗過万里，身事尚孤寒。","竟日风沙急，臨秋草木殘。","何年方致主，时拂劒塵看。"]', '诗', 'shi', '', NULL, '塞下感懷 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6283bd89-92ba-44c4-8335-e5a0b2aaa225', '宿江館', '宿江館', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["江館迢遙處，知音信漸賒。","夜深鄉夢覺，窗下月明斜。","起鴈看荒草，驚波尚白沙。","那堪動鄉思，故國在天涯。"]', '["江館迢遙处，知音信漸賒。","夜深乡梦覺，窗下月明斜。","起鴈看荒草，驚波尚白沙。","那堪动乡思，故国在天涯。"]', '诗', 'shi', '', NULL, '宿江館 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a1ef92f-b5b7-4155-a827-4195b20f2d78', '早梅', '早梅', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["天然根性異，萬物盡難陪。","自古承春早，嚴冬鬬雪開。","豔寒宜雨露，香冷隔塵埃。","堪把依松竹，良塗一處栽。"]', '["天然根性異，万物尽难陪。","自古承春早，嚴冬鬬雪开。","豔寒宜雨露，香冷隔塵埃。","堪把依松竹，良塗一处栽。"]', '诗', 'shi', '', NULL, '早梅 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aa6d6ff-9b3a-43c5-b068-13a5e1c7ab9d', '夏日訪貞上人院', '夏日訪貞上人院', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["炎夏尋靈境，高僧澹蕩中。","命棊隈綠竹，盡日有清風。","流水離經閣，閑雲入梵宮。","此時祛萬慮，直似出塵籠。"]', '["炎夏尋靈境，高僧澹蕩中。","命棊隈綠竹，尽日有清风。","流水離經閣，闲云入梵宮。","此时祛万慮，直似出塵籠。"]', '诗', 'shi', '', NULL, '夏日訪貞上人院 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('723e35d0-f134-4301-bf97-c344eae72f1e', '春日旅次', '春日旅次', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["林中鶯又囀，爲客恨因循。","故里遙千里，青春過數春。","弟兄來漸少，歲月去何頻。","早晚榮歸計，中堂會所親。"]', '["林中鶯又囀，爲客恨因循。","故里遙千里，青春過數春。","弟兄来漸少，歲月去何頻。","早晚榮归計，中堂會所親。"]', '诗', 'shi', '', NULL, '春日旅次 朱慶餘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('695b9bad-19ce-4212-896c-29bf5f70e1d7', '贈至寂禪師', '贈至寂禪師', '33826d8b-2626-42f7-bcd1-c5acd8fda055', '唐', '["處世唯披衲，禪門幾歲寒。","法空無所染，性悟不多看。","竟日門長掩，相逢草自殘。","有時尋道侶，飛錫度峰巒。"]', '["处世唯披衲，禪门幾歲寒。","法空無所染，性悟不多看。","竟日门长掩，相逢草自殘。","有时尋道侶，飞錫度峰巒。"]', '诗', 'shi', '', NULL, '贈至寂禪師 朱慶餘 shi');
